# ── Global fallback logger ───────────────────────────────────────────────
# Many methods throughout this file call a bare log(...) assuming a logger
# is in scope, but no module-level log() ever existed — it only "worked"
# for call sites that happened to sit inside a function with its own local
# `def log(m): ...`. Any other call site (e.g. background-thread workers
# like _zdws_warm_batch_cache) raised NameError the first time that code
# path actually ran. This module-level log() is what Python's LEGB lookup
# now finds for every one of those bare calls, so they no longer crash.
# It's thread-safe: background threads may call this, so any UI update is
# marshalled onto the Tk main loop via .after() rather than touched directly.
_LOG_APP_REF = None   # set to the running MYIPOApp instance once it starts

def log(msg):
    try:
        print(msg)
    except Exception:
        pass
    app = _LOG_APP_REF
    if app is not None:
        try:
            app.after(0, lambda m=msg: (app.status_var.set(m)
                                         if hasattr(app, 'status_var') else None))
        except Exception:
            pass

_CACHE_DIR        = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'paa_cache')
_CACHE_PRICES_DIR = os.path.join(_CACHE_DIR, 'prices')
_CACHE_DIVS_DIR   = os.path.join(_CACHE_DIR, 'divs')
_CACHE_LIVE_DIR   = os.path.join(_CACHE_DIR, 'live')
_CACHE_ETF_DIR    = os.path.join(_CACHE_DIR, 'etf_holdings')   # alpha.102 — ETF Top Holdings Intelligence

_TTL_PRICE  = 86_400        # 1 day
_TTL_DIV    = 7 * 86_400    # 7 days
_TTL_LIVE   = 300           # 5 min
_TTL_EPS    = 86_400        # 24 hr
_TTL_ETF    = 86_400        # 24 hr — ETF top-10 holdings / sector weights change slowly

for _d in (_CACHE_DIR, _CACHE_PRICES_DIR, _CACHE_DIVS_DIR, _CACHE_LIVE_DIR, _CACHE_ETF_DIR):
    os.makedirs(_d, exist_ok=True)


def _cache_fresh(path: str, ttl: int) -> bool:
    try:    return (time_module.time() - os.path.getmtime(path)) < ttl
    except: return False

def _cache_rparquet(path: str):
    try:    return pd.read_parquet(path)
    except: return None

def _cache_wparquet(path: str, df):
    try:    df.to_parquet(path)
    except: pass

def _cache_rjson(path: str) -> dict:
    import json as _j
    try:
        with open(path, 'r', encoding='utf-8') as f: return _j.load(f)
    except: return {}

# (older _cache_wjson() removed — superseded by the holiday-aware version further below)

def _pticker(ticker: str) -> str:
    return os.path.join(_CACHE_PRICES_DIR,
                        ticker.replace('^','_').replace('/','_') + '.parquet')

def _dticker(ticker: str) -> str:
    return os.path.join(_CACHE_DIVS_DIR,
                        ticker.replace('^','_').replace('/','_') + '.parquet')

def _etfjson(ticker: str) -> str:
    safe = ''.join(ch if (ch.isalnum() or ch in '_-.') else '_' for ch in ticker.upper())
    return os.path.join(_CACHE_ETF_DIR, f'{safe}.json')

def cache_get_etf_holdings(ticker: str, ttl: int = _TTL_ETF) -> dict:
    """Return cached {'holdings': [...], 'sector_weightings': {...}} for an
    ETF ticker, or {} if stale/missing (mirrors the other live/-cache getters)."""
    p = _etfjson(ticker)
    if not _cache_fresh(p, ttl): return {}
    return _cache_rjson(p)

def cache_set_etf_holdings(ticker: str, data: dict):
    _cache_wjson(_etfjson(ticker), data)


def _ljson(key: str) -> str:
    # Symbols can carry characters that are awkward in filenames (^, =, /),
    # e.g. 'USDMYR=X'. Normalise so every cache key maps to a safe path.
    safe = ''.join(ch if (ch.isalnum() or ch in '_-.') else '_' for ch in key)
    return os.path.join(_CACHE_LIVE_DIR, f'{safe}.json')


def _smart_chunk_size(n_total: int, max_single_chunk: int = 100, min_chunk: int = 20,
                       target_chunks: int = 6) -> int:
    """Picks a bulk-download chunk size that scales with how many tickers
    actually need fetching, instead of every call site hardcoding its own
    one-size-fits-all constant:
      - A small batch (<= max_single_chunk) goes out as a single chunk —
        no point splitting a download that's already small.
      - A larger batch is split to aim for roughly `target_chunks` parallel
        requests, clamped between min_chunk and max_single_chunk so any one
        yfinance call stays within a size Yahoo's rate limiter tolerates.
    Every splash-time / bulk price fetch in the app calls this instead of
    picking its own constant, so chunk sizing stays consistent and each
    site only needs to say what its own safe ceiling/floor is.
    """
    if n_total <= 0:
        return 1
    if n_total <= max_single_chunk:
        return n_total
    size = -(-n_total // target_chunks)   # ceil division
    return max(min_chunk, min(max_single_chunk, size))


# (older cache_get_prices() removed — superseded by the holiday-aware version further below)

def cache_set_prices(ticker: str, series: 'pd.Series'):
    if series is None or series.empty: return
    _cache_wparquet(_pticker(ticker), series.rename('Close').to_frame())

def cache_get_divs(ticker: str) -> 'pd.Series | None':
    p = _dticker(ticker)
    if not _cache_fresh(p, _TTL_DIV): return None
    df = _cache_rparquet(p)
    if df is None or df.empty: return None
    col = 'Dividends' if 'Dividends' in df.columns else df.columns[0]
    s = df[col]
    return s if not s.empty else None

def cache_set_divs(ticker: str, series: 'pd.Series'):
    if series is None or series.empty: return
    _cache_wparquet(_dticker(ticker), series.rename('Dividends').to_frame())

def cache_get_live(key: str, ttl: int = _TTL_LIVE):
    p = _ljson(key)
    if not _cache_fresh(p, ttl): return None
    return _cache_rjson(p).get('v')

def cache_set_live(key: str, value):
    _cache_wjson(_ljson(key), {'v': value, 't': time_module.time()})

def cache_get_live_dict(key: str, ttl: int = _TTL_LIVE) -> dict:
    p = _ljson(key)
    if not _cache_fresh(p, ttl): return {}
    return _cache_rjson(p)

def cache_set_live_dict(key: str, data: dict):
    _cache_wjson(_ljson(key), data)

