def _strip_session_tag(ticker: str) -> str:
    """Undo _market_session_tag()'s suffix (' (P)'/' (L)'/' (M)'/' (N)'/
    ' (C)') so a displayed ticker can be used as a real lookup key again."""
    for tag in (' (P)', ' (L)', ' (M)', ' (N)', ' (C)'):
        if ticker.endswith(tag):
            return ticker[:-len(tag)]
    return ticker


def _my_tick_size(price: float) -> float:
    """Bursa Malaysia minimum tick size, by price tier (standard Bursa
    continuous-tier schedule):
      < RM1.00            -> 0.005 (0.5 sen)
      RM1.00 - RM2.99      -> 0.01  (1.0 sen)
      RM3.00 - RM4.98      -> 0.02  (2.0 sen)
      RM5.00 - RM9.95      -> 0.05  (5.0 sen)
      RM10.00 - RM24.90    -> 0.10  (10.0 sen)
      RM25.00 - RM99.75    -> 0.25  (25.0 sen)
      >= RM100.00          -> 0.50  (50.0 sen)
    """
    if price is None or price <= 0:
        return 0.0
    if price < 1.00:
        return 0.005
    elif price < 3.00:
        return 0.01
    elif price < 5.00:
        return 0.02
    elif price < 10.00:
        return 0.05
    elif price < 25.00:
        return 0.10
    elif price < 100.00:
        return 0.25
    else:
        return 0.50


def _us_tick_size(price: float) -> float:
    """US equities minimum price variation. Standard flat $0.01 for
    stocks priced >= $1.00 (sub-$1.00 stocks technically quote in
    $0.0001 increments under Reg NMS, but that's a quoting nuance).
    Unlike Bursa's schedule above, US tick size is NOT tiered by price —
    it's a flat $0.01 for virtually all normal-priced US listings."""
    if price is None or price <= 0:
        return 0.0
    return 0.0001 if price < 1.00 else 0.01


def _load_div_alert_log() -> dict:
    """Persistent log of yfinance-detected dividends that weren't found in
    the NEWPOR ledger, keyed by (ticker, iso_date) -> {'first_detected':
    ts, 'per_share':.., 'expected_amount':.., 'acknowledged': bool}.
    Survives app restarts (pickle on disk) so an entry isn't 're-noticed'
    with a fresh timestamp every single launch, and so the user has a
    running record of what's still pending vs already actioned."""
    try:
        if os.path.exists(SCA_DIV_ALERT_CACHE):
            with open(SCA_DIV_ALERT_CACHE, 'rb') as f:
                data = pickle.load(f)
                if isinstance(data, dict):
                    return data
    except Exception:
        pass
    return {}


def _save_div_alert_log(log: dict):
    try:
        with open(SCA_DIV_ALERT_CACHE, 'wb') as f:
            pickle.dump(log, f)
    except Exception:
        pass
