        def _make_section(parent, title, labels, accent='#555'):
            labels = list(labels)
            open_var = tk.BooleanVar(
                value=any(self.check_vars[l].get() for l in labels if l in self.check_vars))
            self._accordion_open[title] = open_var
            slot = tk.Frame(parent, bg='#161b22')          # fixed position in the sidebar
            slot.pack(fill='x')
            hdr = tk.Frame(slot, bg='#1e252d', cursor='hand2')
            arrow_var = tk.StringVar(value='▾')
            tk.Label(hdr, textvariable=arrow_var, bg='#1e252d', fg=accent,
                     font=('Segoe UI', 8)).pack(side='left', padx=(6, 2))
            tk.Label(hdr, text=f'{title}  ({len(labels)})', bg='#1e252d', fg=accent,
                     font=('Segoe UI', 8, 'bold')).pack(side='left')
            body = tk.Frame(slot, bg='#161b22')
            rows = []
            for lbl in labels:
                rows.append((lbl, self._make_checkbox(body, lbl)))
            sec = {'title': title, 'hdr': hdr, 'body': body, 'arrow': arrow_var,
                   'open': open_var, 'rows': rows}
            self._index_sections.append(sec)
            def _toggle(event=None, v=open_var):
                v.set(not v.get())
                self._filter_index_list()
            for w in [hdr] + list(hdr.winfo_children()):
                w.bind('<Button-1>', _toggle)
            self._filter_index_list()
            return body

