        def _refresh_cr_labels():
            eng = getattr(self, '_v2_engine', None)
            dash = eng.pages.get('Dashboard') if eng is not None else None
            if dash is not None and hasattr(dash, '_update_cr_balance_labels'):
                dash._update_cr_balance_labels()

        def _toggle_row(label, options, current, on_pick):
            row = tk.Frame(disp_box, bg='#161b22'); row.pack(fill='x', pady=(8, 0))
            tk.Label(row, text=label, font=("Segoe UI", 8), fg='#8b949e',
                     bg='#161b22').pack(anchor='w')
            btns = {}
            bar = tk.Frame(row, bg='#161b22'); bar.pack(anchor='w', pady=(3, 0))
