        self.ptor_banner_frame = tk.Frame(summary_row, bg='#101820',
                                           highlightbackground='#30363d', highlightthickness=1)
        self.ptor_banner_frame.pack(side='right', padx=(6, 12), pady=6)
        tk.Label(self.ptor_banner_frame, text='📐 PtoR RATING', font=('Courier New', 7, 'bold'),
                 fg='#888', bg='#101820').pack(anchor='center', padx=10, pady=(4, 0))
        self.ptor_banner_var = tk.StringVar(value='')
