    # Marquee-only major FX crosses — deliberately NOT part of WORLD_INDICES,
    # since that table drives index matching/ZDWS/ZDOS elsewhere and these
    # are currency pairs, not indices. (sym, label, yahoo_sym)
    MAJOR_FX_PAIRS = [
        ('FXM:EURUSD', 'EUR/USD', 'EURUSD=X'),
        ('FXM:GBPUSD', 'GBP/USD', 'GBPUSD=X'),
        ('FXM:USDCAD', 'USD/CAD', 'USDCAD=X'),
        ('FXM:USDSGD', 'USD/SGD', 'USDSGD=X'),
        ('FXM:USDJPY', 'USD/JPY', 'USDJPY=X'),
        ('FXM:AUDUSD', 'AUD/USD', 'AUDUSD=X'),
        ('FXM:NZDUSD', 'NZD/USD', 'NZDUSD=X'),
    ]
    # Low-value currencies shown per-N-units on the marquee (e.g. "100JPY=")
    # instead of the raw per-1-unit rate, which would round to ~0.0000.
    _FX_DISPLAY_SCALE = {'JPY': 100, 'KRW': 1000, 'IDR': 10000}
    # Currencies people want an MYR pair for even without a matching index —
    # AUD/MYR now comes free via the ASX indices above; THB/MYR (common for
    # Malaysians saving/accumulating toward a Thailand trip) has no index of
    # its own, so it's added here explicitly.
    _EXTRA_FX_CCYS = ('THB', 'AUD', 'IDR')

    def _fx_display_label(self, ccy: str) -> str:
        scale = self._FX_DISPLAY_SCALE.get(ccy)
        if not scale:
            return f'{ccy}MYR'
        n = f'{scale // 1000}K' if scale >= 1000 else str(scale)
        return f'{n}{ccy}='

    def _fx_ccys(self) -> list:
        """All currencies that get an MYR marquee line: every WORLD_INDICES
        currency plus the explicit travel-savings extras (THB etc.)."""
        return sorted({c for _, _, c in self.WORLD_INDICES if c != 'MYR'}
                      | set(self._EXTRA_FX_CCYS))

