# ── K-ID auth helpers ────────────────────────────────────────────────────────
import hashlib as _hashlib

def kid_hash_pin(username: str, pin: str) -> str:
    """Salted SHA-256 of a PIN. Salt = lowercased username, so the same PIN
    under different usernames produces different hashes."""
    salt = username.strip().lower()
    return _hashlib.sha256(f'{salt}::{pin}'.encode('utf-8')).hexdigest()


def kid_find_account(settings: dict, username: str):
    """Return the account dict for a username (case-insensitive), or None."""
    u = username.strip().lower()
    for acc in settings.get('kid_accounts', []):
        if acc.get('username', '').strip().lower() == u:
            return acc
    return None


ADMIN_KID = 'admin1'   # reserved administrator K-ID
TEST_KID  = 'test1'    # reserved test K-ID — both admin1 and test1 belong to
                        # the developer for testing; quick-switch skips the
                        # PIN screen between just these two.
# Default admin PIN is 0000 — stored as its salted hash (sha256('admin1::0000')),
# overridable by settings['admin_pw_hash'] if the admin ever changes it.
ADMIN_DEFAULT_PIN_HASH = '4cc5c192af04c46d777fc80c005df5f8baac04a4db8b9e3350f64a465376cd76'

def kid_verify(settings: dict, username: str, pin: str) -> bool:
    u = username.strip().lower()
    # ── Admin account: PIN checked against settings['admin_pw_hash'] when
    # set, else the baked-in default PIN 0000. (The old 6-char minimum was
    # what silently blocked admin1 logins with the 4-digit PIN — removed.)
    if u == ADMIN_KID:
        if not pin:
            return False
        stored = settings.get('admin_pw_hash', '') or ADMIN_DEFAULT_PIN_HASH
        return stored == kid_hash_pin(ADMIN_KID, pin)
    acc = kid_find_account(settings, username)
    if not acc:
        return False
    return acc.get('pin_hash') == kid_hash_pin(username, pin)


_EMAIL_RE = re.compile(r'^[^@\s]+@[^@\s]+\.[^@\s]+$')

def kid_valid_email(email: str) -> bool:
    """Loose but sane email-shape check — good enough to catch typos
    without pretending to do real deliverability validation."""
    return bool(_EMAIL_RE.match((email or '').strip()))


def kid_get_email(settings: dict, username: str) -> str:
    """Return the stored email for a K-ID, or '' if none is on file."""
    acc = kid_find_account(settings, username)
    return (acc or {}).get('email', '')


def kid_set_email(settings: dict, username: str, email: str) -> tuple:
    """Attach/replace the email on file for an existing K-ID.
    Returns (ok: bool, message: str)."""
    email = (email or '').strip()
    if email and not kid_valid_email(email):
        return False, 'That doesn\'t look like a valid email address.'
    acc = kid_find_account(settings, username)
    if not acc:
        return False, f'K-ID "{username}" not found.'
    acc['email'] = email
    save_app_settings(settings)
    return True, 'Email saved.'


def kid_create(settings: dict, username: str, pin: str, email: str = '') -> tuple:
    """Create a new K-ID. Email is optional — pass '' to skip it, or a
    string to link it to this K-ID from the start. Returns (ok, message)."""
    u = username.strip()
    if 'admin' in u.strip().lower():
        return False, ('Usernames containing "admin" are reserved. Email '
                        'yapwc2838@gmail.com — Subject: request for Admin Account.')
    if len(u) < 3:
        return False, 'Username must be at least 3 characters.'
    if not u.replace('_', '').replace('-', '').isalnum():
        return False, 'Username may only contain letters, numbers, - and _.'
    if kid_find_account(settings, u):
        return False, f'K-ID "{u}" already exists.'
    if not (pin.isdigit() and 4 <= len(pin) <= 8):
        return False, 'PIN must be 4–8 digits.'
    email = (email or '').strip()
    if email and not kid_valid_email(email):
        return False, 'That doesn\'t look like a valid email address.'
    import datetime as _d
    settings.setdefault('kid_accounts', []).append({
        'username': u,
        'pin_hash': kid_hash_pin(u, pin),
        'email':    email,   # '' if skipped — can be added later via kid_set_email
        'created':  _d.date.today().strftime('%Y-%m-%d'),
    })
    return True, f'K-ID "{u}" created.'


# ── OPIE popup chat ───────────────────────────────────────────────────────────
# Stays idle until "Hi, Opie" is typed. Once activated it greets the user,
# resolves a display name (K-ID or a one-time custom alias), and then
# understands two keyword intents:
#   "change"   → lists current portfolio positions, then asks which stock
#                the user wants details on (shares / value / gain / %).
#   "how much" → full summary (value + unrealized %) converted into
#                whichever currency the user names, defaulting to the
#                portfolio's own base currency.
_OPIE_GREETINGS  = ('hi opie', 'hello opie', 'hey opie', 'opie', 'hi opie summary',
                    'hiya opie', 'yo opie', 'sup opie', 'morning opie', 'ok opie',
                    'hi', 'hello', 'hey')

_OPIE_QUESTION_WORDS = ('what', 'whats', "what's", 'how', 'hows', "how's", 'when',
                        'where', 'why', 'who', 'which', 'is', 'are', 'am', 'do',
                        'does', 'did', 'can', 'could', 'would', 'should', 'will')


def _opie_is_question(text: str) -> bool:
    """A loose interrogative-sentence check — a literal '?' or a leading
    question word — used so a genuine question that missed every keyword
    still gets a human, curious reply instead of a flat command dump."""
    low = text.lower().strip()
    if not low:
        return False
    if '?' in low:
        return True
    first_word = low.split(' ', 1)[0].strip(",.!")
    return first_word in _OPIE_QUESTION_WORDS
# Filler words that carry no ticker/index identity — stripped globally before
# matching a query against tickers or index names so "AAPL now", "KLCI today",
# "current price of TSLA" etc. all resolve the same as the bare name.
_OPIE_TIME_WORDS = {
    'NOW', 'TODAY', 'CURRENT', 'CURRENTLY', 'LATEST', 'RIGHT', 'MOMENT',
    'RECENT', 'RECENTLY', 'REALTIME', 'LIVE', 'TONIGHT', 'THISMORNING',
}
_OPIE_CCY_TOKENS = {
    'RM': 'MYR', 'MYR': 'MYR', 'RINGGIT': 'MYR',
    'USD': 'USD', 'US$': 'USD', 'DOLLARS': 'USD', 'DOLLAR': 'USD',
    'SGD': 'SGD', 'SG$': 'SGD', 'SINGDOLLAR': 'SGD',
    'HKD': 'HKD', 'HK$': 'HKD', 'HONGKONGDOLLAR': 'HKD',
    'EUR': 'EUR', 'EURO': 'EUR',
    'GBP': 'GBP', 'POUND': 'GBP', 'STERLING': 'GBP',
    'JPY': 'JPY', 'YEN': 'JPY',
    'KRW': 'KRW', 'WON': 'KRW',
}


def _opie_infer_ccy(ticker: str) -> str:
    """Currency implied by a ticker's exchange suffix, via the app's own
    MARKET_SPEC registry (.KL→MYR, .HK→HKD, .SI→SGD, ...). A bare ticker
    with no recognized suffix follows the app-wide convention of USD —
    adding a new market to MARKET_SPEC is all that's needed for OPIE to
    pick it up automatically."""
    t = (ticker or '').upper()
    best_ccy, best_len = None, 0
    for ccy, spec in MARKET_SPEC.items():
        suf = spec.get('suffix', '')
        if suf and t.endswith(suf) and len(suf) > best_len:
            best_ccy, best_len = ccy, len(suf)
    return best_ccy or 'USD'


def _opie_suffix_variants(ticker: str):
    """Every plausible fully-qualified ticker to try for a bare code typed
    without an exchange suffix — one per market in MARKET_SPEC (.KL, .HK,
    .SI, bare-USD, ...) plus the ticker exactly as typed. Registering a new
    market in MARKET_SPEC (e.g. Tokyo's .T) is all OPIE needs to start
    resolving it too — nothing here has to change."""
    t = (ticker or '').upper().strip()
    if not t:
        return []
    if '.' in t:
        return [t]
    variants = [t]
    for spec in MARKET_SPEC.values():
        suf = spec.get('suffix', '')
        if suf:
            variants.append(t + suf)
    return variants
# Generic filler words that show up around a ticker/index name in a natural
# question ("can you tell me about stock price of X", "what's X worth") —
# stripped before candidate extraction so they never get mistaken for the
# ticker itself (e.g. "ABOUT" was previously picked as a fake ticker).
_OPIE_STOPWORDS = {
    'A', 'AN', 'THE', 'IS', 'ARE', 'OF', 'FOR', 'TO', 'IN', 'ON', 'AT', 'AS',
    'AND', 'OR', 'ME', 'MY', 'I', 'YOU', 'YOUR', 'CAN', 'COULD', 'WOULD',
    'WILL', 'TELL', 'SHOW', 'GIVE', 'KNOW', 'WANT', 'ABOUT', 'WHAT', 'WHATS',
    "WHAT'S", 'WHICH', 'DO', 'DOES', 'STOCK', 'STOCKS', 'PRICE', 'PRICES',
    'PLEASE', 'PORTFOLIO', 'LIKE', 'THIS', 'THAT', 'HOW', 'MUCH', 'VALUE',
    'WORTH', 'IT', "IT'S", 'ITS',
} | _OPIE_TIME_WORDS


def _opie_ticker_candidates(text: str):
    """Tokens from free text that could plausibly be a ticker/index name —
    filler words stripped, but internal '.' and '-' (e.g. '5398.KL') kept
    so real tickers survive instead of being rejected by a plain isalnum
    check."""
    out = []
    for raw in text.split():
        w = raw.strip('.,!?;:()').upper()
        if not w or w in _OPIE_STOPWORDS:
            continue
        if not all(c.isalnum() or c in '.-' for c in w):
            continue
        out.append(w)
    return out


def _opie_best_candidate(candidates):
    """Prefer the most ticker-like token (contains a '.' or mixes letters
    and digits, e.g. '5398.KL' or 'AAPL2'); otherwise fall back to the last
    remaining candidate, since that's usually the one actually being asked
    about ("...tell me about 5347.KL")."""
    if not candidates:
        return None
    for w in reversed(candidates):
        if '.' in w or (any(c.isalpha() for c in w) and any(c.isdigit() for c in w)):
            return w
    return candidates[-1]


def _opie_match_portfolio_ticker(host, text: str):
    """Match free text against actual portfolio holdings — exact ticker
    match first, then loose substring match ignoring punctuation. Returns
    (ticker, item, base_ccy) or None."""
    candidates = _opie_ticker_candidates(text)
    if not candidates:
        return None
    portfolios = _opie_extract_portfolios(host)
    holdings = []
    for port in portfolios.values():
        ccy = port.get('base_currency', 'USD')
        for ticker, item in port.get('holdings', {}).items():
            if item.get('_is_cash'):
                continue
            shares = item.get('shares', 0)
            if not shares or shares <= 0:
                continue
            holdings.append((ticker, item, ccy))
    for cand in candidates:
        for ticker, item, ccy in holdings:
            if cand == ticker.upper():
                return ticker, item, ccy
    for cand in candidates:
        cand_bare = cand.replace('.', '').replace('-', '')
        for ticker, item, ccy in holdings:
            t_bare = ticker.upper().replace('.', '').replace('-', '')
            if cand_bare and (cand_bare == t_bare or cand in ticker.upper() or ticker.upper() in cand):
                return ticker, item, ccy
    return None


def _opie_extract_portfolios(host) -> dict:
    return getattr(host, '_portfolios', None) or getattr(host, 'newpor_portfolios', None) or {}


def _opie_extract_fx(host) -> dict:
    return getattr(host, '_fx_rates', None) or {get_home_currency(): 1.0}


def _opie_extract_prices(host) -> dict:
    return getattr(host, '_last_price_data', None) or {}


def _build_portfolio_summary_text(host, ccy: str = 'MYR') -> str:
    """Standalone whole-portfolio summary (value, P/L, recent buys) usable
    outside a chat session — shared by Opie's 'summary' answer and the
    scheduled/on-open auto-summary popup."""
    portfolios = _opie_extract_portfolios(host)
    if not portfolios:
        return 'No portfolio loaded yet.'
    fx     = _opie_extract_fx(host)
    prices = _opie_extract_prices(host)

    def _to_ccy(amount, c):
        if c == ccy:
            return amount
        myr = amount if c == 'MYR' else amount * fx.get(c, 1.0)
        if ccy == 'MYR':
            return myr
        rate = fx.get(ccy)
        return (myr / rate) if rate else amount

    cost_total, mv_total, positions = 0.0, 0.0, 0
    all_buys = []
    for port in portfolios.values():
        p_ccy = port.get('base_currency', 'USD')
        for ticker, item in port.get('holdings', {}).items():
            if item.get('_is_cash'):
                continue
            shares = item.get('shares', 0)
            if not shares or shares <= 0:
                continue
            positions += 1
            cost_total += _to_ccy(item.get('cost_value', 0.0), p_ccy)
            price = prices.get(ticker)
            mv = shares * price if price else item.get('cost_value', 0.0)
            mv_total += _to_ccy(mv, p_ccy)
            for t in item.get('transactions', []):
                if t[0] == 'buy':
                    all_buys.append((ticker, t))
    gain = mv_total - cost_total
    pct  = (gain / cost_total * 100) if cost_total > 0 else 0.0
    prefix = 'RM' if ccy == 'MYR' else f'{ccy} '
    recent_buys = sorted(all_buys, key=lambda x: x[1][1], reverse=True)[:5]
    buys_txt = '\n'.join(f'  • {tk}  +{t[2]:g} @ {t[3]:,.4f}  ({t[1]})' for tk, t in recent_buys) \
               or '  (none on record)'
    return (f'Portfolio summary ({ccy})\n'
            f'{positions} position(s)  ·  value {prefix}{mv_total:,.2f}  ·  '
            f'unrealized {prefix}{gain:+,.2f} ({pct:+.2f}%)\n\n'
            f'Recently bought:\n{buys_txt}')


def _maybe_show_scheduled_summary(sca_window):
    """Checked once per SCAWindow open. Respects a per-K-ID setting
    (configurable via Opie: 'set summary on open' / 'set summary time
    9:00am' / 'turn off summary schedule') for whether/when to pop up an
    automatic portfolio summary — either every time the app opens, or once
    per day at/after a fixed time."""
    import datetime as _dt
    kid = globals().get('CURRENT_KID') or ''
    if not kid:
        return
    settings = load_app_settings()
    prefs = settings.get('opie_summary_prefs', {}).get(kid.lower(), {})
    mode  = prefs.get('schedule_mode', 'off')
    if mode == 'off':
        return
    today = _dt.date.today().isoformat()
    if prefs.get('last_shown_date') == today:
        return
    if mode == 'fixed_time':
        fixed = prefs.get('fixed_time', '09:00')
        try:
            h, m = (int(x) for x in fixed.split(':'))
        except Exception:
            h, m = 9, 0
        now = _dt.datetime.now()
        if now < now.replace(hour=h, minute=m, second=0, microsecond=0):
            return
    elif mode != 'on_open':
        return

    ccy = prefs.get('currency', 'MYR')
    text = _build_portfolio_summary_text(sca_window, ccy)
    prefs['last_shown_date'] = today
    settings.setdefault('opie_summary_prefs', {})[kid.lower()] = prefs
    save_app_settings(settings)

    pop = tk.Toplevel(sca_window)
    pop.title('📋 Your Portfolio Summary')
    pop.configure(bg='#0a0e1a')
    pop.geometry('440x320')
    tk.Label(pop, text=text, font=('Courier New', 9), fg='#e2e8f0',
             bg='#0a0e1a', justify='left', anchor='nw', wraplength=410,
             padx=14, pady=14).pack(fill='both', expand=True)
    tk.Button(pop, text='Close', command=pop.destroy, bg='#1a2035',
              fg='#00b4d8', relief='flat', padx=10).pack(pady=(0, 10))


def _opie_extract_mkt_data(host) -> dict:
    """Live index/FX snapshot lives on the dashboard (MYIPOApp); SCAWindow's
    host needs to hop up to its master to find it."""
    data = getattr(host, '_mkt_data', None)
    if data:
        return data
    master = getattr(host, 'master', None)
    return getattr(master, '_mkt_data', None) or {}


def _opie_dashboard_app(host):
    """Resolve up to the MYIPOApp dashboard instance, which is where
    all_frames (every index/fund NAV series) and _calc_fund_return live —
    SCAWindow's host needs to hop up to its master to find it."""
    if hasattr(host, 'all_frames'):
        return host
    master = getattr(host, 'master', None)
    if master is not None and hasattr(master, 'all_frames'):
        return master
    return host


def _opie_fund_catalog(host):
    """List of (label, ccy) for every fund OPIE can look up — both
    unit-trust FUND_LABELS (always MYR) and VFund/Enhanced-Yield CEFs
    (MYR or USD, per VFUND_CONFIG)."""
    out = [(lbl, 'MYR') for lbl in FUND_LABELS]
    out += [(vf['label'], vf['ccy']) for vf in VFUND_CONFIG]
    return out


_OPIE_MYIPO_INDEX_LABELS = tuple(
    lbl for lbl in ALL_INDEX_LABELS
    if lbl not in FUND_LABELS and lbl not in VFUND_LABELS
)
# ^ Built straight from ALL_INDEX_LABELS (the same master list the chart's
#   own line-style/legend machinery uses) rather than a separate hand-typed
#   tuple, so OPIE can never again drift out of sync and go quiet on an
#   index that exists elsewhere in the app — every Core/Y-Series/TR-Series/
#   Top-N (+PW twins)/Champions-Kings-Gem-Diva/BBI30/Swinger/Never-Break/
#   Annual Winners+Losers index is automatically included, present or
#   future. Fund labels are excluded here since OPIE looks those up
#   through _opie_fund_catalog instead.


def _opie_index_catalog(host):
    """List of (symbol, display name, currency) for every index OPIE can
    look up — the Bursa benchmark, every world index the dashboard already
    tracks, and the full internal MYIPO+ index family (marked with the
    'internal' symbol tag so _say_index_value knows to read it straight
    out of all_frames instead of the live world-index mkt-data snapshot)."""
    app = host if hasattr(host, 'WORLD_INDICES') else getattr(host, 'master', None)
    world = list(getattr(app, 'WORLD_INDICES', []) or [])
    myipo = [('internal', lbl, 'MYR')
             for lbl in _OPIE_MYIPO_INDEX_LABELS
             if lbl in getattr(app, 'all_frames', {})]
    return [('^KLSE', 'FBM KLCI', 'MYR')] + world + myipo


def _opie_index_guide_lookup(app, display_name: str):
    """Map an index's OPIE catalog display name (e.g. 'FBM KLCI',
    'MYIPO+ Top 10') to a plain-English write-up, checking two sources:

    1. _MYIPO_INDEX_GUIDE (dashboard's short guide, keyed on the bare
       label — 'KLCI', 'Top 10' — used for KLCI and the handful of
       entries it covers).
    2. _index_description(label) — the FULL, authoritative generator
       used for the ⓘ hover in the main index checklist. It's built
       straight from the same config tuples that define each series
       (YSERIES_CONFIG, core_notes, top_notes incl. Champions 50 /
       Kings 10 / Gem 20 / Diva 20 / BBI30 / Swinger / NeverBreak /
       Annual Winners+Losers / Dynamic365 / Top-N PW twins), so it
       can't drift out of sync and already covers names the shorter
       guide dict doesn't.

    Returns None — not a KeyError — only if neither source has
    anything, so callers can still fall back gracefully."""
    guide = getattr(app, '_MYIPO_INDEX_GUIDE', {}) or {}
    bare_key = display_name
    if bare_key == 'FBM KLCI':
        bare_key = 'KLCI'
    elif bare_key.startswith('MYIPO+ '):
        bare_key = bare_key[len('MYIPO+ '):]
    text = guide.get(bare_key)
    if text:
        return text

    describe = getattr(app, '_index_description', None)
    if callable(describe):
        try:
            text = describe(display_name)
        except Exception:
            text = ''
        if text:
            return text

    return None


def _opie_parse_currency(text: str):
    """Best-effort currency code detected in free text, or None."""
    t = text.upper()
    for token, code in _OPIE_CCY_TOKENS.items():
        if token in t:
            return code
    return None


# ── ETF Top Holdings Intelligence (alpha.102) ────────────────────────────────
# Feature 1 (Top 10 Holdings) + Feature 2 (Opie Smart Summary) from the
# ETF Top Holdings Intelligence proposal, reached through the existing OPIE
# chatbox (Feature 3 — no separate window/module; OPIE is currently disabled
# as a full AI agent, so the "summary" is generated by a local, deterministic
# rule engine reusing the same disk-cache pattern as the rest of the app).
_OPIE_ETF_KEYWORDS = ('top holding', 'top 10 holding', 'holdings', 'etf summary',
                      'etf holdings', 'etf breakdown')

# 'full holdings' / 'all holdings' / NPORT-P — SEC-sourced complete list,
# not just Top-10. Checked BEFORE _OPIE_ETF_KEYWORDS since 'holdings' alone
# would otherwise steal it (same precedence trick as _OPIE_INDIRECT_KEYWORDS
# above). US-listed ETFs/funds only — see _is_us_listed_etf().
_OPIE_FULL_HOLDINGS_KEYWORDS = ('full holdings', 'all holdings', 'complete holdings',
                                'entire holdings', 'nport', 'full breakdown',
                                'every holding', 'full etf holdings')

# 'indirect exposure' / 'look-through' — SCAIE's own keyword set, checked
# BEFORE _OPIE_ETF_KEYWORDS below since 'holdings' would otherwise steal it.
_OPIE_INDIRECT_KEYWORDS = ('indirect exposure', 'indirect', 'look-through',
                           'look through', 'looks through', 'exposure to',
                           'exposed to', 'scaie', 'total exposure')
_OPIE_FALLERS_KEYWORDS  = ('biggest faller', 'biggest fallers', 'fell so much',
                           'fell the most', 'falling the most', 'who fell',
                           'what fell', 'worst performer', 'worst performers',
                           'dropped the most', 'down the most', 'declining the most',
                           'biggest crasher', 'crashed the most', 'crashing')
_OPIE_UPPERS_KEYWORDS   = ('biggest upper', 'biggest uppers', 'biggest gainer',
                           'biggest gainers', 'rose the most', 'rising the most',
                           'who rose', 'what rose', 'best performer', 'best performers',
                           'up the most', 'gained the most', 'climbing the most',
                           'shot up', 'surged')

# ── Broadened intent patterns ────────────────────────────────────────────
# Each of these started as a single keyword; expanded with the natural
# synonyms/phrasings a person would actually type instead of the exact
# command word, so OPIE recognizes the *intent* behind ~100 plausible ways
# to ask, not just one hardcoded phrase per topic.
_OPIE_RE_TREND    = re.compile(r'\btrend(ed|ing|s)?\b|\bperform(ed|ance|ing)?\b|'
                                r'\bhow.*(done|doing|been doing)\b|\bover time\b|'
                                r'\bhistorical(ly)?\b|\btrajectory\b|\bmomentum\b')
_OPIE_RE_SUMMARY  = re.compile(r'\bsummary\b|\boverview\b|\brecap\b|\breview\b|'
                                r'\bhow.*(am i doing|is my portfolio|are my (investments|holdings))\b|'
                                r'\bportfolio (health|status)\b|\bhow.*i.*doing\b|'
                                r'\bwrap.?up\b|\bstate of my portfolio\b')
_OPIE_RE_AVGCOST  = re.compile(r'\b(avg|average)\s*cost\b|\bbreak.?even\b|'
                                r'\bcost\s*basis\b|\bpurchase price\b|\bentry price\b|'
                                r'\bbought at\b|\bbuy.?in price\b|\bwhat did i pay\b')
_OPIE_RE_WEIGHT   = re.compile(r'\b(weight|allocation|concentration)\b|'
                                r'\b(%|percent(age)?|proportion|portion|share)\s*(of)?\s*(my)?\s*portfolio\b|'
                                r'\bhow much of my portfolio\b|\bhow big (a|is my) (position|stake|slice)\b')
_OPIE_RE_HOLD_RPT = re.compile(r'\b(holdings?|position)\b.*\b(report|detail|ledger|popup|history|transactions?)\b|'
                                r'\b(report|detail|ledger|popup|history|transactions?)\b.*\b(holdings?|position)\b')
_OPIE_RE_DIVIDEND = re.compile(r'\bdividend[s]?\b|\bdiv\s*(income|received|paid|payout|log)\b|'
                                r'\bpayout[s]?\b|\bhow much.*(dividend|div\b)|\bdividend.*(receiv|paid|log)\b')
_OPIE_RE_FUND     = re.compile(r'\bfund[s]?\b|\bunit trust[s]?\b|\bcef[s]?\b|\bnav\b')
_OPIE_RE_CHANGE   = re.compile(r'\bchange[ds]?\b|\bmov(ed|ing|es|ement)\b|\bup or down\b|'
                                r'\bgain(ed)? or loss\b|\bperforming today\b|\bhow.*(today|so far)\b')
_OPIE_RE_PRICE    = re.compile(r'\bprices?\b|\bworth\b|\btrading at\b|\bquote[d]?\b|'
                                r'\bcurrent(ly)? (value|value of|trading)\b|\bwhat.?s.*(worth|trading)\b')
_OPIE_RE_INDEX    = re.compile(r'\b(index|indexes|indices|benchmark)\b|\bmarket level\b')
_OPIE_RE_DEFINE   = re.compile(r'\bwhat(\'?s| is| does| are)\b.*\b(mean|means)\b|'
                                r'\b(explain|define|definition|meaning of)\b|'
                                r'\bwhat is\b(?!.*\b(worth|trading|value|price|level|at|now)\b)|'
                                r'\btell me about\b')


def _opie_fetch_underlying_day_change(symbols: list, limit: int = 20) -> dict:
    """Day-change % for a batch of underlying tickers — used by SCAIE's
    'Biggest Fallers' view. Capped at `limit` symbols (called with the
    top-exposure underlyings already sliced) since this is a per-symbol
    2-day history fetch, not a cached bulk lookup like the ETFs themselves."""
    out = {}
    for sym in symbols[:limit]:
        try:
            hist = yf.Ticker(sym).history(period='5d')
            closes = hist['Close'].dropna()
            if len(closes) >= 2:
                out[sym] = (closes.iloc[-1] / closes.iloc[-2] - 1) * 100
        except Exception:
            continue
    return out


def _opie_merge_etf_holdings(ticker: str) -> list:
    """Combines BOTH sources for one ETF instead of either/or:
      - yfinance's Top-10 (funds_data, live-priced weights) for the
        biggest positions
      - EDGAR/SEC's NPORT-P full list for everything AFTER position #10
        (yfinance only ever exposes 10; EDGAR has the rest, just at a
        ~60-day filing lag rather than live)
    yfinance symbols take priority for the top slice since their weights
    reflect current pricing; anything from EDGAR whose symbol already
    appears in the yfinance top-10 is skipped so a name isn't double
    counted. Returns a combined holdings list (each item has 'symbol',
    'name', 'pct')."""
    ticker = _resolve_ticker_alias((ticker or '').upper().strip())
    if not ticker:
        return []

    top10_data = _opie_fetch_etf_holdings(ticker)
    top10 = top10_data.get('holdings') or []
    top10_syms = {(h.get('symbol') or '?') for h in top10}

    full_data = _opie_fetch_etf_full_holdings(ticker)
    full_holdings = full_data.get('holdings') if not full_data.get('error') else []
    full_holdings = full_holdings or []

    # EDGAR's list is already sorted by value descending — everything not
    # already covered by the yfinance top-10 is the "after top 10" slice.
    beyond_top10 = [h for h in full_holdings if (h.get('symbol') or '?') not in top10_syms]

    return top10 + beyond_top10


def _prefetch_sca_ie_holdings(portfolios: dict, log_cb=None, chunk_size: int = None):
    """
    SCAIE pre-fetch: warms _opie_fetch_etf_holdings (yfinance Top-10, cached
    via cache_get/set_etf_holdings) AND _opie_fetch_etf_full_holdings (EDGAR
    NPORT-P full list, cached via _ETF_FULL_HOLDINGS_CACHE) for every
    US-market ticker held, IN CHUNKS, on the Splashscreen — before the
    'SCAIE' button is ever clicked.

    This is what _open_sca_ie -> _opie_compute_indirect_exposure ->
    _opie_merge_etf_holdings would otherwise do live, synchronously, on the
    Tk main thread the first time someone opens SCAIE — one or more blocking
    EDGAR/yfinance round-trips per ETF held, which is exactly why that
    window used to take a long time to open and made the whole app appear
    to hang/lag while it did. Warming both caches here means SCAIE's own
    fetch calls are cache hits and the window renders instantly.

    Mirrors _prefetch_sca_dividends' chunk/log_cb pattern so this shows up
    on the Splashscreen progress bar exactly like every other prefetch pass
    (chunk messages already match the '...chunk...' progress-bar trigger in
    SplashScreen._log).
    """
    def log(m):
        if log_cb: log_cb(m)

    seen    = set()
    tickers = []
    for port in (portfolios or {}).values():
        if port.get('base_currency') != 'USD':
            continue   # US-only, same gate as _opie_compute_indirect_exposure
        for ticker, item in port.get('holdings', {}).items():
            if item.get('_is_cash') or item.get('market') != 'US':
                continue
            shares = item.get('shares', 0)
            if not shares or shares <= 0 or ticker in seen:
                continue
            seen.add(ticker)
            tickers.append(ticker)

    if not tickers:
        return

    if chunk_size is None:
        chunk_size = _smart_chunk_size(len(tickers), max_single_chunk=10,
                                        min_chunk=1, target_chunks=10)

    log(f'⬇  [SCAIE] Pre-fetching ETF holdings for {len(tickers)} US ticker(s)…')

    from concurrent.futures import ThreadPoolExecutor, as_completed as _ac

    def _fetch_one(ticker):
        try:
            _opie_fetch_etf_holdings(ticker)        # yfinance Top-10 (cached)
            _opie_fetch_etf_full_holdings(ticker)    # EDGAR full list (cached)
            return ticker, 'ok'
        except Exception as e:
            return ticker, f'error: {e}'

    total   = len(tickers)
    done    = 0
    chunks  = [tickers[i:i + chunk_size] for i in range(0, total, chunk_size)]
    for ci, chunk in enumerate(chunks, 1):
        with ThreadPoolExecutor(max_workers=min(6, len(chunk))) as ex:
            futs = {ex.submit(_fetch_one, t): t for t in chunk}
            for fut in _ac(futs):
                fut.result()
                done += 1
        log(f'⬇  [SCAIE] Downloading chunk {ci}/{len(chunks)} '
            f'({done}/{total} tickers)…')

    log(f'✅  [SCAIE] {total} ticker(s) warmed — SCAIE will open instantly.')


def _opie_compute_indirect_exposure(portfolios: dict, price_data: dict):
    """Shared engine behind SCAIE and OPIE's 'indirect exposure' chat answer.
    US-market ETFs/funds only. Returns (exposure, etfs_used, etf_mv_total)
    where exposure maps underlying symbol -> {'name', 'value', 'via': set()}.
    """
    exposure: dict = {}
    etf_mv_total = 0.0
    etfs_used = []
    for port in (portfolios or {}).values():
        if port.get('base_currency') != 'USD':
            continue   # US-only for now
        for ticker, item in port.get('holdings', {}).items():
            if item.get('_is_cash') or item.get('market') != 'US':
                continue
            shares = item.get('shares', 0)
            if not shares or shares <= 0:
                continue
            price = price_data.get(ticker)
            if not price:
                continue
            mv = shares * price

            # Both sides combined, not either/or: yfinance's Top-10 (live
            # weights) plus everything EDGAR's NPORT-P filing has beyond
            # position #10. See _opie_merge_etf_holdings for the merge
            # logic and why the two sources don't get double-counted.
            holdings = _opie_merge_etf_holdings(ticker)
            if not holdings:
                continue
            etf_mv_total += mv
            etfs_used.append(ticker)
            for h in holdings:
                sym = h.get('symbol', '?') or '?'
                pct = h.get('pct', 0.0) or 0.0
                val = mv * (pct / 100.0)
                rec = exposure.setdefault(sym, {'name': h.get('name', sym),
                                                 'value': 0.0, 'via': set()})
                rec['value'] += val
                rec['via'].add(ticker)
    return exposure, etfs_used, etf_mv_total




def _opie_format_indirect_exposure_summary(exposure: dict, etfs_used: list,
                                            etf_mv_total: float) -> str:
    """Total-exposure mode — a short, human read-out instead of the full
    table. NOT a repeat of the underlying-exposure list (Detail already
    shows every holding, unlimited, scrollable) — this is deliberately
    just the headline totals plus today's top movements, ranked by $
    IMPACT (exposure x %chg, tick-size logic) same as SCAIE's own
    Fallers/Uppers toggles, top 10 only."""
    if not etfs_used:
        return ("You're not holding any US ETFs/funds I can look through right "
                 "now — no indirect exposure to report.")
    ranked = sorted(exposure.items(), key=lambda kv: kv[1]['value'], reverse=True)
    lines = [
        f"Across {len(etfs_used)} ETF(s) you hold ({', '.join(etfs_used)}), "
        f"total ETF market value is ${etf_mv_total:,.2f}, touching "
        f"{len(exposure)} underlying name(s) in total (see Detail for the full list).",
    ]
    if ranked:
        biggest_sym, biggest_rec = ranked[0]
        biggest_pct = (biggest_rec['value'] / etf_mv_total * 100) if etf_mv_total else 0
        if biggest_pct >= 15:
            lines.append(f"That's a meaningful concentration in {biggest_sym} "
                          f"once you look through the ETF wrappers.")

    # Biggest crasher/upper — matches SCAIE's Fallers/Uppers toggles now:
    # top-10 by exposure, ranked by $ IMPACT (exposure x %chg) not raw
    # %chg, same tick-size-impact logic.
    top10_syms = [sym for sym, _ in ranked[:10]]
    day_chg = _opie_fetch_underlying_day_change(top10_syms, limit=10)
    if day_chg:
        impact = {sym: exposure[sym]['value'] * (chg / 100.0) for sym, chg in day_chg.items()}
        worst_sym = min(impact, key=impact.get)
        best_sym  = max(impact, key=impact.get)
        lines.append(
            f"Among your top 10 exposures today: {worst_sym} is having the biggest "
            f"negative $ impact (${impact[worst_sym]:+,.0f}, {day_chg[worst_sym]:+.2f}%), "
            f"while {best_sym} is having the biggest positive $ impact "
            f"(${impact[best_sym]:+,.0f}, {day_chg[best_sym]:+.2f}%). "
            f"See 🔻 Biggest Fallers / 🚀 Biggest Uppers for the full top-10 breakdown."
        )
    return ' '.join(lines)




def _opie_fetch_etf_holdings(ticker: str) -> dict:
    """Top-10 holdings + sector weightings for an ETF ticker, via yfinance's
    funds_data, disk-cached for _TTL_ETF like every other network call in
    this app. Returns {} if the ticker isn't a fund or the fetch fails."""
    ticker = _resolve_ticker_alias((ticker or '').upper().strip())
    if not ticker:
        return {}
    cached = cache_get_etf_holdings(ticker)
    if cached:
        return cached
    try:
        fd = yf.Ticker(ticker).funds_data
        top_df = getattr(fd, 'top_holdings', None)
        if top_df is None or top_df.empty:
            return {}
        holdings = []
        for sym, row in top_df.head(10).iterrows():
            pct = row.get('Holding Percent', row.iloc[0] if len(row) else 0) or 0
            holdings.append({
                'symbol': str(sym),
                'name':   str(row.get('Name', sym)),
                'pct':    float(pct) * (100.0 if float(pct) <= 1 else 1.0),
            })
        sectors = {}
        try:
            raw_sectors = getattr(fd, 'sector_weightings', None) or {}
            for sec, w in raw_sectors.items():
                w = float(w)
                sectors[str(sec)] = w * 100.0 if w <= 1 else w
        except Exception:
            sectors = {}
        data = {'ticker': ticker, 'holdings': holdings, 'sector_weightings': sectors}
        if holdings:
            cache_set_etf_holdings(ticker, data)
        return data
    except Exception:
        return {}


# Ticker rename aliases — NPORT-P filings (and any cached/older data) may
# still report a company's OLD symbol after an exchange ticker change;
# yfinance only ever recognizes the CURRENT one, so a stale symbol coming
# back from EDGAR would silently fail to match/price ("possibly delisted").
# Add an entry here whenever a held/underlying name's ticker changes.
_TICKER_RENAME_ALIASES = {
    'SATS': 'ECHO',   # EchoStar Corp — Nasdaq ticker changed 2026-06-24
    'EQR':  'VMRK',   # Equity Residential acquired AvalonBay, renamed Vivmark Residential (VMRK) 2026-08-18
    'AVB':  'VMRK',   # AvalonBay shares converted into VMRK (2.793x) — old holdings/filings resolve here
}

# S&P 500 constituent changes applied on top of a persisted sp500.csv (which is
# never re-seeded once written).  Removed tickers are dropped, added ones are
# appended if missing.  Append a new entry here whenever the index changes.
_SP500_CHANGES = [
    # (effective date, tickers removed, [(ticker, name) added])
    ('2026-08-18', ['AVB'], [('RDDT', 'Reddit'), ('VMRK', 'Vivmark Residential')]),
]


# ── S&P 500 live constituent detector ────────────────────────────────────────
# Keeps sp500.csv in step with the real index so a merger / ticker change /
# index swap (e.g. AVB -> VMRK, RDDT in) never again depends on a code edit.
# Runs at most once per 24h (retries a failed fetch after 1h), with short
# timeouts, and NEVER overwrites the CSV unless the fetched list passes sanity
# checks.  _SP500_CHANGES above stays as an offline fallback / override.
SP500_LIVE_SOURCES = [
    ('Wikipedia', 'https://en.wikipedia.org/wiki/List_of_S%26P_500_companies'),
    ('DataHub',   'https://raw.githubusercontent.com/datasets/'
                  's-and-p-500-companies/main/data/constituents.csv'),
]
SP500_SYNC_OK_HOURS    = 24
SP500_SYNC_RETRY_HOURS = 1
SP500_MIN_COUNT, SP500_MAX_COUNT = 480, 520
SP500_MIN_OVERLAP      = 0.90     # live list must share >=90% with what we hold
SP500_SYNC_STATUS      = {}       # last result, readable from the UI/log


def _sp500_fetch_live():
    """Return (source_name, [(ticker, name)]) from the first source that
    parses, else (None, [])."""
    import io as _io
    import csv as _csv
    try:
        import requests as _rq
    except Exception:
        return None, []
    hdr = {'User-Agent': 'Mozilla/5.0 (PAA-MERGED S&P500 sync)'}
    for name, url in SP500_LIVE_SOURCES:
        try:
            r = _rq.get(url, headers=hdr, timeout=8)
            r.raise_for_status()
            rows = []
            if name == 'Wikipedia':
                tbls = pd.read_html(_io.StringIO(r.text), match='Symbol')
                t = tbls[0]
                scol = next(c for c in t.columns if str(c).strip().lower() == 'symbol')
                ncol = next((c for c in t.columns if str(c).strip().lower() in ('security', 'name')), scol)
                for sym, nm in zip(t[scol], t[ncol]):
                    rows.append((str(sym).strip().upper().replace('.', '-'), str(nm).strip()))
            else:
                for row in _csv.DictReader(_io.StringIO(r.text)):
                    sym = (row.get('Symbol') or row.get('symbol') or '').strip().upper().replace('.', '-')
                    nm  = (row.get('Security') or row.get('Name') or row.get('name') or sym).strip()
                    if sym:
                        rows.append((sym, nm))
            rows = [(t_, n_) for t_, n_ in rows if t_ and t_ != 'NAN']
            if SP500_MIN_COUNT <= len(rows) <= SP500_MAX_COUNT:
                return name, rows
            log(f"   ⚠️  S&P 500 live ({name}): {len(rows)} rows — outside sane range, ignored")
        except Exception as e:
            log(f"   ⚠️  S&P 500 live ({name}) unavailable: {e}")
    return None, []


def _sp500_live_sync(csv_path: str, force: bool = False) -> dict:
    """Compare sp500.csv with the live index and update the CSV when they
    differ.  Safe no-op on any failure.  Returns a status dict."""
    import json as _json
    import csv as _csv
    global SP500_SYNC_STATUS
    stamp_path = os.path.join(os.path.dirname(csv_path), 'sp500_sync.json')
    now = time_module.time()
    state = {}
    try:
        if os.path.exists(stamp_path):
            with open(stamp_path, encoding='utf-8') as f:
                state = _json.load(f) or {}
    except Exception:
        state = {}
    if not force:
        if now - state.get('last_ok', 0) < SP500_SYNC_OK_HOURS * 3600:
            SP500_SYNC_STATUS = state.get('last_result', {}) or {}
            return SP500_SYNC_STATUS
        if now - state.get('last_try', 0) < SP500_SYNC_RETRY_HOURS * 3600 \
                and state.get('last_try', 0) > state.get('last_ok', 0):
            SP500_SYNC_STATUS = state.get('last_result', {}) or {}
            return SP500_SYNC_STATUS
    state['last_try'] = now
    result = {'ok': False, 'source': None, 'added': [], 'removed': [], 'checked': now}
    try:
        src, live = _sp500_fetch_live()
        if not src:
            result['error'] = 'no live source reachable'
        else:
            cur = []
            if os.path.exists(csv_path):
                with open(csv_path, encoding='utf-8') as f:
                    for row in _csv.DictReader(f):
                        t = (row.get('ticker') or '').strip()
                        if t:
                            cur.append((t, (row.get('name') or t).strip()))
            cur = _apply_sp500_changes(cur) if cur else []
            cur_set  = {t for t, _ in cur}
            live_set = {t for t, _ in live}
            overlap  = len(cur_set & live_set) / max(1, len(cur_set)) if cur_set else 1.0
            if cur_set and overlap < SP500_MIN_OVERLAP:
                result['error'] = f'live list only {overlap:.0%} overlap — refused'
                log(f"   ⚠️  S&P 500 sync refused ({src}): {result['error']}")
            else:
                # Known renames stay authoritative even if a source lags behind.
                live_set = {_resolve_ticker_alias(t) for t in live_set}
                live_set -= {t for _, rem, _ in _SP500_CHANGES for t in rem
                             if t not in _TICKER_RENAME_ALIASES.values()}
                live_set |= {t for _, _, adds in _SP500_CHANGES for t, _ in adds}
                added   = sorted(live_set - cur_set)
                removed = sorted(cur_set - live_set)
                names = {t: n for t, n in cur}
                names.update({t: n for t, n in live if t not in names})
                if added or removed or not cur_set:
                    if os.path.exists(csv_path):
                        try:
                            import shutil as _sh
                            _sh.copyfile(csv_path, csv_path + '.bak')
                        except Exception:
                            pass
                    with open(csv_path, 'w', encoding='utf-8', newline='') as f:
                        f.write('ticker,name\n')
                        for t in sorted(live_set):
                            n = names.get(t, t)
                            f.write(f'{t},"{n}"\n' if ',' in n else f'{t},{n}\n')
                    log(f"   🔄 S&P 500 sync ({src}): +{len(added)} {added} / "
                        f"-{len(removed)} {removed} → sp500.csv updated ({len(live_set)} tickers)")
                else:
                    log(f"   ✅ S&P 500 sync ({src}): sp500.csv already matches the live index")
                result.update({'ok': True, 'source': src, 'added': added,
                               'removed': removed, 'count': len(live_set)})
                state['last_ok'] = now
                if added or removed:
                    hist = state.get('history', [])
                    hist.append({'when': datetime.now().strftime('%Y-%m-%d %H:%M'),
                                 'source': src, 'added': added, 'removed': removed})
                    state['history'] = hist[-20:]
    except Exception as e:
        result['error'] = str(e)
        log(f"   ⚠️  S&P 500 sync failed: {e}")
    state['last_result'] = result
    try:
        with open(stamp_path, 'w', encoding='utf-8') as f:
            _json.dump(state, f)
    except Exception:
        pass
    SP500_SYNC_STATUS = result
    return result


def _apply_sp500_changes(rows: list) -> list:
    """rows = [(ticker, name)]. Resolves renames, drops removed tickers, adds
    new ones, de-duplicates by ticker (first wins; a later renamed name such
    as VMRK replaces the stale 'Equity Residential' label)."""
    removed = {t for _, rem, _ in _SP500_CHANGES for t in rem}
    out, seen = [], {}
    for t, n in rows:
        t = _resolve_ticker_alias(t)
        if t in removed and t not in _TICKER_RENAME_ALIASES.values():
            continue
        if t in seen:
            continue
        seen[t] = len(out)
        out.append((t, n))
    for _, _, adds in _SP500_CHANGES:
        for t, n in adds:
            if t in seen:
                out[seen[t]] = (t, n)
            else:
                seen[t] = len(out)
                out.append((t, n))
    return out


def _resolve_ticker_alias(ticker: str) -> str:
    """Maps an old/retired ticker to its current one. Safe no-op for any
    ticker not in the alias table."""
    ticker = (ticker or '').upper().strip()
    return _TICKER_RENAME_ALIASES.get(ticker, ticker)


# SEC requires every EDGAR request to identify a real person/organization —
# "Name email@domain" — or it will start throttling/blocking requests.
# EDGAR access is gated on the signed-in K-ID having an email on file
# (set on the sign-in screen / the "add an email" prompt); if that's not
# set, this falls back to the app-wide "edgar_fallback_email" setting
# (⚙ EDGAR Settings) so EDGAR isn't simply unusable without a K-ID email.
def edgar_identity() -> 'str | None':
    """Return '<K-ID> <their email>' for the signed-in K-ID if they have a
    valid email on file; otherwise fall back to the app-wide EDGAR settings
    email ('PAA+ <email>'); otherwise None — callers must treat None as
    'EDGAR is not available yet, needs an email configured somewhere'."""
    kid = (globals().get('CURRENT_KID') or '').strip()
    settings = load_app_settings()
    if kid:
        em = kid_get_email(settings, kid)
        if em and kid_valid_email(em):
            return f"{kid} {em}"
    fallback = (settings.get('edgar_fallback_email') or '').strip()
    if fallback and kid_valid_email(fallback):
        return f"PAA+ {fallback}"
    return None


def set_edgar_fallback_email(email: str) -> bool:
    """⚙ EDGAR Settings — sets/clears the app-wide EDGAR identity email.
    Returns True on success, False if the email fails validation (and
    isn't empty — empty is allowed, it just clears the fallback)."""
    email = (email or '').strip()
    if email and not kid_valid_email(email):
        return False
    settings = load_app_settings()
    settings['edgar_fallback_email'] = email
    save_app_settings(settings)
    return True

_ETF_FULL_HOLDINGS_CACHE: dict = {}   # ticker -> {'data': {...}, 'ts': epoch_seconds}
_ETF_FULL_HOLDINGS_TTL   = 7 * 24 * 3600   # NPORT-P is filed monthly with a lag —
                                            # no point re-hitting SEC more than weekly


_US_EXCHANGES = {
    'NMS', 'NYQ', 'NGM', 'NCM', 'PCX', 'ASE', 'BATS', 'PNK', 'OBB',
}  # yfinance exchange codes for Nasdaq/NYSE/NYSE Arca/AMEX/OTC/BATS


def _is_us_listed_etf(ticker: str) -> tuple:
    """Cheap pre-check via yfinance before ever hitting SEC/EDGAR: confirms
    the ticker is (a) a fund/ETF and (b) listed on a US exchange. This is
    what actually gates the EDGAR call — Bursa/SGX/HKEX tickers, or plain
    stocks, get rejected here instead of wasting a request (and getting a
    confusing error back) from edgartools/SEC.
    Returns (is_us_etf: bool, reason: str).
    """
    ticker = _resolve_ticker_alias((ticker or '').upper().strip())
    if not ticker:
        return False, 'No ticker given.'
    try:
        info = yf.Ticker(ticker).info or {}
    except Exception as e:
        return False, f"Couldn't look up {ticker} on yfinance: {type(e).__name__}."

    quote_type = str(info.get('quoteType', '')).upper()
    exchange = str(info.get('exchange', '')).upper()

    if quote_type not in ('ETF', 'MUTUALFUND'):
        return False, f"{ticker} isn't a fund/ETF on yfinance (quoteType={quote_type or '?'})."
    if exchange not in _US_EXCHANGES:
        return False, (f"{ticker} isn't US-listed (yfinance exchange={exchange or '?'}) — "
                        f"only US-listed ETFs file NPORT-P with the SEC.")
    return True, ''


def _opie_fetch_etf_full_holdings(ticker: str) -> dict:
    """FULL holdings list for a US-registered ETF, straight from its most
    recent NPORT-P filing with the SEC (every '40 Act fund/ETF must file
    one monthly, disclosing every single position — not just a top-10).
    Requires the 'edgartools' package: pip install edgartools

    Gated by _is_us_listed_etf() first — only tickers yfinance confirms as
    US-listed funds/ETFs ever reach EDGAR. Everything else (Bursa/SGX/HKEX
    funds, plain stocks, bad tickers) short-circuits with a clear reason
    before any SEC request is made.

    Returns {} if:
      - edgartools isn't installed
      - the ticker doesn't resolve to an SEC-registered fund
      - no NPORT-P filing is found

    Caveat vs. the yfinance top-10 fetcher above: this is NOT live. NPORT-P
    is filed monthly with roughly a 60-day lag, so 'full holdings' here
    means 'as of the most recent SEC snapshot', not today's actual book.
    """
    ticker = _resolve_ticker_alias((ticker or '').upper().strip())
    if not ticker:
        return {}
    cached = _ETF_FULL_HOLDINGS_CACHE.get(ticker)
    if cached and (time_module.time() - cached['ts']) < _ETF_FULL_HOLDINGS_TTL:
        return cached['data']

    is_us_etf, reason = _is_us_listed_etf(ticker)
    if not is_us_etf:
        return {'error': reason}

    try:
        from edgar import Company, set_identity
    except ImportError:
        return {'error': "edgartools isn't installed. Run: pip install edgartools"}

    try:
        identity = edgar_identity()
        if not identity:
            return {'error': 'Add an email to your K-ID to use EDGAR/SEC lookups '
                              '(Sign-in screen \u2192 your K-ID needs an email on file).'}
        set_identity(identity)
        fund = Company(ticker)
        if fund is None or not getattr(fund, 'cik', None):
            return {'error': f'{ticker} did not resolve to an SEC-registered entity '
                              f'(only works for US-listed ETFs that file with the SEC).'}

        filings = fund.get_filings(form='NPORT-P')
        if not filings or len(filings) == 0:
            return {'error': f'No NPORT-P filing found for {ticker}.'}

        latest = filings[0]
        report = latest.obj()

        # investment_data() is the documented DataFrame accessor as of the
        # current edgartools docs; .investments is an older/alternate
        # attribute some versions expose instead — try both so this
        # doesn't silently break across edgartools versions.
        df = None
        try:
            df = report.investment_data(include_derivatives=False)
        except Exception:
            df = getattr(report, 'investments', None)
        if df is None or len(df) == 0:
            return {'error': f'NPORT-P filing found for {ticker} but no positions parsed out of it.'}

        total_value = float(df['value_usd'].sum()) if 'value_usd' in df.columns else None
        holdings = []
        for _, row in df.iterrows():
            val = float(row.get('value_usd', 0) or 0)
            pct = (val / total_value * 100.0) if total_value else None
            holdings.append({
                'symbol': _resolve_ticker_alias(str(row.get('ticker', '') or row.get('cusip', '') or '')),
                'name':   str(row.get('name', '?')),
                'value_usd': val,
                'pct':    pct,
            })
        holdings.sort(key=lambda h: h['value_usd'], reverse=True)

        net_assets = None
        try:
            net_assets = float(report.fund_info.net_assets)
        except Exception:
            pass

        data = {
            'ticker': ticker,
            'filing_date': str(getattr(latest, 'filing_date', '')),
            'total_positions': len(holdings),
            'total_value_usd': total_value,
            'net_assets': net_assets,
            'holdings': holdings,   # FULL list — could be hundreds/thousands of rows
        }
        _ETF_FULL_HOLDINGS_CACHE[ticker] = {'data': data, 'ts': time_module.time()}
        return data
    except Exception as e:
        return {'error': f'{type(e).__name__}: {e}'}


def _opie_format_holdings_table(data: dict) -> str:
    """Plain-text Top 10 Holdings table, mirroring the proposal's example
    layout ('1. Apple Inc.   6.72%')."""
    lines = [f"{data.get('ticker', '?')} — Top 10 Holdings", '']
    for i, h in enumerate(data.get('holdings', [])[:10], 1):
        lines.append(f"{i:>2}. {h['name']:<28} {h['pct']:>5.2f}%")
    return '\n'.join(lines)


def _opie_format_full_holdings_table(data: dict, limit: int = 50) -> str:
    """Plain-text FULL holdings table from an NPORT-P filing (see
    _opie_fetch_etf_full_holdings). Shows up to `limit` rows (the real
    list can run into the hundreds/thousands for broad-market ETFs) plus
    a count of how many more exist beyond that."""
    if data.get('error'):
        return f"Couldn't get full holdings: {data['error']}"
    holdings = data.get('holdings', [])
    if not holdings:
        return "No holdings data available."
    lines = [f"{data.get('ticker', '?')} — Full Holdings "
             f"({data.get('total_positions', len(holdings))} positions, "
             f"as of NPORT-P filed {data.get('filing_date', '?')})", '']
    for i, h in enumerate(holdings[:limit], 1):
        pct_str = f"{h['pct']:>5.2f}%" if h.get('pct') is not None else '   —  '
        lines.append(f"{i:>3}. {h['name']:<32} {pct_str}   ${h['value_usd']:,.0f}")
    if len(holdings) > limit:
        lines.append(f"\n… and {len(holdings) - limit} more positions "
                      f"(full list is in the returned data, just not printed here)")
    return '\n'.join(lines)


def _opie_generate_etf_summary(data: dict) -> str:
    """Rule-based stand-in for the proposal's 'Opie Smart Summary' — no live
    AI call (OPIE-the-agent is disabled), just a deterministic write-up from
    the holdings/sector data already fetched, in the same tone as the
    proposal's example summary."""
    ticker   = data.get('ticker', 'This ETF')
    holdings = data.get('holdings', [])
    sectors  = data.get('sector_weightings', {})
    if not holdings:
        return f"I couldn't retrieve holdings for {ticker} — check the ticker or try again shortly."

    top3 = [h['name'] for h in holdings[:3]]
    top3_str = ', '.join(top3[:-1]) + (f' and {top3[-1]}' if len(top3) > 1 else top3[0])
    top1_pct = holdings[0]['pct']

    ranked_sectors = sorted(sectors.items(), key=lambda kv: kv[1], reverse=True)
    largest_sector = ranked_sectors[0][0].replace('_', ' ').title() if ranked_sectors else None
    largest_sector_pct = ranked_sectors[0][1] if ranked_sectors else None
    other_sectors = [s.replace('_', ' ').title() for s, _ in ranked_sectors[1:4]]

    concentration = ('a fairly concentrated' if top1_pct >= 8
                      else 'a moderately concentrated' if top1_pct >= 4
                      else 'a broadly diversified')

    parts = [f"{ticker} counts {top3_str} among its largest holdings."]
    if largest_sector:
        parts.append(f"The largest sector allocation is {largest_sector} "
                      f"(~{largest_sector_pct:.1f}%), "
                      f"suggesting a strong tilt toward that space.")
    if other_sectors:
        parts.append(f"Remaining exposure spans {', '.join(other_sectors)}, "
                      f"rounding out the fund's sector mix.")
    parts.append(f"With its top holding at {top1_pct:.2f}%, {ticker} looks like "
                 f"{concentration} fund overall.")
    return ' '.join(parts)


class OpieChatWindow(tk.Toplevel):
    """Pop-up OPIE chat box. Idle until 'Hi, Opie' is typed; only then does
    it greet the user, confirm a display name, and start answering."""

    def __init__(self, parent, host, kid_username: str):
        super().__init__(parent)
        self.host = host
        self.kid  = (kid_username or '').strip()
        self.title('🤖 OPIE')
        self.configure(bg='#0d1117')
        self.geometry('380x460')
        self.transient(parent)

        self._activated      = False
        self._awaiting_name  = False
        self._awaiting_stock = False
        self._awaiting_price = False
        self._awaiting_index = False
        self._awaiting_index_define = False
        self._awaiting_fund  = False
        self._pending_invest = None   # (amount, ccy) waiting on a fund name
        self._awaiting_summary_currency = False
        self._pending_summary = None   # ('ticker', match) | ('portfolio', None) awaiting a currency reply
        self._display_name   = None
        # Continuation mode: remembers the last ticker/index actually
        # resolved so a follow-up like "how much is it worth" or "what
        # about the price" can be answered without repeating the name.
        self._last_subject   = None   # ('ticker', ticker, item, ccy) | ('index', match)
        # Order-opening (PTS / ZDWS / ZDOS) conversation state.
        self._awaiting_permission = False
        self._pending_order_text  = None
        self._order               = None   # in-progress order dict
        self._awaiting_order_field = None  # which field the next reply fills

        tk.Label(self, text='🤖  OPIE', font=('Segoe UI', 12, 'bold'),
                 fg='#3FB950', bg='#0d1117').pack(pady=(10, 2))

        self._log = tk.Text(self, height=18, width=44, font=('Segoe UI', 9),
                             bg='#161b22', fg='#cdd9e5', wrap='word',
                             relief='flat', state='disabled')
        self._log.pack(padx=10, pady=6, fill='both', expand=True)

        row = tk.Frame(self, bg='#0d1117')
        row.pack(fill='x', padx=10, pady=(0, 10))
        self._entry_var = tk.StringVar()
        entry = tk.Entry(row, textvariable=self._entry_var, font=('Segoe UI', 10),
                          bg='#21262d', fg='#cdd9e5', insertbackground='#cdd9e5',
                          relief='flat')
        entry.pack(side='left', fill='x', expand=True, ipady=4)
        entry.bind('<Return>', lambda e: self._submit())
        entry.focus_set()
        tk.Button(row, text='Send', font=('Segoe UI', 9, 'bold'), bg='#3FB950',
                  fg='#0d1117', relief='flat', padx=10, cursor='hand2',
                  command=self._submit).pack(side='left', padx=(6, 0))

        self._say('Type "Hi, Opie" to start.')

    # ── log helpers ──────────────────────────────────────────────────────
    def _say(self, text: str):
        self._log.configure(state='normal')
        self._log.insert('end', f'🤖 OPIE: {text}\n\n')
        self._log.configure(state='disabled')
        self._log.see('end')

    def _say_user(self, text: str):
        self._log.configure(state='normal')
        self._log.insert('end', f'You: {text}\n')
        self._log.configure(state='disabled')

    def _submit(self):
        text = self._entry_var.get().strip()
        if not text:
            return
        self._entry_var.set('')
        self._say_user(text)
        self._process(text)

    # ── conversation logic ───────────────────────────────────────────────
    def _process(self, text: str):
        low = text.lower().replace(',', '').replace('!', '').strip()
        # Squash all whitespace/punctuation so "Hi,Opie", "Hi, Opie!", "hi   opie"
        # etc. all normalize the same way for the activation check.
        squashed = ''.join(ch for ch in low if ch.isalnum())

        if not self._activated:
            if squashed in {g.replace(' ', '') for g in _OPIE_GREETINGS}:
                self._activated = True
                self._start_name_flow()
            else:
                self._say('Type "Hi, Opie" to start.')
            return

        if self._awaiting_name:
            self._resolve_name(text)
            return

        if self._awaiting_stock:
            self._answer_stock(text)
            return

        if self._awaiting_price:
            self._answer_price(text)
            return

        if self._awaiting_index:
            self._answer_index(text)
            return

        if self._awaiting_index_define:
            self._answer_index_definition(text)
            return

        if self._awaiting_fund:
            self._answer_fund(text)
            return

        if self._awaiting_summary_currency:
            self._answer_summary_currency(text)
            return

        if self._awaiting_permission:
            self._resolve_permission(text)
            return

        if self._awaiting_order_field:
            self._continue_order(text)
            return

        # Log every real question from here on — greetings and mid-flow
        # answers above are excluded since they aren't questions in
        # themselves.
        self._log_recent_asked(text)

        if re.search(r'\bopen\b', low) and re.search(r'\b(pts|zdws|zdos|order|position|warrant|option|prediction)\b', low):
            self._handle_open_order(text)
            return

        # "invest $10,000 in <fund>" / "if I put RM5000 into <fund>" — a
        # historical backtest of what that would be worth today, using the
        # fund's real NAV history (same engine as the Return Calculator
        # button on the VFund Events tab, just reachable from chat too).
        if re.search(r'\binvest(ed|ing)?\b|\bput\b.*\bin(to)?\b', low) and \
           re.search(r'\b\d', low):
            self._handle_invest(text)
            return

        # 'who fell so much' / 'biggest fallers' / 'biggest uppers' — SCAIE's
        # fallers/uppers views, reachable from chat. Checked before the
        # plain indirect-exposure keywords since 'fell'/'dropped'/'rose'
        # don't overlap with those phrases.
        if any(kw in low for kw in _OPIE_FALLERS_KEYWORDS):
            self._handle_indirect_fallers(text, worst=True)
            return
        if any(kw in low for kw in _OPIE_UPPERS_KEYWORDS):
            self._handle_indirect_fallers(text, worst=False)
            return

        # 'indirect exposure' / 'total exposure' / 'am I exposed to NVDA' —
        # checked BEFORE the ETF-holdings check below, since 'exposure to X'
        # doesn't contain the word 'holdings' but 'exposed to' does overlap
        # in spirit with it; this used to be something OPIE simply couldn't
        # answer at all (SCAIE was a SCA-only button) — now it can.
        if any(kw in low for kw in _OPIE_INDIRECT_KEYWORDS):
            self._handle_indirect_exposure(text)
            return

        if any(kw in low for kw in _OPIE_FULL_HOLDINGS_KEYWORDS):
            self._handle_full_etf_holdings(text)
            return

        if any(kw in low for kw in _OPIE_ETF_KEYWORDS):
            self._handle_etf_holdings(text)
            return

        # 'trend BOTZ 5d', 'MYIPO+ trend YTD', 'how has S&P 500 trended all time'
        if _OPIE_RE_TREND.search(low):
            self._handle_trend(text)
            return

        # 'summary settings' / 'set summary on open' / 'set summary time
        # 9:00am' / 'turn off summary schedule' — config, checked before
        # the data-summary query below.
        if re.search(r'\bsummary\b', low) and \
           re.search(r'\b(setting|schedule|on\s*open|turn off|disable|fixed|daily)\b', low):
            self._handle_summary_settings(text)
            return

        # 'summary' — checked before 'holdings'/'weight' etc since it's a
        # broader ask; continuation-aware (ticker vs whole portfolio).
        if _OPIE_RE_SUMMARY.search(low):
            self._handle_summary(text)
            return

        if _OPIE_RE_AVGCOST.search(low):
            self._handle_avg_cost(text)
            return

        # 'weight'/'allocation'/'% of portfolio' — new FAQ, not ETF-related.
        if _OPIE_RE_WEIGHT.search(low):
            self._handle_weight(text)
            return

        # 'holdings report', 'position report/detail for BOTZ' — opens the
        # T80 ledger+chart popup from chat, same as the button/row-click.
        if _OPIE_RE_HOLD_RPT.search(low):
            self._handle_holdings_report(text)
            return

        # 'dividend' / 'div income' / 'payouts' — reads straight from the
        # _dividends log built during ledger parsing (the same data behind
        # the 💵 Dividend Log button), not the live-price dividend
        # estimator (that's a forward-looking projection, this is what
        # was actually paid).
        if _OPIE_RE_DIVIDEND.search(low):
            self._handle_dividend_info(text)
            return

        if _OPIE_RE_FUND.search(low):
            self._handle_fund(text)
            return

        # Continuation mode: "it"/"that"/"this one" etc. with no ticker/index
        # of its own named in the message refers back to whatever was last
        # resolved, so a follow-up question doesn't need the name repeated.
        if self._last_subject and re.search(r"\b(it|that|this( one)?|its)\b", low) and \
           not _opie_ticker_candidates(text) and not self._match_index(self.host, text):
            if _OPIE_RE_CHANGE.search(low) and not re.search(r'\bexchange\b', low):
                self._handle_change()
                return
            if _OPIE_RE_TREND.search(low):
                self._handle_trend(text)
                return
            if _OPIE_RE_WEIGHT.search(low):
                self._handle_weight(text)
                return
            if _OPIE_RE_SUMMARY.search(low):
                self._handle_summary(text)
                return
            if _OPIE_RE_AVGCOST.search(low):
                self._handle_avg_cost(text)
                return
            # ETF ("top holdings") and Holdings Report continuation are
            # deliberately excluded here — those stay explicit-trigger only.
            if 'how much' in low or _OPIE_RE_PRICE.search(low) or \
               _OPIE_RE_INDEX.search(low):
                self._reply_last_subject()
                return

        if _OPIE_RE_CHANGE.search(low) and not re.search(r'\bexchange\b', low):
            self._handle_change()
            return

        if 'how much' in low or 'value of' in low or 'worth of' in low:
            self._handle_how_much(text)
            return

        # 'what is Top 5', 'explain MYIPO+ Momentum', 'define KLCI', 'tell me
        # about Top 200' — a definition ask, checked BEFORE the plain
        # index-value lookup below so "what is X" doesn't get misread as a
        # request for X's current level.
        if _OPIE_RE_DEFINE.search(low):
            self._handle_index_definition(text)
            return

        if _OPIE_RE_PRICE.search(low):
            self._handle_price(text)
            return

        if _OPIE_RE_INDEX.search(low):
            self._handle_index(text)
            return

        # Last resort: no keyword matched, but the message may just be a bare
        # ticker/index left over from an earlier prompt (e.g. "5347.KL?"
        # typed after a failed match) — resolve it directly instead of
        # forcing the user to re-trigger a keyword.
        match = _opie_match_portfolio_ticker(self.host, text)
        if match:
            self._say_stock_value(match)
            return
        idx = self._match_index(self.host, text)
        if idx:
            self._say_index_value(idx)
            return
        cand = _opie_best_candidate(_opie_ticker_candidates(text))
        if cand:
            resolved, price = self._current_price(cand)
            if price is not None:
                self._last_subject = ('price', resolved, price)
                self._say(f'{resolved} is currently trading at {price:,.4f} {_opie_infer_ccy(resolved)}.')
                return

        if _opie_is_question(text):
            self._say("Good question — I'm not quite sure how to answer that one yet, "
                       "but here's what I can actually help with:")
        else:
            self._say("Not sure I follow — here's what I can help with:")
        self._say('"change" (see your portfolio / a stock), '
                   '"how much" (value & % in a currency of your choice), '
                   '"stock price" (current price of a stock), '
                   '"index" (current value of a market index — KLCI, world '
                   'indices, S&P sector indices — Tech/Financials/Health Care/'
                   'Energy/etc., or any MYIPO+ index), "trend" (e.g. "trend BOTZ '
                   '5d", "MYIPO+ trend YTD" — 1d/5d/1mo/3mo/6mo/ytd/1y/all), '
                   '"summary" (ticker or whole-portfolio, incl. recent buys — '
                   '"set summary on open" / "set summary time 9:00am" to '
                   'schedule an auto-popup), "avg cost" (cost basis / '
                   'breakeven on a stock), '
                   '"holdings report" (opens the ledger + chart popup), '
                   '"weight" (% of your portfolio a stock represents), '
                   '"top holdings" of an ETF (e.g. "top holdings VOO"), '
                   '"full holdings" of a US ETF straight from its SEC NPORT-P '
                   'filing (e.g. "full holdings SCHD"), '
                   '"indirect exposure" (how much of your ETFs\' underlying '
                   'holdings you\'re really exposed to — e.g. "am I exposed to NVDA?"), '
                   'or "open" a PTS/ZDWS/ZDOS position. Ask me however feels '
                   'natural — I\'ll do my best to match it.')

    def _reply_last_subject(self):
        """Continuation-mode follow-up ("how much is it worth now?") — repeat
        whatever's already stored as the last resolved subject."""
        kind = self._last_subject[0]
        if kind == 'stock':
            self._say_stock_value(self._last_subject[1])
        elif kind == 'index':
            self._say_index_value(self._last_subject[1])
        elif kind == 'fund':
            self._say_fund_value(self._last_subject[1])
        elif kind == 'etf':
            data = _opie_fetch_etf_holdings(self._last_subject[1])
            if data.get('holdings'):
                self._say(_opie_format_holdings_table(data))
                self._say(_opie_generate_etf_summary(data))
        elif kind == 'price':
            _, ticker, price = self._last_subject
            self._say(f'{ticker} is currently trading at {price:,.4f} {_opie_infer_ccy(ticker)}.')

    def _recent_asked_line(self):
        """Formats this K-ID's 'Recently Asked' list for display right after
        the Opie greeting, or '' if there's no history yet."""
        settings = load_app_settings()
        recent = settings.get('opie_recent_asked', {}).get(self.kid.lower(), [])
        if not recent:
            return ''
        shown = recent[-5:][::-1]   # most recent first
        bullets = '\n'.join(f'  • {q}' for q in shown)
        return f'\n\nRecently asked:\n{bullets}'

    def _start_name_flow(self):
        settings = load_app_settings()
        names  = settings.get('opie_display_names', {})
        locked = settings.get('opie_name_locked', {})
        key = self.kid.lower()
        if key in names and locked.get(key):
            self._display_name = names[key]
            self._say(f'Hi, {self._display_name}! What would you like to know — '
                       f'try "change", "how much", "stock price", "index", "top holdings" of an ETF, or "open" a PTS/ZDWS/ZDOS position.'
                       f'{self._recent_asked_line()}')
            return
        self._awaiting_name = True
        self._say(f'Hi there! Want me to call you by your K-ID ("{self.kid}"), '
                   f'or type a custom name instead — this can only be set once.')

    def _resolve_name(self, text: str):
        settings = load_app_settings()
        names  = settings.setdefault('opie_display_names', {})
        locked = settings.setdefault('opie_name_locked', {})
        key = self.kid.lower()
        choice = text.strip()
        name = self.kid if choice.lower() in ('kid', 'k-id', self.kid.lower()) else choice
        names[key]  = name
        locked[key] = True
        save_app_settings(settings)
        self._display_name  = name
        self._awaiting_name = False
        self._say(f'Got it, {name}! What would you like to know — '
                   f'try "change", "how much", "stock price", "index", "top holdings" of an ETF, or "open" a PTS/ZDWS/ZDOS position.'
                   f'{self._recent_asked_line()}')

    def _handle_change(self):
        portfolios = _opie_extract_portfolios(self.host)
        if not portfolios:
            self._say('No portfolio loaded yet — connect a source first.')
            return
        lines = []
        for port in portfolios.values():
            for ticker, item in port.get('holdings', {}).items():
                if item.get('_is_cash'):
                    continue
                shares = item.get('shares', 0)
                if not shares or shares <= 0:
                    continue
                lines.append(f'{ticker} ({shares:g} shares)')
        if not lines:
            self._say('Your portfolio has no active positions right now.')
            return
        self._awaiting_stock = True
        self._say('Here\'s your portfolio: ' + ', '.join(lines) +
                   '. Which stock do you want to know about?')

    def _answer_stock(self, text: str):
        self._awaiting_stock = False
        match = _opie_match_portfolio_ticker(self.host, text)
        if not match:
            self._say(f'Couldn\'t match "{text}" to a ticker in your portfolio — '
                       f'try typing just the ticker, e.g. 5398.KL.')
            return
        self._say_stock_value(match)

    def _say_stock_value(self, match):
        ticker, item, ccy = match
        self._last_subject = ('stock', match)
        prices = _opie_extract_prices(self.host)
        shares = item.get('shares', 0)
        cost   = item.get('cost_value', 0.0)
        price  = prices.get(ticker)
        if not price:
            _, price = self._current_price(ticker)
        value  = shares * price if price else cost
        gain   = value - cost
        pct    = (gain / cost * 100) if cost > 0 else 0.0
        prefix = 'RM' if ccy == 'MYR' else f'{ccy} '
        self._say(f'{ticker}: {shares:g} shares, worth '
                   f'{prefix}{value:,.2f}, '
                   f'unrealized {gain:+,.2f} ({pct:+.2f}%).')

    def _current_price(self, ticker: str):
        """Live price from whatever's already loaded, falling back to the
        on-disk price cache. Bare codes with no exchange suffix (e.g. a
        Hong Kong or Singapore code typed without .HK/.SI) are tried
        against every market in MARKET_SPEC, so this keeps working as more
        exchanges get registered there — no changes needed here."""
        prices = _opie_extract_prices(self.host)
        variants = _opie_suffix_variants(ticker)
        for cand in variants:
            p = prices.get(cand)
            if p:
                return cand, p
        for cand in variants:
            try:
                s = cache_get_prices(cand)
                if s is not None and not s.empty:
                    return cand, float(s.iloc[-1])
            except Exception:
                pass
        return None, None

    def _handle_price(self, text: str):
        """'price' keyword: if a ticker was named in the same message, answer
        directly; otherwise list the portfolio and ask which stock."""
        cand = _opie_best_candidate(_opie_ticker_candidates(text))
        if cand:
            self._answer_price(cand)
            return
        portfolios = _opie_extract_portfolios(self.host)
        tickers = sorted({t for port in portfolios.values()
                           for t, item in port.get('holdings', {}).items()
                           if not item.get('_is_cash')})
        self._awaiting_price = True
        if tickers:
            self._say('Which stock\'s price do you want — e.g. ' +
                       ', '.join(tickers[:8]) + '?')
        else:
            self._say('Which stock\'s price do you want to know?')

    def _answer_price(self, text: str):
        self._awaiting_price = False
        query = text.strip().upper()
        resolved, price = self._current_price(query)
        if price is None:
            cand = _opie_best_candidate(_opie_ticker_candidates(text))
            if cand and cand != query:
                resolved, price = self._current_price(cand)
        if price is None:
            self._say(f'No current price on record for "{text}" — check the ticker and try again.')
            return
        self._last_subject = ('price', resolved, price)
        self._say(f'{resolved} is currently trading at {price:,.4f} {_opie_infer_ccy(resolved)}.')

    def _match_index(self, host, query: str):
        """Match free text against the index catalog by symbol or name,
        ignoring time-filler words, whichever way the substring runs (a bare
        name like "KLCI" or a full sentence like "what's the S&P 500 at")."""
        words = [w.strip('.,!?') for w in query.split()
                 if w.strip('.,!?').upper() not in _OPIE_TIME_WORDS]
        squashed_q = ''.join(ch for ch in ' '.join(words).upper() if ch.isalnum())
        if not squashed_q:
            return None
        for sym, name, ccy in _opie_index_catalog(host):
            sym_bare = ''.join(ch for ch in sym.replace('^', '').upper() if ch.isalnum())
            name_sq  = ''.join(ch for ch in name.upper() if ch.isalnum())
            if (name_sq and (name_sq in squashed_q or squashed_q in name_sq)) or \
               (sym_bare and (sym_bare == squashed_q or sym_bare in squashed_q)):
                return sym, name, ccy
        return None

    def _handle_index(self, text: str):
        """'index'/'indices' keyword: if a specific index was named in the
        same message, answer directly; otherwise list what's trackable and
        ask which one the user wants."""
        match = self._match_index(self.host, text)
        if match:
            self._say_index_value(match)
            return
        catalog = _opie_index_catalog(self.host)
        names = [name for _, name, _ in catalog]
        self._awaiting_index = True
        self._say('Which index do you want the current value for — ' +
                   ', '.join(names) + '?')

    def _answer_index(self, text: str):
        self._awaiting_index = False
        match = self._match_index(self.host, text)
        if not match:
            self._say(f'Couldn\'t match "{text}" to a tracked index — try one of the names above.')
            return
        self._say_index_value(match)

    def _say_index_value(self, match):
        sym, name, ccy = match
        self._last_subject = ('index', match)
        if sym == 'internal':
            app = _opie_dashboard_app(self.host)
            df = getattr(app, 'all_frames', {}).get(name)
            if df is None or df.empty or name not in df.columns:
                self._say(f'No data for {name} yet.')
                return
            s = df[name].dropna()
            if s.empty:
                self._say(f'No priced level for {name} yet.')
                return
            last = float(s.iloc[-1])
            chg_pct = None
            if len(s) > 1:
                prev = float(s.iloc[-2])
                if prev:
                    chg_pct = (last - prev) / prev * 100
            chg_txt = f', {chg_pct:+.2f}% vs previous close' if chg_pct is not None else ''
            self._say(f'{name} ({ccy}) is currently at {last:,.2f}{chg_txt}.')
            return
        mkt = _opie_extract_mkt_data(self.host)
        vals = mkt.get(sym)
        if not vals or vals[0] is None:
            self._say(f'No live value for {name} yet — open the dashboard so it can load.')
            return
        last, prev = vals
        chg_pct = ((last - prev) / prev * 100) if prev else 0.0
        self._say(f'{name} ({ccy}) is currently at {last:,.2f}, '
                   f'{chg_pct:+.2f}% vs the previous close.')

    def _handle_index_definition(self, text: str):
        """'what is'/'explain'/'define'/'tell me about' + an index name:
        answer with the plain-English guide, if one has been written for
        that index. If no name was given, list what's trackable and wait."""
        match = self._match_index(self.host, text)
        if match:
            self._say_index_definition(match)
            return
        catalog = _opie_index_catalog(self.host)
        names = [name for _, name, _ in catalog]
        self._awaiting_index_define = True
        self._say('Which index do you want explained — ' +
                   ', '.join(names) + '?')

    def _answer_index_definition(self, text: str):
        self._awaiting_index_define = False
        match = self._match_index(self.host, text)
        if not match:
            self._say(f'Couldn\'t match "{text}" to a tracked index — try one of the names above.')
            return
        self._say_index_definition(match)

    def _say_index_definition(self, match):
        sym, name, ccy = match
        self._last_subject = ('index', match)
        app = _opie_dashboard_app(self.host)
        guide_text = _opie_index_guide_lookup(app, name)
        if guide_text:
            self._say(guide_text)
            return
        # Fallback for anything not yet written up in _MYIPO_INDEX_GUIDE —
        # e.g. a newer tier like a Y-series or Champions/Kings/Gem/Diva cut,
        # or a future addition to BURSA_INDICES/the internal catalog that
        # nobody has gotten around to describing. Keeps OPIE from going
        # blank or saying "couldn't match" on a name it does recognise.
        if sym == 'internal':
            self._say(f"I don't have a written description for {name} yet — it's "
                       f"part of the MYIPO+ index family ({ccy}) and its live level "
                       f"is already trackable; ask \"what's {name} at\" for that. "
                       f"If you'd like, I can flag it so a proper description gets "
                       f"added to the guide.")
        else:
            self._say(f"I don't have a written description for {name} yet — it's "
                       f"tracked as a benchmark/world index ({ccy}); ask \"what's "
                       f"{name} at\" for its current level.")

    def _match_fund(self, host, query: str):
        """Match free text against the fund catalog (unit-trust + VFund
        labels) by name, same style as _match_index."""
        words = [w.strip('.,!?') for w in query.split()
                 if w.strip('.,!?').upper() not in _OPIE_TIME_WORDS]
        squashed_q = ''.join(ch for ch in ' '.join(words).upper() if ch.isalnum())
        if not squashed_q:
            return None
        best = None
        for label, ccy in _opie_fund_catalog(host):
            name_sq = ''.join(ch for ch in label.upper() if ch.isalnum())
            if name_sq and (name_sq in squashed_q or squashed_q in name_sq):
                # Prefer the longest matching label — avoids a short/generic
                # name matching every close variant equally well.
                if best is None or len(name_sq) > len(best[0]):
                    best = (name_sq, label, ccy)
        return (best[1], best[2]) if best else None

    # ── TREND — 1d/5d/1mo/3mo/6mo/ytd/1y/all, for SCA tickers, funds,
    #    the MYIPO+ index family, and world indices ─────────────────────
    _TREND_PERIODS = [
        (r'\b1\s*d(ay)?\b',            '1d',  1),
        (r'\b5\s*d(ay)?s?\b',          '5d',  5),
        (r'\b(1\s*mo(nth)?|30\s*d)\b', '1mo', 30),
        (r'\b3\s*mo(nth)?s?\b',        '3mo', 90),
        (r'\b6\s*mo(nth)?s?\b',        '6mo', 182),
        (r'\bytd\b',                   'ytd', None),
        (r'\b1\s*y(ea)?r?\b',          '1y',  365),
        (r'\ball\b',                   'all', None),
    ]

    def _parse_trend_period(self, low: str):
        for pat, label, _days in self._TREND_PERIODS:
            if re.search(pat, low):
                return label
        return None

    def _trend_series(self, text: str):
        """Resolve free text to (label, ccy, pandas Series) for trend, in
        priority order: MYIPO+/world index catalog -> tracked fund -> SCA
        portfolio ticker (fetched live via the same history helper the
        Holdings Report popup chart uses). World indices get their history
        loaded on demand if it isn't cached yet."""
        idx = self._match_index(self.host, text)
        if idx:
            sym, name, ccy = idx
            app = _opie_dashboard_app(self.host)
            if name not in getattr(app, 'all_frames', {}) and hasattr(app, '_load_world_history'):
                try:
                    app._load_world_history(symbols=[sym])
                except Exception:
                    pass
            df = getattr(app, 'all_frames', {}).get(name)
            if df is not None and not df.empty and name in df.columns:
                return name, ccy, df[name].dropna()
            return name, ccy, None

        fund = self._match_fund(self.host, text)
        if fund:
            label, ccy = fund
            app = _opie_dashboard_app(self.host)
            df = getattr(app, 'all_frames', {}).get(label)
            if df is not None and not df.empty and label in df.columns:
                return label, ccy, df[label].dropna()
            return label, ccy, None

        match = _opie_match_portfolio_ticker(self.host, text)
        if match:
            ticker = match[0]
            mkt = 'US' if _opie_infer_ccy(ticker) == 'USD' else 'MY'
            hist = None
            try:
                hist = _mf_get_price_history(ticker, mkt)
            except Exception:
                pass
            ccy = _opie_infer_ccy(ticker)
            return ticker, ccy, (hist if hist is None else hist.dropna())

        return None

    def _handle_trend(self, text: str):
        low = text.lower()
        period = self._parse_trend_period(low) or '1mo'
        resolved = self._trend_series(text)
        if not resolved and self._last_subject:
            kind = self._last_subject[0]
            if kind == 'index':
                resolved = self._trend_series(self._last_subject[1][1])  # index name
            elif kind in ('stock', 'fund'):
                resolved = self._trend_series(self._last_subject[1][0])
            elif kind == 'price':
                resolved = self._trend_series(self._last_subject[1])
        if not resolved:
            self._say('Which stock, fund, or index — try "trend BOTZ 5d" or "MYIPO+ trend YTD".')
            return
        label, ccy, s = resolved
        if s is None or s.empty:
            self._say(f'No price history for {label} yet.')
            return
        self._last_subject = ('price', label, float(s.iloc[-1]))
        import datetime as _dt
        last = float(s.iloc[-1])
        if period == 'all':
            start_val = float(s.iloc[0])
            span_txt = f'since {s.index[0].date()}'
        elif period == 'ytd':
            this_year = s.index[s.index.year == _dt.date.today().year]
            if this_year.empty:
                start_val = float(s.iloc[0])
            else:
                start_val = float(s.loc[this_year].iloc[0])
            span_txt = 'YTD'
        else:
            days = dict((lbl, d) for _, lbl, d in self._TREND_PERIODS if d)[period]
            cutoff = pd.Timestamp(_dt.date.today() - _dt.timedelta(days=days))
            window = s[s.index >= cutoff]
            start_val = float(window.iloc[0]) if not window.empty else float(s.iloc[0])
            span_txt = period
        if not start_val:
            self._say(f'No baseline price to compute the {span_txt} trend for {label}.')
            return
        chg = last - start_val
        chg_pct = chg / start_val * 100
        arrow = '▲' if chg >= 0 else '▼'
        self._say(f'{label} {span_txt} trend: {start_val:,.4f} → {last:,.4f} {ccy} '
                   f'({arrow} {chg_pct:+.2f}%).')

    def _handle_holdings_report(self, text: str):
        """'holdings report' / 'position detail' — opens the same T80 popup
        (ledger + price chart) the button and row-click open, for a named
        ticker or the last one discussed."""
        opener = getattr(self.host, '_open_holdings_report_popup', None)
        if opener is None:
            master = getattr(self.host, 'master', None)
            opener = getattr(master, '_open_holdings_report_popup', None)
        if opener is None:
            self._say('Holdings Report is only available from the SCA portfolio window — open it from there.')
            return
        match = _opie_match_portfolio_ticker(self.host, text)
        ticker = match[0] if match else None
        if not ticker and self._last_subject and self._last_subject[0] in ('stock', 'price'):
            ticker = self._last_subject[1] if self._last_subject[0] == 'price' else self._last_subject[1][0]
        opener(ticker)
        self._say(f'Opened the holdings report{f" for {ticker}" if ticker else ""}.')

    def _handle_dividend_info(self, text: str):
        """'dividend' / 'how much dividend have I received' / 'div income for
        BOTZ' — reads straight from each portfolio's _dividends log (built
        during ledger parsing — the actual paid history, not the forward-
        looking estimator). Named ticker -> that stock's own payments;
        otherwise -> the whole-portfolio total across every currency,
        same numbers as the 💵 Dividend Log popup."""
        import datetime as _dt
        portfolios = getattr(self.host, '_portfolios', None)
        if portfolios is None:
            master = getattr(self.host, 'master', None)
            portfolios = getattr(master, '_portfolios', None)
        if not portfolios:
            self._say('No portfolio loaded yet.')
            return

        match = _opie_match_portfolio_ticker(self.host, text)
        ticker = match[0] if match else None
        if not ticker and self._last_subject and self._last_subject[0] in ('stock', 'price'):
            ticker = self._last_subject[1] if self._last_subject[0] == 'price' else self._last_subject[1][0]

        rows = []   # (date, ticker, ccy, amount)
        for port_key, port in portfolios.items():
            ccy = _port_ccy(port_key)
            for date_s, amount, tkr in port.get('_dividends', []):
                if ticker and tkr != ticker:
                    continue
                try:
                    d = _dt.datetime.strptime(date_s, '%m/%d/%Y').date()
                except ValueError:
                    continue
                rows.append((d, tkr, ccy, amount))

        if not rows:
            self._say(f'No dividends recorded{f" for {ticker}" if ticker else ""} yet.')
            return

        rows.sort(key=lambda r: r[0])
        totals_by_ccy = {}
        for _, _, ccy, amount in rows:
            totals_by_ccy[ccy] = totals_by_ccy.get(ccy, 0.0) + amount
        totals_txt = '  ·  '.join(
            f'{ccy_symbol(c)}{v:,.2f} {c}' for c, v in sorted(totals_by_ccy.items()))
        last_d, last_tkr, last_ccy, last_amt = rows[-1]

        if ticker:
            self._say(f'{ticker}: {len(rows)} payment{"s" if len(rows) != 1 else ""} '
                       f'totaling {totals_txt}. Most recent: '
                       f'{ccy_symbol(last_ccy)}{last_amt:,.4f} on {last_d.strftime("%d/%m/%Y")}.')
        else:
            self._say(f'{len(rows)} dividend payment{"s" if len(rows) != 1 else ""} recorded, '
                       f'totaling {totals_txt}. Most recent: {last_tkr} '
                       f'{ccy_symbol(last_ccy)}{last_amt:,.4f} on {last_d.strftime("%d/%m/%Y")}. '
                       f'Open the 💵 Dividend Log for the full breakdown.')

    def _handle_weight(self, text: str):
        """'weight'/'allocation'/'% of portfolio' — what share of the total
        portfolio a given stock represents. Falls back to the last resolved
        stock subject if none is named in this message."""
        match = _opie_match_portfolio_ticker(self.host, text)
        if not match and self._last_subject and self._last_subject[0] == 'stock':
            match = self._last_subject[1]
        if not match:
            self._say('Which stock — try "what\'s my weight in 5398.KL?"')
            return
        ticker, item, ccy = match
        self._last_subject = ('stock', match)
        portfolios = _opie_extract_portfolios(self.host)
        prices = _opie_extract_prices(self.host)
        shares = item.get('shares', 0)
        price  = prices.get(ticker)
        if not price:
            _, price = self._current_price(ticker)
        this_value = shares * price if price else item.get('cost_value', 0.0)

        fx = _opie_extract_fx(self.host)
        def _to_myr(amount, c):
            return amount if c == 'MYR' else amount * fx.get(c, 1.0)

        total_myr = 0.0
        for port in portfolios.values():
            p_ccy = port.get('base_currency', 'USD')
            for t, it in port.get('holdings', {}).items():
                if it.get('_is_cash'):
                    continue
                sh = it.get('shares', 0)
                if not sh or sh <= 0:
                    continue
                p = prices.get(t)
                mv = sh * p if p else it.get('cost_value', 0.0)
                total_myr += _to_myr(mv, p_ccy)

        if not total_myr:
            self._say('No portfolio value on record yet to compute weight from.')
            return
        this_myr = _to_myr(this_value, ccy)
        weight_pct = this_myr / total_myr * 100
        prefix = 'RM' if ccy == 'MYR' else f'{ccy} '
        self._say(f'{ticker} is {weight_pct:.2f}% of your total portfolio '
                   f'({prefix}{this_value:,.2f} of the whole book).')

    def _handle_avg_cost(self, text: str):
        """'avg cost'/'average cost'/'breakeven' — cost basis for a named
        ticker, or the last one discussed."""
        match = _opie_match_portfolio_ticker(self.host, text)
        if not match and self._last_subject and self._last_subject[0] == 'stock':
            match = self._last_subject[1]
        if not match:
            self._say('Which stock — try "what\'s my avg cost on 5398.KL?"')
            return
        ticker, item, ccy = match
        self._last_subject = ('stock', match)
        shares   = item.get('shares', 0)
        cost_val = item.get('cost_value', 0.0)
        avg_cost = item.get('avg_cost', (cost_val / shares) if shares else 0.0)
        prefix = 'RM' if ccy == 'MYR' else f'{ccy} '
        prices = _opie_extract_prices(self.host)
        price = prices.get(ticker)
        if not price:
            _, price = self._current_price(ticker)
        live_txt = ''
        if price:
            gap = (price - avg_cost) / avg_cost * 100 if avg_cost else 0.0
            live_txt = f', live is {prefix}{price:,.4f} ({gap:+.2f}% vs breakeven)'
        self._say(f'{ticker}: avg cost {prefix}{avg_cost:,.4f} over {shares:g} shares '
                   f'(total cost {prefix}{cost_val:,.2f}){live_txt}.')

    def _handle_etf_holdings(self, text: str):
        """alpha.102 — 'top holdings <TICKER>' / 'ETF summary <TICKER>'.
        Prints the Top 10 holdings table (Feature 1) followed by Opie's
        rule-based summary (Feature 2), reusing the same disk-cache and
        ticker-matching helpers as the rest of the chat."""
        cand = _opie_best_candidate(_opie_ticker_candidates(text))
        ticker = None
        if cand:
            ticker = cand
        elif self._last_subject and self._last_subject[0] == 'etf':
            ticker = self._last_subject[1]
        if not ticker:
            self._say('Which ETF? Try "top holdings VOO" or "top holdings QQQ".')
            return
        data = _opie_fetch_etf_holdings(ticker)
        if not data.get('holdings'):
            self._say(f'Couldn\'t find ETF holdings for "{ticker}" — double-check the '
                       f'ticker (e.g. VOO, QQQ, VNQ) and try again.')
            return
        self._last_subject = ('etf', data['ticker'])
        self._say(_opie_format_holdings_table(data))
        self._say(_opie_generate_etf_summary(data))

    def _handle_full_etf_holdings(self, text: str):
        """'full holdings <TICKER>' / 'all holdings <TICKER>' / 'nport <TICKER>'.
        Complete position list straight from the ETF's latest NPORT-P filing
        with the SEC (via edgartools) — not just the Top-10. US-listed
        ETFs/funds only; gated by _is_us_listed_etf() inside the fetcher
        itself, so a Bursa/SGX/HKEX ticker or a plain stock gets a clear
        reason back instead of a crash or a silent {}."""
        cand = _opie_best_candidate(_opie_ticker_candidates(text))
        ticker = None
        if cand:
            ticker = cand
        elif self._last_subject and self._last_subject[0] == 'etf':
            ticker = self._last_subject[1]
        if not ticker:
            self._say('Which ETF? Try "full holdings VOO" or "nport SCHD".')
            return
        data = _opie_fetch_etf_full_holdings(ticker)
        if data.get('error'):
            self._say(f"Couldn't get full holdings for \"{ticker}\": {data['error']}")
            return
        if not data.get('holdings'):
            self._say(f'Couldn\'t find full SEC holdings for "{ticker}" — double-check '
                       f'the ticker and try again.')
            return
        self._last_subject = ('etf', data['ticker'])
        self._say(_opie_format_full_holdings_table(data))

    def _handle_indirect_exposure(self, text: str):
        """'indirect exposure', 'am I exposed to NVDA through my ETFs?',
        'total exposure' — the SCAIE look-through calc, now reachable from
        chat instead of only the SCA button. If a specific name is named
        (e.g. 'am I exposed to NVDA') answers just that name; otherwise
        gives the total-exposure summary (same text as SCAIE's toggle)."""
        portfolios = _opie_extract_portfolios(self.host)
        price_data = _opie_extract_prices(self.host)
        if not portfolios:
            self._say("I don't have a portfolio loaded yet to check exposure on — "
                       "connect a source first.")
            return
        exposure, etfs_used, etf_mv_total = _opie_compute_indirect_exposure(
            portfolios, price_data)
        if not etfs_used:
            self._say("You're not holding any US ETFs/funds I can look through right "
                       "now, so there's no indirect exposure to report.")
            return

        cand = _opie_best_candidate(_opie_ticker_candidates(text))
        if cand:
            rec = exposure.get(cand.upper())
            if not rec:
                # loose match on name/symbol substring
                for sym, r in exposure.items():
                    if cand.upper() in sym.upper() or cand.upper() in (r.get('name') or '').upper():
                        rec = r; cand = sym
                        break
            if rec:
                pct = (rec['value'] / etf_mv_total * 100) if etf_mv_total else 0.0
                self._say(f"You've got about ${rec['value']:,.2f} ({pct:.2f}% of your "
                          f"ETF market value) of indirect exposure to {cand} through "
                          f"{', '.join(sorted(rec['via']))}.")
                return
            self._say(f"I don't see {cand.upper()} showing up in the top-10 holdings "
                      f"of any ETF you hold — it might just not be a large enough "
                      f"position in those funds to show up.")
            return

        self._last_subject = ('indirect_exposure', None)
        self._say(_opie_format_indirect_exposure_summary(exposure, etfs_used, etf_mv_total))

    def _handle_indirect_fallers(self, text: str, worst: bool = True):
        """'who fell so much' / 'biggest fallers' / 'biggest uppers' — same
        look-through universe as indirect exposure, but ranked by today's
        day-change % instead of $ exposure. Chat equivalent of SCAIE's
        🔻 Biggest Fallers / 🚀 Biggest Uppers toggles. worst=True -> fallers
        (biggest decline first), worst=False -> uppers (biggest gain first)."""
        portfolios = _opie_extract_portfolios(self.host)
        price_data = _opie_extract_prices(self.host)
        if not portfolios:
            self._say("I don't have a portfolio loaded yet to check on — "
                       "connect a source first.")
            return
        exposure, etfs_used, etf_mv_total = _opie_compute_indirect_exposure(
            portfolios, price_data)
        if not etfs_used:
            what = 'fallers' if worst else 'uppers'
            self._say(f"You're not holding any US ETFs/funds I can look through right "
                       f"now, so there's nothing to check for {what}.")
            return

        by_exposure = sorted(exposure.items(), key=lambda kv: kv[1]['value'], reverse=True)
        top_syms = [sym for sym, _ in by_exposure[:20]]
        day_chg = _opie_fetch_underlying_day_change(top_syms)
        ranked = sorted(
            ((sym, rec, day_chg[sym]) for sym, rec in by_exposure if sym in day_chg),
            key=lambda t: t[2], reverse=not worst
        )
        if not ranked:
            self._say("Couldn't pull today's move for your underlyings right now — try again shortly.")
            return

        movers = ranked[:5]
        lines = ', '.join(f"{sym} {chg:+.2f}% (via {', '.join(sorted(rec['via']))})"
                          for sym, rec, chg in movers)
        label = 'Biggest fallers' if worst else 'Biggest uppers'
        self._say(f"{label} today among your indirect exposure: {lines}.")

    def _handle_fund(self, text: str):
        match = self._match_fund(self.host, text)
        if match:
            self._say_fund_value(match)
            return
        self._awaiting_fund = True
        labels = [lbl for lbl, _ in _opie_fund_catalog(self.host)]
        self._say('Which fund do you mean — ' + ', '.join(labels) + '?')

    def _answer_fund(self, text: str):
        self._awaiting_fund = False
        match = self._match_fund(self.host, text)
        if not match:
            self._say(f'Couldn\'t match "{text}" to a tracked fund — try one of the names above.')
            return
        if self._pending_invest:
            amount, ccy = self._pending_invest
            self._pending_invest = None
            app = _opie_dashboard_app(self.host)
            self._say_invest_result(app, match[0], amount, ccy)
            return
        self._say_fund_value(match)

    def _say_fund_value(self, match):
        label, ccy = match
        self._last_subject = ('fund', match)
        app = _opie_dashboard_app(self.host)
        df = getattr(app, 'all_frames', {}).get(label)
        if df is None or df.empty or label not in df.columns:
            self._say(f'No NAV data for {label} yet.')
            return
        s = df[label].dropna()
        if s.empty:
            self._say(f'No priced NAV for {label} yet.')
            return
        last = float(s.iloc[-1])
        chg_pct = None
        if len(s) > 1:
            prev = float(s.iloc[-2])
            if prev:
                chg_pct = (last - prev) / prev * 100
        chg_txt = f', {chg_pct:+.2f}% vs previous close' if chg_pct is not None else ''
        self._say(f'{label} NAV is currently {last:,.4f} {ccy}{chg_txt}.')

    def _handle_invest(self, text: str):
        """'invest $10,000 in <fund>' — historical backtest via the
        dashboard's _calc_fund_return (same engine as the Return Calculator
        button on the VFund Events tab). Explicitly framed as a backtest,
        not a forecast — see _say_invest_result."""
        app = _opie_dashboard_app(self.host)
        if not hasattr(app, '_calc_fund_return'):
            self._say("Return calculator isn't available from here yet.")
            return
        m = re.search(r'([\d,]+(?:\.\d+)?)', text)
        if not m:
            self._say('How much would you like to invest, and in which fund?')
            return
        amount = float(m.group(1).replace(',', ''))
        ccy = _opie_parse_currency(text) or 'MYR'
        match = self._match_fund(self.host, text)
        if not match:
            self._pending_invest = (amount, ccy)
            self._awaiting_fund = True
            labels = [lbl for lbl, _ in _opie_fund_catalog(self.host)]
            self._say('Which fund do you want to invest in — ' + ', '.join(labels) + '?')
            return
        self._say_invest_result(app, match[0], amount, ccy)

    def _say_invest_result(self, app, label, amount, ccy):
        res = app._calc_fund_return(label, amount, ccy)
        if 'error' in res:
            self._say(f"⚠️ {res['error']}")
            return
        sign = '+' if res['return_pct'] >= 0 else ''
        self._say(
            f"Backtest, not a forecast: {amount:,.2f} {ccy} invested in {label} "
            f"at launch ({res['entry_date'].date()}, NAV {res['entry_nav']:.4f} "
            f"{res['fund_ccy']}) would be worth {res['current_value']:,.2f} {ccy} "
            f"today ({res['latest_date'].date()}) — {sign}{res['return_pct']:.2f}%."
        )

    # ── SUMMARY — ticker or whole-portfolio, currency-aware, remembers
    #    what was recently asked ──────────────────────────────────────────
    def _summary_currency_pref(self):
        settings = load_app_settings()
        return settings.get('opie_summary_prefs', {}).get(self.kid.lower(), {}).get('currency')

    def _set_summary_currency_pref(self, ccy: str):
        settings = load_app_settings()
        prefs = settings.setdefault('opie_summary_prefs', {}).setdefault(self.kid.lower(), {})
        prefs['currency'] = ccy
        save_app_settings(settings)

    def _log_recent_asked(self, text: str):
        """Keep the last 10 non-trivial things this K-ID has asked Opie, so
        summaries (and Opie itself) can reference 'what you usually ask'."""
        settings = load_app_settings()
        recent = settings.setdefault('opie_recent_asked', {}).setdefault(self.kid.lower(), [])
        recent.append(text.strip())
        del recent[:-10]
        save_app_settings(settings)

    def _handle_summary(self, text: str):
        """'summary' — continuation-aware: a named/last-discussed ticker
        gets a per-position summary, otherwise the whole portfolio.
        Currency: uses one already in the message (existing
        _opie_parse_currency), else the saved preference, else asks once
        and remembers the answer for next time."""
        match = _opie_match_portfolio_ticker(self.host, text)
        if not match and self._last_subject and self._last_subject[0] == 'stock':
            match = self._last_subject[1]
        target = ('ticker', match) if match else ('portfolio', None)

        ccy = _opie_parse_currency(text) or self._summary_currency_pref()
        if not ccy:
            self._pending_summary = target
            self._awaiting_summary_currency = True
            self._say('Which currency should I show the summary in — MYR or USD?')
            return
        self._say_summary(target, ccy)

    def _answer_summary_currency(self, text: str):
        self._awaiting_summary_currency = False
        ccy = _opie_parse_currency(text)
        if not ccy:
            self._say('Sorry, I didn\'t catch a currency — try MYR or USD.')
            self._awaiting_summary_currency = True
            return
        self._set_summary_currency_pref(ccy)
        target, self._pending_summary = self._pending_summary, None
        self._say_summary(target, ccy)

    def _say_summary(self, target, ccy: str):
        kind, match = target
        prefix = 'RM' if ccy == 'MYR' else f'{ccy} '
        if kind == 'ticker':
            ticker, item, item_ccy = match
            self._last_subject = ('stock', match)
            fx = _opie_extract_fx(self.host)
            def _to_ccy(amount, c):
                if c == ccy:
                    return amount
                myr = amount if c == 'MYR' else amount * fx.get(c, 1.0)
                if ccy == 'MYR':
                    return myr
                rate = fx.get(ccy)
                return (myr / rate) if rate else amount
            prices = _opie_extract_prices(self.host)
            shares = item.get('shares', 0)
            cost   = item.get('cost_value', 0.0)
            price  = prices.get(ticker) or self._current_price(ticker)[1]
            value  = shares * price if price else cost
            gain   = value - cost
            pct    = (gain / cost * 100) if cost > 0 else 0.0
            recent_buys = sorted(
                [t for t in item.get('transactions', []) if t[0] == 'buy'],
                key=lambda t: t[1], reverse=True)[:3]
            buys_txt = '; '.join(f'{t[1]}: +{t[2]:g} @ {t[3]:,.4f}' for t in recent_buys) or 'none on record'
            self._say(f'{ticker} summary — {shares:g} shares, avg cost '
                       f'{prefix}{_to_ccy(cost / shares if shares else 0, item_ccy):,.4f}, '
                       f'worth {prefix}{_to_ccy(value, item_ccy):,.2f}, '
                       f'unrealized {prefix}{_to_ccy(gain, item_ccy):+,.2f} ({pct:+.2f}%). '
                       f'Recent buys: {buys_txt}.')
            return

        portfolios = _opie_extract_portfolios(self.host)
        if not portfolios:
            self._say('No portfolio loaded yet — connect a source first.')
            return
        fx = _opie_extract_fx(self.host)
        prices = _opie_extract_prices(self.host)
        def _to_ccy(amount, c):
            if c == ccy:
                return amount
            myr = amount if c == 'MYR' else amount * fx.get(c, 1.0)
            if ccy == 'MYR':
                return myr
            rate = fx.get(ccy)
            return (myr / rate) if rate else amount

        cost_total, mv_total, positions = 0.0, 0.0, 0
        all_buys = []
        for port in portfolios.values():
            p_ccy = port.get('base_currency', 'USD')
            for ticker, item in port.get('holdings', {}).items():
                if item.get('_is_cash'):
                    continue
                shares = item.get('shares', 0)
                if not shares or shares <= 0:
                    continue
                positions += 1
                cost_total += _to_ccy(item.get('cost_value', 0.0), p_ccy)
                price = prices.get(ticker)
                mv = shares * price if price else item.get('cost_value', 0.0)
                mv_total += _to_ccy(mv, p_ccy)
                for t in item.get('transactions', []):
                    if t[0] == 'buy':
                        all_buys.append((ticker, t))
        gain = mv_total - cost_total
        pct  = (gain / cost_total * 100) if cost_total > 0 else 0.0
        recent_buys = sorted(all_buys, key=lambda x: x[1][1], reverse=True)[:5]
        buys_txt = '; '.join(f'{tk} {t[1]}: +{t[2]:g} @ {t[3]:,.4f}' for tk, t in recent_buys) or 'none on record'
        self._say(f'Portfolio summary ({ccy}): {positions} position(s), '
                   f'value {prefix}{mv_total:,.2f}, '
                   f'unrealized {prefix}{gain:+,.2f} ({pct:+.2f}%). '
                   f'Recently bought: {buys_txt}.')

    def _handle_summary_settings(self, text: str):
        """'summary settings' / 'set summary on open' / 'set summary time
        9:00am' / 'turn off summary schedule' — configures the per-K-ID
        auto-summary popup shown when SCA opens."""
        low = text.lower()
        settings = load_app_settings()
        prefs = settings.setdefault('opie_summary_prefs', {}).setdefault(self.kid.lower(), {})

        if re.search(r'\boff\b|\bstop\b|\bdisable\b', low):
            prefs['schedule_mode'] = 'off'
            save_app_settings(settings)
            self._say('Turned off the auto-summary popup.')
            return

        if re.search(r'\bon\s*open\b|\bevery time\b|\bwhen(ever)? i open\b', low):
            prefs['schedule_mode'] = 'on_open'
            save_app_settings(settings)
            self._say('Got it — I\'ll show a portfolio summary every time you open SCA.')
            return

        m = re.search(r'\b(\d{1,2}):?(\d{2})?\s*(am|pm)?\b', low)
        if m and re.search(r'\btime\b|\bdaily\b|\bfixed\b|\bam\b|\bpm\b|:\d{2}', low):
            h = int(m.group(1)); mnt = int(m.group(2) or 0)
            if m.group(3) == 'pm' and h < 12:
                h += 12
            if m.group(3) == 'am' and h == 12:
                h = 0
            prefs['schedule_mode'] = 'fixed_time'
            prefs['fixed_time'] = f'{h:02d}:{mnt:02d}'
            save_app_settings(settings)
            self._say(f'Got it — I\'ll show a portfolio summary once a day, '
                       f'the first time you open SCA at or after {prefs["fixed_time"]}.')
            return

        mode = prefs.get('schedule_mode', 'off')
        detail = f' at {prefs.get("fixed_time", "09:00")}' if mode == 'fixed_time' else ''
        self._say(f'Auto-summary is currently "{mode}"{detail}. Try "set summary on open", '
                   f'"set summary time 9:00am", or "turn off summary schedule".')

    def _handle_how_much(self, text: str):
        portfolios = _opie_extract_portfolios(self.host)
        if not portfolios:
            self._say('No portfolio loaded yet — connect a source first.')
            return
        fx     = _opie_extract_fx(self.host)
        prices = _opie_extract_prices(self.host)
        target = _opie_parse_currency(text)
        ccy_counts = {}
        for port in portfolios.values():
            c = port.get('base_currency', 'USD')
            ccy_counts[c] = ccy_counts.get(c, 0) + 1
        if not target:
            target = get_home_currency() if ccy_counts else 'MYR'

        def _to_target(amount, ccy):
            if ccy == target:
                return amount
            # fx is keyed ccy -> home-currency (pivot), whatever that is —
            # not necessarily MYR.
            amount_pivot = amount * fx.get(ccy, 1.0)
            rate = fx.get(target)
            return (amount_pivot / rate) if rate else amount_pivot

        cost_total, mv_total, positions = 0.0, 0.0, 0
        unresolved = False
        for port in portfolios.values():
            ccy = port.get('base_currency', 'USD')
            for ticker, item in port.get('holdings', {}).items():
                if item.get('_is_cash'):
                    continue
                shares = item.get('shares', 0)
                if not shares or shares <= 0:
                    continue
                positions += 1
                cost = _to_target(item.get('cost_value', 0.0), ccy)
                price = prices.get(ticker)
                mv = _to_target(shares * price, ccy) if price else cost
                if cost is None or mv is None:
                    unresolved = True
                    continue
                cost_total += cost
                mv_total   += mv

        if unresolved and positions and cost_total == 0:
            self._say(f'No exchange rate available for {target} yet — try MYR or USD.')
            return

        gain = mv_total - cost_total
        pct  = (gain / cost_total * 100) if cost_total > 0 else 0.0
        prefix = 'RM' if target == 'MYR' else f'{target} '
        self._say(f'Full summary in {target}: {positions} position(s), '
                   f'value {prefix}{mv_total:,.2f}, '
                   f'unrealized {prefix}{gain:+,.2f} ({pct:+.2f}%).')

    # ── PTS / ZDWS / ZDOS order opening ─────────────────────────────────
    def _trade_host(self):
        """The MYIPOApp instance that actually owns the PTS/ZDWS/ZDOS wallet
        and open_position methods — self.host is that instance directly on
        the dashboard, or its master when opened from inside SCA."""
        if hasattr(self.host, '_zdws_open_position'):
            return self.host
        master = getattr(self.host, 'master', None)
        if master is not None and hasattr(master, '_zdws_open_position'):
            return master
        return None

    def _handle_open_order(self, text: str):
        """'open' + PTS/ZDWS/ZDOS/order/position keyword — gate on a
        one-time permission grant, then start (or continue) the guided
        order-builder."""
        settings = load_app_settings()
        granted = settings.get('opie_trade_permission', {}).get(self.kid.lower(), False)
        if not granted:
            self._awaiting_permission = True
            self._pending_order_text  = text
            self._say('I can open PTS / ZDWS / ZDOS positions for you, but I need '
                       'your permission first (one-time) — reply "yes" to grant it, '
                       'or "no" to skip.')
            return
        self._order = self._order or {}
        self._continue_order(text)

    def _resolve_permission(self, text: str):
        self._awaiting_permission = False
        low = text.strip().lower()
        grant = bool(re.search(r'\b(yes|y|ok|okay|sure|yeah|yep|grant|granted|allow)\b', low))
        deny  = bool(re.search(r'\b(no|nope|nah|never|skip|deny|cancel)\b', low))
        if grant and not deny:
            settings = load_app_settings()
            perms = settings.setdefault('opie_trade_permission', {})
            perms[self.kid.lower()] = True
            save_app_settings(settings)
            self._say('Permission granted — I can open orders for you from now on.')
            pending, self._pending_order_text = self._pending_order_text, None
            self._order = self._order or {}
            if pending:
                self._continue_order(pending)
        else:
            self._pending_order_text = None
            self._order = None
            self._say('No problem — I won\'t open any orders. Just ask again anytime.')

    def _continue_order(self, text: str):
        """Fill the in-progress order one field at a time: system → side →
        underlying → stake → settlement horizon → confirm. Each step tries
        to parse straight out of free text before falling back to asking."""
        order = self._order if self._order is not None else {}
        self._order = order
        low = text.lower()

        if not order.get('system'):
            if re.search(r'\bzdws\b', low):
                order['system'] = 'ZDWS'
            elif re.search(r'\bzdos\b', low):
                order['system'] = 'ZDOS'
            elif re.search(r'\bpts\b', low):
                order['system'] = 'PTS'
        if not order.get('system'):
            self._awaiting_order_field = 'system'
            self._say('Which desk — PTS, ZDWS, or ZDOS?')
            return

        if order['system'] == 'PTS':
            self._continue_pts_order(text, order)
        else:
            self._continue_market_order(text, order)

    def _continue_market_order(self, text: str, order: dict):
        """ZDWS (BULL/BEAR warrant) or ZDOS (CALL/PUT option) field collection."""
        low = text.lower()
        is_zdos = order['system'] == 'ZDOS'

        if not order.get('side'):
            if is_zdos:
                if re.search(r'\blong\s*call\b', low) or (re.search(r'\bcall\b', low) and re.search(r'\blong\b', low)):
                    order['side'] = 'LONG_CALL'
                elif re.search(r'\bshort\s*call\b', low) or (re.search(r'\bcall\b', low) and re.search(r'\bshort\b', low)):
                    order['side'] = 'SHORT_CALL'
                elif re.search(r'\blong\s*put\b', low) or (re.search(r'\bput\b', low) and re.search(r'\blong\b', low)):
                    order['side'] = 'LONG_PUT'
                elif re.search(r'\bshort\s*put\b', low) or (re.search(r'\bput\b', low) and re.search(r'\bshort\b', low)):
                    order['side'] = 'SHORT_PUT'
            else:
                if re.search(r'\bbull\b', low):
                    order['side'] = 'BULL'
                elif re.search(r'\bbear\b', low):
                    order['side'] = 'BEAR'
        if not order.get('side'):
            self._awaiting_order_field = 'side'
            opts = 'LONG_CALL, SHORT_CALL, LONG_PUT, or SHORT_PUT' if is_zdos else 'BULL or BEAR'
            self._say(f'Which side — {opts}?')
            return

        if not order.get('underlying'):
            match = _opie_match_portfolio_ticker(self.host, text)
            idx   = self._match_index(self.host, text)
            if match:
                order['underlying'] = match[0]
            elif idx:
                order['underlying'] = idx[0]
            elif self._last_subject and re.search(r"\b(it|that|this)\b", low):
                if self._last_subject[0] == 'stock':
                    order['underlying'] = self._last_subject[1][0]
                elif self._last_subject[0] == 'index':
                    order['underlying'] = self._last_subject[1][0]
                elif self._last_subject[0] == 'price':
                    order['underlying'] = self._last_subject[1]
            else:
                cand = _opie_best_candidate(_opie_ticker_candidates(text))
                if cand:
                    order['underlying'] = cand
        if not order.get('underlying'):
            self._awaiting_order_field = 'underlying'
            self._say('Which underlying — a ticker or an index name?')
            return

        if order.get('tier') is None and is_zdos:
            m = re.search(r'\btier\s*(\d+)\b', low) or re.search(r'\bt(\d+)\b', low)
            if m:
                order['tier'] = int(m.group(1))
            elif re.search(r'\bat[- ]?the[- ]?money\b|\batm\b', low):
                order['tier'] = 0
        if order.get('tier') is None and is_zdos:
            self._awaiting_order_field = 'tier'
            self._say('Which strike tier (e.g. 0 for at-the-money, 1, 2, -1)?')
            return

        if not order.get('stake'):
            m = re.search(r'(\d[\d,]*\.?\d*)\s*(cr|credits?)?\b', low.replace(',', ''))
            if m:
                try:
                    order['stake'] = float(m.group(1))
                except ValueError:
                    pass
        if not order.get('stake'):
            self._awaiting_order_field = 'stake'
            self._say('How many credits do you want to stake?')
            return

        if not order.get('days'):
            m = re.search(r'\b(\d+)\s*day', low)
            if 'daily' in low:
                order['days'] = 1
            elif m:
                order['days'] = int(m.group(1))
        if not order.get('days'):
            self._awaiting_order_field = 'days'
            self._say('How many days out should it settle — e.g. "daily", "7", "30"?')
            return

        self._awaiting_order_field = None
        self._execute_market_order(order)

    def _execute_market_order(self, order: dict):
        host = self._trade_host()
        if host is None:
            self._say('Trading isn\'t available from this window right now — open OPIE from the dashboard instead.')
            self._order = None
            return
        settle_pairs = host._pts_settlement_dates(include_daily=(order['system'] == 'ZDWS'))
        wanted = order['days']
        best_label, best_date, best_diff = None, None, None
        import datetime as _dt
        today = _dt.date.today()
        for lbl, d in settle_pairs.items():
            diff = abs((d - today).days - wanted)
            if best_diff is None or diff < best_diff:
                best_label, best_date, best_diff = lbl, d, diff
        if best_date is None:
            self._say('Couldn\'t find a valid settlement date for that — try again with a different horizon.')
            self._order = None
            return
        settle_str = best_date.strftime('%d/%m/%Y')
        if order['system'] == 'ZDWS':
            ok = host._zdws_open_position(order['underlying'], order['side'], order['stake'], settle_str)
            msg = (f'ZDWS opened: {order["side"]} {order["underlying"]}  ·  '
                   f'{order["stake"]:,.0f} credits  ·  settles {settle_str}.') if ok else \
                  'Couldn\'t open that ZDWS position — check the underlying has a live price and you have enough credits.'
        else:
            ok = host._zdos_open_position(order['underlying'], order['side'], order['tier'],
                                           order['stake'], settle_str)
            msg = (f'ZDOS opened: {order["side"].replace("_"," ").title()} T{order["tier"]} '
                   f'{order["underlying"]}  ·  {order["stake"]:,.0f} credits  ·  '
                   f'settles {settle_str}.') if ok else \
                  'Couldn\'t open that ZDOS position — check the underlying has a live price and you have enough credits.'
        self._say(msg)
        self._order = None

    def _continue_pts_order(self, text: str, order: dict):
        """PTS custom YES/NO prediction field collection."""
        low = text.lower()

        if not order.get('question'):
            # Whatever's left after stripping the trigger words is treated
            # as the prediction question, if there's enough of it.
            stripped = re.sub(r'\b(open|pts|please|can|you|help|me)\b', '', low).strip(' ?.!')
            if len(stripped) > 6:
                order['question'] = text.strip()
        if not order.get('question'):
            self._awaiting_order_field = 'question'
            self._say('What\'s the prediction question?')
            return

        if not order.get('position'):
            if re.search(r'\byes\b', low):
                order['position'] = 'YES'
            elif re.search(r'\bno\b', low):
                order['position'] = 'NO'
        if not order.get('position'):
            self._awaiting_order_field = 'position'
            self._say('YES or NO?')
            return

        if not order.get('stake'):
            m = re.search(r'(\d[\d,]*\.?\d*)\s*(cr|credits?)?\b', low.replace(',', ''))
            if m:
                try:
                    order['stake'] = float(m.group(1))
                except ValueError:
                    pass
        if not order.get('stake'):
            self._awaiting_order_field = 'stake'
            self._say('How many credits do you want to stake?')
            return

        if not order.get('days'):
            m = re.search(r'\b(\d+)\s*day', low)
            if m:
                order['days'] = int(m.group(1))
        if not order.get('days'):
            self._awaiting_order_field = 'days'
            self._say('How many days until it resolves (minimum 7)?')
            return

        self._awaiting_order_field = None
        host = self._trade_host()
        if host is None:
            self._say('Trading isn\'t available from this window right now — open OPIE from the dashboard instead.')
            self._order = None
            return
        import datetime as _dt
        deadline = _dt.date.today() + _dt.timedelta(days=max(order['days'], 7))
        ok, msg = host._pts_open_custom_prediction(order['question'], order['position'],
                                                     order['stake'], deadline)
        self._say(msg)
        self._order = None


def _opie_open_chat(parent, host, kid_username: str):
    """Open (or focus) the single OPIE popup chat window for this parent."""
    win = getattr(parent, '_opie_chat_win', None)
    if win is not None and win.winfo_exists():
        win.lift()
        win.focus_set()
        return
    win = OpieChatWindow(parent, host, kid_username)
    parent._opie_chat_win = win


# ── SCA portfolio source (per K-ID) ──────────────────────────────────────────
# The signed-in user's own sheet/CSV. Falls back to the built-in demo sheet
# when a user hasn't configured one yet.
CURRENT_KID = ''   # set at login; '' = no account (legacy PIN mode)
CURRENT_OPIE = None  # authenticated user's OPIE coordinator; set by AppLockScreen

# ── Presence / online-status heartbeat ───────────────────────────────────────
PRESENCE_ONLINE_SECS = 300   # 'online' = seen within the last 5 minutes
_presence_last_write = 0.0   # module-level throttle so we don't hammer disk

def presence_touch(login: bool = False):
    """Record that CURRENT_KID is active right now. Writes at most once per
    60s (unless it's the login event itself) — called from login and from
    every wallet load, so any gameplay keeps the heartbeat fresh."""
    global _presence_last_write
    import time as _t, datetime as _dt
    kid = (CURRENT_KID or '').strip().lower()
    if not kid:
        return
    now = _t.time()
    if not login and now - _presence_last_write < 60:
        return
    _presence_last_write = now
    try:
        s = load_app_settings()
        rec = s.setdefault('presence', {}).setdefault(kid, {})
        stamp = _dt.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        rec['last_seen'] = stamp
        if login:
            rec['last_login'] = stamp
        save_app_settings(s)
    except Exception:
        pass


def sca_normalise_sheet_url(url: str) -> str:
    """Accept any Google Sheets URL form and return a CSV-export URL.
    Handles: /pub?output=csv, /pubhtml, /edit#gid=N, and bare doc URLs."""
    u = (url or '').strip()
    if not u:
        return ''
    if 'output=csv' in u:
        return u
    # Published-to-web form: .../e/2PACX-.../pubhtml  ->  .../pub?output=csv
    if '/pubhtml' in u:
        return u.split('/pubhtml')[0] + '/pub?gid=0&single=true&output=csv'
    # Standard edit URL: .../d/<ID>/edit#gid=123  ->  .../d/<ID>/export?format=csv&gid=123
    import re as _re
    m = _re.search(r'/spreadsheets/d/([a-zA-Z0-9-_]+)', u)
    if m:
        doc_id = m.group(1)
        gid_m  = _re.search(r'[#&?]gid=(\d+)', u)
        gid    = gid_m.group(1) if gid_m else '0'
        return (f'https://docs.google.com/spreadsheets/d/{doc_id}'
                f'/export?format=csv&gid={gid}')
    return u   # not recognisable — hand back unchanged, let the fetch fail loudly


def sca_has_source(settings: dict, username: str = None) -> bool:
    """True if this K-ID has explicitly chosen a portfolio source.
    A missing entry means first run — SCA should force setup rather than
    quietly showing demo data as if it were theirs."""
    u = (username if username is not None else CURRENT_KID) or ''
    src = settings.get('sca_sources', {}).get(u)
    return bool(src and src.get('mode'))


# ── K-ID recovery — knowledge questions from the user's own ledger ───────────
# If someone forgets their PIN, they can prove ownership by answering questions
# only the portfolio owner would know: what they bought today, what they hold
# most of, and so on. Questions are generated live from their OWN sheet/CSV,
# so there is nothing extra to store and nothing to keep in sync.
#
# NOTE ON STRENGTH: this is deliberate, proportionate security for a local
# desktop app — it stops a housemate poking at your laptop. It is NOT strong
# auth: anyone who can already read your sheet can answer these. The real
# protection on the ledger is Google's own sharing settings / file permissions.

def kid_recovery_questions(rows: list, portfolios: dict, n: int = 3) -> list:
    """Build multiple-choice questions from a ledger.
    Returns [{'q': str, 'options': [str], 'answer': str}] — at most n of them.
    Returns [] when there isn't enough history to ask anything meaningful.
    """
    import random as _rnd
    import datetime as _d

    qs = []

    # Flatten non-cash holdings across every portfolio
    holds = []   # (ticker, units, port_key)
    for pk, port in (portfolios or {}).items():
        for tkr, item in port.get('holdings', {}).items():
            if item.get('_is_cash'):
                continue
            if item.get('shares', 0) > 0:
                holds.append((tkr, item['shares'], pk))

    def _decoys(correct, pool, k=3):
        """Wrong answers drawn from the user's own universe where possible —
        a decoy they've never heard of would give the answer away."""
        cand = [x for x in pool if x != correct]
        _rnd.shuffle(cand)
        out = cand[:k]
        if len(out) < k:
            extra = [c for c, _ in LOTTO_STOCK_LIST if c != correct and c not in out]
            _rnd.shuffle(extra)
            out += extra[:k - len(out)]
        return out

    # ── Q1: most-held by units ────────────────────────────────────────────────
    if len(holds) >= 4:
        by_units = sorted(holds, key=lambda x: -x[1])
        top = by_units[0][0]
        # Only ask if there's a clear winner — a near-tie is unfair
        if len(by_units) < 2 or by_units[0][1] > by_units[1][1] * 1.05:
            pool = [t for t, _, _ in by_units]
            opts = [top] + _decoys(top, pool)
            _rnd.shuffle(opts)
            qs.append({
                'q':       'Which holding do you own the MOST units of?',
                'options': opts,
                'answer':  top,
            })

    # ── Q2: what you bought today (or most recently) ──────────────────────────
    buys = []
    for r in (rows or []):
        if r.get(_NC_TYPE, '').strip().lower() != 'buy':
            continue
        ds = r.get(_NC_DATE, '').strip()
        d  = None
        for fmt in ('%m/%d/%Y', '%d/%m/%Y', '%Y-%m-%d', '%m-%d-%Y'):
            try:
                d = _d.datetime.strptime(ds, fmt).date(); break
            except ValueError:
                continue
        if d:
            buys.append((d, r.get(_NC_ASSET, '').strip().upper()))
    if len(buys) >= 4:
        buys.sort(key=lambda x: -x[0].toordinal())
        last_date, last_asset = buys[0]
        today = _d.date.today()
        label = ('buy TODAY' if last_date == today
                 else f'buy most recently ({last_date.strftime("%d %b %Y")})')
        pool  = [a for _, a in buys]
        opts  = [last_asset] + _decoys(last_asset, pool)
        _rnd.shuffle(opts)
        qs.append({
            'q':       f'Which asset did you {label}?',
            'options': opts,
            'answer':  last_asset,
        })

    # ── Q3: first asset ever bought ───────────────────────────────────────────
    if len(buys) >= 5:
        first_date, first_asset = min(buys, key=lambda x: x[0].toordinal())
        pool = [a for _, a in buys]
        opts = [first_asset] + _decoys(first_asset, pool)
        _rnd.shuffle(opts)
        qs.append({
            'q':       'Which asset did you buy FIRST, when you started?',
            'options': opts,
            'answer':  first_asset,
        })

    # ── Q4: position count (fallback / extra) ─────────────────────────────────
    if len(holds) >= 3:
        n_pos = len(holds)
        opts  = {str(n_pos)}
        for delta in (-3, -2, -1, 1, 2, 3, 5):
            if n_pos + delta > 0:
                opts.add(str(n_pos + delta))
        opts = list(opts)
        _rnd.shuffle(opts)
        opts = ([str(n_pos)] + [o for o in opts if o != str(n_pos)][:3])
        _rnd.shuffle(opts)
        qs.append({
            'q':       'How many separate positions do you currently hold?',
            'options': opts,
            'answer':  str(n_pos),
        })

    _rnd.shuffle(qs)
    return qs[:n]


def kid_load_recovery_data(settings: dict, username: str):
    """Load a user's ledger for recovery WITHOUT signing them in.
    Returns (rows, portfolios) or (None, None) if unreachable."""
    global CURRENT_KID
    src = settings.get('sca_sources', {}).get(username or '')
    if not src or not src.get('mode'):
        return None, None
    saved_kid = CURRENT_KID
    try:
        CURRENT_KID = username          # so per-user cache paths resolve
        if src['mode'] == 'csv' and src.get('csv_path'):
            if not os.path.exists(src['csv_path']):
                return None, None
            with open(src['csv_path'], 'r', encoding='utf-8-sig') as f:
                rows = _mf_parse_rows(f.read())
        else:
            rows = _mf_load_csv(url=src.get('url'))
        ports = _mf_build_portfolios(rows)
        return rows, ports
    except Exception:
        return None, None
    finally:
        CURRENT_KID = saved_kid


def kid_reset_pin(settings: dict, username: str, new_pin: str) -> tuple:
    """Set a new PIN after successful recovery. Returns (ok, message)."""
    if not (new_pin.isdigit() and 4 <= len(new_pin) <= 8):
        return False, 'PIN must be 4–8 digits.'
    acc = kid_find_account(settings, username)
    if not acc:
        return False, 'K-ID not found.'
    acc['pin_hash'] = kid_hash_pin(username, new_pin)
    save_app_settings(settings)
    return True, 'PIN reset. Sign in with your new PIN.'


def sca_get_source(settings: dict, username: str = None) -> dict:
    """Return the SCA source config for a user.
    Shape: {"mode": "sheet"|"csv"|"demo", "url": str, "csv_path": str, "label": str}
    """
    u = (username if username is not None else CURRENT_KID) or ''
    src = settings.get('sca_sources', {}).get(u)
    if src and (src.get('url') or src.get('csv_path')):
        return src
    return {'mode': '', 'url': '', 'csv_path': '',
            'label': 'No portfolio connected'}


def sca_save_source(settings: dict, username: str, mode: str,
                    url: str = '', csv_path: str = '', label: str = '') -> dict:
    """Persist a user's SCA source and return the saved record."""
    import datetime as _d
    rec = {
        'mode':     mode,
        'url':      sca_normalise_sheet_url(url) if mode == 'sheet' else '',
        'csv_path': csv_path if mode == 'csv' else '',
        'label':    label or ('My Google Sheet' if mode == 'sheet' else 'Imported CSV'),
        'saved':    _d.datetime.now().strftime('%Y-%m-%d %H:%M'),
    }
    settings.setdefault('sca_sources', {})[username or ''] = rec
    save_app_settings(settings)
    return rec


import copy as _copy


def _pts_fresh_wallet() -> dict:
    """A brand-new PTS/ZDWS wallet. Deep-copied so the mutable lists in
    _DEFAULT_SETTINGS are never shared between K-IDs."""
    return _copy.deepcopy(_DEFAULT_SETTINGS['pts'])


def load_app_settings() -> dict:
    if os.path.exists(_SETTINGS_PATH):
        try:
            with open(_SETTINGS_PATH, 'r', encoding='utf-8') as f:
                data = _json.load(f)
            merged = dict(_DEFAULT_SETTINGS)
            merged.update(data)
            return merged
        except Exception:
            pass
    return dict(_DEFAULT_SETTINGS)


def save_app_settings(settings: dict):
    """Persist app settings to disk, next to the script."""
    try:
        with open(_SETTINGS_PATH, 'w', encoding='utf-8') as f:
            _json.dump(settings, f, indent=2)
    except Exception:
        pass


_SUPPORTED_HOME_CCYS = ("MYR", "USD", "HKD", "SGD", "AUD", "THB", "IDR")

def get_home_currency() -> str:
    """The currency every SCA total/roll-up converts into. User-set via
    ⚙ Settings (dashboard) or SCA's own Settings panel. Defaults to MYR."""
    ccy = (load_app_settings().get('home_currency') or 'MYR').upper().strip()
    return ccy if ccy in _SUPPORTED_HOME_CCYS else 'MYR'


def set_home_currency(ccy: str):
    ccy = (ccy or 'MYR').upper().strip()
    if ccy not in _SUPPORTED_HOME_CCYS:
        return
    s = load_app_settings()
    s['home_currency'] = ccy
    save_app_settings(s)


# ── Admin temporary recovery phrase (generated from the sign-in screen) ─────
# "Forgot recovery phrase" on the outside: after admin1 + PIN are verified, a
# fresh 16-hex single-use phrase is written to a .txt next to paa_settings.json
# (only its SHA-256 goes into settings), the emergency lock is engaged, and the
# phrase expires after ADMIN_TEMP_RECOVERY_MINUTES. The existing
# _admin_recovery_flow() consumes it exactly like a phrase minted from inside.
ADMIN_TEMP_RECOVERY_MINUTES = 30
ADMIN_TEMP_RECOVERY_TXT     = 'PAA_ADMIN_TEMP_RECOVERY.txt'


def admin_temp_recovery_issue(settings: dict, folder: str = None, now: float = None):
    """Mint a temporary recovery phrase and write it to a txt file.
    Mutates `settings` (caller saves). Returns (txt_path, expires_epoch).
    Raises OSError if the txt can't be written — settings are untouched then.
    The phrase itself is never returned or logged; it lives only in the txt."""
    import secrets as _sec, hashlib as _hl
    now     = time_module.time() if now is None else now
    folder  = folder or os.path.dirname(_SETTINGS_PATH)
    phrase  = _sec.token_hex(8)                      # 16 hex chars, 0-f
    expires = now + ADMIN_TEMP_RECOVERY_MINUTES * 60
    path    = os.path.join(folder, ADMIN_TEMP_RECOVERY_TXT)
    fmt     = lambda t: datetime.fromtimestamp(t).strftime('%Y-%m-%d %H:%M:%S')
    body = (
        'PAA ADMIN - TEMPORARY RECOVERY PHRASE\n'
        '=====================================\n'
        f'Generated : {fmt(now)}\n'
        f'Expires   : {fmt(expires)}  ({ADMIN_TEMP_RECOVERY_MINUTES} minutes)\n\n'
        f'Recovery phrase:  {phrase}\n\n'
        'How to use\n'
        '  1. Open PAA, enter K-ID  admin1  and its PIN, click Sign In.\n'
        '  2. Type the recovery phrase above when asked.\n'
        '  3. Set a NEW R-Code secret (twice).\n\n'
        'Single-use. This file is deleted automatically after a successful\n'
        'recovery. If you did not use it, delete this file yourself.\n'
    )
    with open(path, 'w', encoding='utf-8') as f:
        f.write(body)
    settings['admin_emergency_lock']   = True
    settings['admin_recovery_sha256']  = _hl.sha256(phrase.encode()).hexdigest()
    settings['admin_recovery_expires'] = expires
    settings['admin_recovery_txt']     = path
    return path, expires


def admin_temp_recovery_expired(settings: dict, now: float = None) -> bool:
    exp = float(settings.get('admin_recovery_expires', 0) or 0)
    now = time_module.time() if now is None else now
    return bool(exp) and now > exp


def admin_temp_recovery_delete_txt(settings: dict):
    """Best-effort removal of the plaintext phrase file."""
    p = settings.get('admin_recovery_txt', '')
    if p:
        try:
            os.remove(p)
        except OSError:
            pass


def admin_temp_recovery_burn(settings: dict):
    """After a successful recovery: delete the txt and clear temp-phrase keys."""
    admin_temp_recovery_delete_txt(settings)
    settings['admin_recovery_expires'] = 0
    settings['admin_recovery_txt']     = ''


class AppLockScreen(tk.Tk):
    """K-ID sign-in — username + PIN. Falls back to legacy PIN-only mode
    when no K-ID account exists yet."""

    def __init__(self):
        super().__init__()
        self.title("PAA — K-ID Sign In")
        self.configure(bg='#0d1117')
        self.geometry("440x600")
        self.resizable(False, False)
        self._settings = load_app_settings()
        # Field starts EMPTY by design — prefilling the last-used K-ID would
        # hand back the valid-username knowledge the dropdown removal hides.
        self._user_var  = tk.StringVar(value='')
        self._pin_var   = tk.StringVar(value="")
        self._email_var = tk.StringVar(value="")   # optional, Create mode only
        self._mode = 'signin'   # 'signin' | 'create'
        self._build_ui()

    # ── UI ───────────────────────────────────────────────────────────────────
    def _build_ui(self):
        for w in self.winfo_children():
            w.destroy()

        center = tk.Frame(self, bg='#0d1117')
        center.place(relx=0.5, rely=0.5, anchor="center")

        accounts = self._settings.get('kid_accounts', [])
        # Default to Create on a fresh install (no accounts yet), but honor an
        # EXPLICIT switch to sign-in even with zero accounts — the admin
        # account (admin1) exists implicitly without ever being created, so
        # sign-in must always be reachable. Previously `or not accounts`
        # forced Create unconditionally and 'Back to sign in' just bounced
        # straight back, locking admin1 out of a fresh install entirely.
        creating = (self._mode == 'create') or (
            not accounts and not getattr(self, '_mode_explicit', False))

        tk.Label(center, text="🆔", font=("Segoe UI", 38),
                 bg='#0d1117', fg='#58A6FF').pack()
        tk.Label(center, text="K-ID", font=("Segoe UI", 20, "bold"),
                 fg='#58A6FF', bg='#0d1117').pack(pady=(2, 0))
        tk.Label(center,
                 text="Create your K-ID" if creating else "Sign in to continue",
                 font=("Segoe UI", 9), fg='#888', bg='#0d1117').pack(pady=(2, 14))

        # Username
        tk.Label(center, text="Username", font=("Segoe UI", 8),
                 fg='#8b949e', bg='#0d1117', anchor='w').pack(fill='x')
        # Username — always a plain typed entry, NO dropdown. Deliberate
        # security choice: the old dropdown enumerated every K-ID on the
        # machine (and advertised admin1's existence), handing an attacker
        # half the credential for free. Now knowing a valid username is part
        # of what a login attempt must supply.
        tk.Entry(center, textvariable=self._user_var, justify="center",
                 font=("Segoe UI", 13), bg='#161b22', fg='#cdd9e5',
                 insertbackground='#cdd9e5', relief="flat",
                 width=18).pack(pady=(2, 8), ipady=5)

        # Email (Create mode only — optional, linked to this K-ID)
        if creating:
            tk.Label(center, text="Email (optional)", font=("Segoe UI", 8),
                     fg='#8b949e', bg='#0d1117', anchor='w').pack(fill='x')
            tk.Entry(center, textvariable=self._email_var, justify="center",
                     font=("Segoe UI", 11), bg='#161b22', fg='#cdd9e5',
                     insertbackground='#cdd9e5', relief="flat",
                     width=22).pack(pady=(2, 8), ipady=4)

        # PIN
        tk.Label(center, text="PIN (4–8 digits)", font=("Segoe UI", 8),
                 fg='#8b949e', bg='#0d1117', anchor='w').pack(fill='x')
        pin_entry = tk.Entry(center, textvariable=self._pin_var, show="•",
                             justify="center", font=("Segoe UI", 16),
                             bg='#161b22', fg='#cdd9e5',
                             insertbackground='#cdd9e5', relief="flat", width=12)
        pin_entry.pack(pady=(2, 0), ipady=6)
        pin_entry.bind("<Return>",
                       lambda e: self._create() if creating else self._sign_in())
        pin_entry.focus_set()

        self._error_var = tk.StringVar(value="")
        tk.Label(center, textvariable=self._error_var, font=("Segoe UI", 8),
                 fg='#F85149', bg='#0d1117', wraplength=320,
                 justify='center').pack(pady=(8, 0))

        # Primary action
        tk.Button(center,
                  text="Create K-ID" if creating else "Sign In",
                  font=("Segoe UI", 11, "bold"), bg='#58A6FF', fg='#0d1117',
                  relief="flat", padx=24, pady=8, cursor="hand2",
                  command=self._create if creating else self._sign_in
                  ).pack(pady=(12, 0))

        # Mode switch
        if accounts:
            tk.Button(center,
                      text="← Back to sign in" if creating else "+ Create another K-ID",
                      font=("Segoe UI", 8), bg='#0d1117', fg='#58A6FF',
                      relief="flat", cursor="hand2", bd=0,
                      activebackground='#0d1117', activeforeground='#79c0ff',
                      command=self._toggle_mode).pack(pady=(8, 0))

        if accounts and not creating:
            tk.Button(center, text="Forgot your PIN?",
                      font=("Segoe UI", 8), bg='#0d1117', fg='#8b949e',
                      relief="flat", cursor="hand2", bd=0,
                      activebackground='#0d1117', activeforeground='#D29922',
                      command=self._open_recovery).pack(pady=(2, 0))

        if not creating:
            tk.Button(center, text="Forgot admin recovery phrase?",
                      font=("Segoe UI", 8), bg='#0d1117', fg='#8b949e',
                      relief="flat", cursor="hand2", bd=0,
                      activebackground='#0d1117', activeforeground='#F85149',
                      command=self._admin_forgot_phrase).pack(pady=(2, 0))

        if creating:
            tk.Label(center,
                     text="Your K-ID is local to this device.\n"
                          "It keeps your portfolio and PTS wallet separate\n"
                          "from anyone else using this app.",
                     font=("Segoe UI", 7), fg='#555', bg='#0d1117',
                     justify='center').pack(pady=(10, 0))

        # Security note
        box = tk.Frame(center, bg='#161b22', highlightbackground='#30363D',
                       highlightthickness=1, padx=14, pady=8)
        box.pack(pady=(18, 0), fill='x')
        tk.Label(box, text="🔒  Sign in is required",
                 font=("Segoe UI", 8, "bold"), fg='#888',
                 bg='#161b22').pack(anchor='w')
        tk.Label(box,
                 text="Your K-ID decides which portfolio, PTS wallet and\n"
                      "warrant book load. PINs are stored hashed, never in\n"
                      "plain text, and never leave this device.",
                 font=("Segoe UI", 7), fg='#555', bg='#161b22',
                 justify='left').pack(anchor='w', pady=(2, 0))

    def _admin_forgot_phrase(self):
        """Outside-the-app 'forgot recovery phrase' for admin1. Gated on
        admin1 + its PIN (typed into the fields above) — otherwise anyone at
        the sign-in screen could mint a phrase and lock the real admin out."""
        u, p = self._user_var.get().strip(), self._pin_var.get()
        if u.lower() != ADMIN_KID or not p or not kid_verify(self._settings, u, p):
            self._error_var.set("Type admin1 and its PIN above first, "
                                "then click this again.")
            self._pin_var.set("")
            return
        if not messagebox.askyesno('Admin Recovery Phrase',
                'Generate a NEW temporary recovery phrase?\n\n'
                '• It is saved to a .txt file next to the app\n'
                f'• Valid for {ADMIN_TEMP_RECOVERY_MINUTES} minutes, single-use\n'
                '• Normal PIN + R-Code login is disabled until you recover\n'
                '• Recovery makes you set a NEW R-Code', parent=self):
            return
        try:
            path, _exp = admin_temp_recovery_issue(self._settings)
        except OSError as exc:
            self._error_var.set(f"Could not write the recovery file: {exc}")
            return
        save_app_settings(self._settings)
        self._pin_var.set("")
        self._error_var.set("")
        messagebox.showinfo('Admin Recovery Phrase',
            f'✅ Temporary recovery phrase saved to:\n\n{path}\n\n'
            f'Open it, then sign in as admin1 and enter the phrase within '
            f'{ADMIN_TEMP_RECOVERY_MINUTES} minutes.', parent=self)

    def _open_recovery(self):
        """Forgot-PIN recovery — prove ownership by answering questions
        generated live from the user's own portfolio ledger."""
        user = self._user_var.get().strip()
        if not user or not kid_find_account(self._settings, user):
            self._error_var.set("Pick the K-ID you want to recover first.")
            return

        if not sca_has_source(self._settings, user):
            messagebox.showwarning(
                'K-ID Recovery',
                f'"{user}" has never connected a portfolio, so there are no\n'
                f'questions to verify against.\n\n'
                f'Recovery works by asking about your own transactions —\n'
                f'without a ledger there is nothing to ask.',
                parent=self)
            return

        win = tk.Toplevel(self)
        win.title('K-ID Recovery')
        win.configure(bg='#0d1117')
        win.geometry('460x520')
        win.transient(self)
        win.grab_set()

        tk.Label(win, text='🔓  K-ID RECOVERY', font=('Segoe UI', 13, 'bold'),
                 fg='#D29922', bg='#0d1117').pack(pady=(16, 2))
        tk.Label(win, text=f'Recovering: {user}', font=('Segoe UI', 9),
                 fg='#cdd9e5', bg='#0d1117').pack()

        status = tk.StringVar(value='⏳  Reading your ledger…')
        tk.Label(win, textvariable=status, font=('Segoe UI', 8),
                 fg='#8b949e', bg='#0d1117', wraplength=400,
                 justify='center').pack(pady=(10, 6))

        body = tk.Frame(win, bg='#0d1117')
        body.pack(fill='both', expand=True, padx=18)

        state = {'qs': [], 'vars': [], 'attempts': 0}

        def _build_quiz():
            rows, ports = kid_load_recovery_data(self._settings, user)
            if not rows or not ports:
                status.set('❌  Could not read your portfolio.\n'
                           'Recovery needs access to the sheet/CSV you connected.')
                return
            qs = kid_recovery_questions(rows, ports, n=3)
            if len(qs) < 2:
                status.set('❌  Not enough transaction history to verify you.\n'
                           'Recovery needs a few buys on record.')
                return
            state['qs'] = qs
            status.set(f'Answer all {len(qs)} questions about your own portfolio.')

            for i, q in enumerate(qs, 1):
                card = tk.Frame(body, bg='#161b22', highlightbackground='#30363D',
                                highlightthickness=1, padx=12, pady=8)
                card.pack(fill='x', pady=4)
                tk.Label(card, text=f'{i}.  {q["q"]}', font=('Segoe UI', 9, 'bold'),
                         fg='#cdd9e5', bg='#161b22', wraplength=380,
                         justify='left').pack(anchor='w')
                v = tk.StringVar(value='')
                state['vars'].append(v)
                opt_row = tk.Frame(card, bg='#161b22')
                opt_row.pack(fill='x', pady=(4, 0))
                for opt in q['options']:
                    tk.Radiobutton(opt_row, text=opt, variable=v, value=opt,
                                   bg='#161b22', fg='#8b949e', selectcolor='#161b22',
                                   activebackground='#161b22', activeforeground='#58A6FF',
                                   font=('Segoe UI', 8), relief='flat',
                                   cursor='hand2', indicatoron=False,
                                   padx=8, pady=3).pack(side='left', padx=2)

            tk.Button(win, text='✓  Verify', font=('Segoe UI', 10, 'bold'),
                      bg='#D29922', fg='#0d1117', relief='flat',
                      padx=20, pady=6, cursor='hand2',
                      command=_verify).pack(pady=(8, 12))

        def _verify():
            answers = [v.get() for v in state['vars']]
            if any(not a for a in answers):
                status.set('⚠️  Answer every question.')
                return
            correct = sum(1 for q, a in zip(state['qs'], answers) if a == q['answer'])
            if correct == len(state['qs']):
                win.destroy()
                self._open_reset_pin(user)
                return
            state['attempts'] += 1
            if state['attempts'] >= 3:
                messagebox.showerror(
                    'K-ID Recovery',
                    'Too many failed attempts.\n\n'
                    'If this is your K-ID, check your portfolio in the sheet\n'
                    'and try again later.',
                    parent=win)
                win.destroy()
                return
            status.set(f'❌  {correct}/{len(state["qs"])} correct — '
                       f'{3 - state["attempts"]} attempt(s) left.')

        # Load in the background so the dialog paints immediately
        def _bg():
            try:
                self.after(0, _build_quiz)
            except Exception:
                pass
        self.after(80, _bg)

    def _open_reset_pin(self, user: str):
        """Post-recovery — set a new PIN."""
        win = tk.Toplevel(self)
        win.title('Set New PIN')
        win.configure(bg='#0d1117')
        win.geometry('360x280')
        win.transient(self)
        win.grab_set()

        tk.Label(win, text='✅  IDENTITY CONFIRMED', font=('Segoe UI', 12, 'bold'),
                 fg='#3FB950', bg='#0d1117').pack(pady=(18, 2))
        tk.Label(win, text=f'Set a new PIN for "{user}"', font=('Segoe UI', 8),
                 fg='#888', bg='#0d1117').pack(pady=(0, 14))

        new_var, cf_var = tk.StringVar(), tk.StringVar()
        for lbl, var in [('New PIN (4–8 digits)', new_var), ('Confirm new PIN', cf_var)]:
            tk.Label(win, text=lbl, font=('Segoe UI', 8), fg='#8b949e',
                     bg='#0d1117').pack()
            tk.Entry(win, textvariable=var, show='•', justify='center',
                     font=('Segoe UI', 14), bg='#161b22', fg='#cdd9e5',
                     insertbackground='#cdd9e5', relief='flat',
                     width=12).pack(pady=(2, 8), ipady=4)

        err = tk.StringVar()
        tk.Label(win, textvariable=err, font=('Segoe UI', 8), fg='#F85149',
                 bg='#0d1117', wraplength=300).pack()

        def _apply():
            if new_var.get() != cf_var.get():
                err.set("PINs don't match."); return
            ok, msg = kid_reset_pin(self._settings, user, new_var.get())
            if not ok:
                err.set(msg); return
            win.destroy()
            self._settings = load_app_settings()
            self._pin_var.set('')
            self._error_var.set('')
            messagebox.showinfo('K-ID', msg, parent=self)

        tk.Button(win, text='Set PIN', font=('Segoe UI', 10, 'bold'),
                  bg='#3FB950', fg='#0d1117', relief='flat', padx=20, pady=6,
                  cursor='hand2', command=_apply).pack(pady=(10, 0))

    def _toggle_mode(self):
        self._mode = 'signin' if self._mode == 'create' else 'create'
        self._mode_explicit = True   # user chose — don't force Create anymore
        self._pin_var.set("")
        self._build_ui()

    def _prompt_for_email(self, username: str):
        """One-time nudge for K-IDs created before email support existed.
        Optional — 'Skip' just moves on and it'll ask again next sign-in
        until an email is saved (or the user keeps skipping, which is fine)."""
        dlg = tk.Toplevel(self)
        dlg.title('Add an email')
        dlg.configure(bg='#0d1117')
        dlg.geometry('340x190')
        dlg.transient(self); dlg.grab_set()
        tk.Label(dlg, text='📧  Link an email to this K-ID',
                 font=('Segoe UI', 11, 'bold'), fg='#58A6FF',
                 bg='#0d1117').pack(pady=(14, 2))
        tk.Label(dlg, text=f'"{username}" doesn\'t have one on file yet.\n'
                            'Optional, but useful for recovery later.',
                 font=('Segoe UI', 8), fg='#8b949e', bg='#0d1117',
                 justify='center').pack(pady=(0, 8))
        ev = tk.StringVar()
        e = tk.Entry(dlg, textvariable=ev, justify='center',
                     font=('Segoe UI', 11), bg='#161b22', fg='#cdd9e5',
                     insertbackground='#cdd9e5', relief='flat')
        e.pack(pady=4, padx=24, fill='x', ipady=4)
        e.focus_set()
        err = tk.StringVar()
        tk.Label(dlg, textvariable=err, font=('Segoe UI', 8),
                 fg='#F85149', bg='#0d1117').pack()

        def _save():
            email = ev.get().strip()
            if not email:
                dlg.destroy(); return
            ok, msg = kid_set_email(self._settings, username, email)
            if not ok:
                err.set(msg); return
            dlg.destroy()

        row = tk.Frame(dlg, bg='#0d1117'); row.pack(pady=(10, 0))
        tk.Button(row, text='Skip', font=('Segoe UI', 9), bg='#21262d',
                  fg='#8b949e', relief='flat', padx=14, pady=4, cursor='hand2',
                  command=dlg.destroy).pack(side='left', padx=6)
        tk.Button(row, text='Save', font=('Segoe UI', 9, 'bold'), bg='#58A6FF',
                  fg='#0d1117', relief='flat', padx=14, pady=4, cursor='hand2',
                  command=_save).pack(side='left', padx=6)
        e.bind('<Return>', lambda _: _save())
        self.wait_window(dlg)

    # ── Actions ──────────────────────────────────────────────────────────────
    def _create(self):
        u, p, em = self._user_var.get(), self._pin_var.get(), self._email_var.get().strip()
        if em and not kid_valid_email(em):
            self._error_var.set("That doesn't look like a valid email address.")
            return
        if 'admin' in u.strip().lower():
            messagebox.showwarning(
                'K-ID Reserved',
                'Usernames containing "admin" are reserved and can only be '
                'approved by the administrator (admin1).\n\n'
                'To request an admin-related K-ID, email:\n'
                'yapwc2838@gmail.com\n'
                'Subject: request for Admin Account',
                parent=self)
            self._pin_var.set("")
            return
        ok, msg = kid_create(self._settings, u, p, em)
        if not ok:
            self._error_var.set(msg)
            self._pin_var.set("")
            return
        self._settings['kid_last_user'] = u.strip()
        save_app_settings(self._settings)
        # First-time nudge: this new K-ID starts on the house default Luno
        # key (admin-set) — flag it so their first Settings visit surfaces
        # the "My Key" panel, rather than the default silently staying
        # permanent just because nobody ever mentioned it existed.
        messagebox.showinfo(
            'Welcome',
            f'K-ID "{u.strip()}" created.\n\n'
            'Crypto (Luno, MYR) pricing starts on the app\'s house default '
            'key. You can set your own anytime in ⚙ Settings → '
            'LUNO CRYPTO — My Key.',
            parent=self)
        self._launch(u.strip())

    def _sign_in(self):
        u, p = self._user_var.get().strip(), self._pin_var.get()
        if not u:
            self._error_var.set("Pick a K-ID."); return
        if not p:
            self._error_var.set("Enter your PIN."); return
        # ── Emergency lock: while active, admin1 can ONLY get in via the
        # 16-hex recovery code (normal PIN+R-Code path is disabled) and must
        # set a brand-new R-Code secret on the way through.
        if (u.strip().lower() == ADMIN_KID
                and self._settings.get('admin_emergency_lock')):
            if self._admin_recovery_flow():
                self._settings['kid_last_user'] = u
                save_app_settings(self._settings)
                self._launch(u)
            else:
                self._error_var.set("Recovery failed. Admin remains locked.")
                self._pin_var.set("")
            return
        if kid_verify(self._settings, u, p):
            # ── Admin 3FA: username + password + R-Code passphrase ──────────
            if u.strip().lower() == ADMIN_KID:
                if not self._admin_rcode_check():
                    self._error_var.set("R-Code incorrect. Access denied.")
                    self._pin_var.set("")
                    return
            self._settings['kid_last_user'] = u
            save_app_settings(self._settings)
            if u.strip().lower() != ADMIN_KID and not kid_get_email(self._settings, u):
                self._prompt_for_email(u)
            self._launch(u)
            return
        self._error_var.set("Wrong username or PIN.")
        self._pin_var.set("")

    # SHA-256 of the R-Code passphrase (HYDEV001). A rotated secret set via
    # emergency recovery lives in settings['admin_rcode_sha256'] and takes
    # priority over this baked-in default.
    ADMIN_RCODE_SHA256 = ('7e23f29f13be8c3431f50d6c92fe6b4eedf651cfa0cc16aece474e67bdd5128f')

    def _admin_rcode_hash(self) -> str:
        return (self._settings.get('admin_rcode_sha256', '')
                or self.ADMIN_RCODE_SHA256)

    def _admin_rcode_check(self) -> bool:
        """Third factor for admin1: prompt for the R-Code passphrase in a
        masked dialog and compare SHA-256 against the effective hash."""
        import hashlib as _hl
        dlg = tk.Toplevel(self)
        dlg.title('R-Code')
        dlg.configure(bg='#0d1117')
        dlg.geometry('300x140')
        dlg.transient(self); dlg.grab_set()
        tk.Label(dlg, text='🔐  Admin R-Code', font=('Segoe UI', 11, 'bold'),
                 fg='#F85149', bg='#0d1117').pack(pady=(14, 2))
        tk.Label(dlg, text='Enter the R-Code passphrase (3rd factor)',
                 font=('Segoe UI', 8), fg='#8b949e', bg='#0d1117').pack()
        rv = tk.StringVar()
        e = tk.Entry(dlg, textvariable=rv, show='•', font=('Segoe UI', 10),
                     bg='#161b22', fg='#cdd9e5', insertbackground='#F85149',
                     relief='flat', highlightbackground='#30363d',
                     highlightthickness=1, justify='center')
        e.pack(pady=6, padx=24, fill='x'); e.focus_set()
        result = {'ok': False}
        def _submit(_=None):
            result['ok'] = (_hl.sha256(rv.get().encode()).hexdigest()
                            == self._admin_rcode_hash())
            dlg.destroy()
        e.bind('<Return>', _submit)
        tk.Button(dlg, text='Verify', font=('Segoe UI', 9, 'bold'),
                  bg='#21262d', fg='#F85149', relief='flat', padx=14, pady=4,
                  cursor='hand2', command=_submit).pack(pady=(0, 10))
        self.wait_window(dlg)
        return result['ok']

    def _admin_recovery_flow(self) -> bool:
        """Emergency recovery: verify the one-time 16-hex recovery code, then
        force setting a NEW R-Code secret (entered twice). On success the
        lock clears and the recovery hash is burned — each recovery code is
        single-use."""
        import hashlib as _hl
        stored = self._settings.get('admin_recovery_sha256', '')
        if not stored:
            messagebox.showerror('Recovery',
                'Emergency lock is active but no recovery code exists — '
                'restore paa_settings.json from backup.', parent=self)
            return False
        if admin_temp_recovery_expired(self._settings):
            admin_temp_recovery_delete_txt(self._settings)
            messagebox.showerror('Recovery',
                'This temporary recovery phrase has expired.\n\n'
                'Use "Forgot admin recovery phrase?" on the sign-in screen '
                '(admin1 + PIN) to generate a new one.', parent=self)
            return False
        dlg = tk.Toplevel(self)
        dlg.title('Emergency Recovery')
        dlg.configure(bg='#0d1117')
        dlg.geometry('340x250')
        dlg.transient(self); dlg.grab_set()
        tk.Label(dlg, text='🚨  EMERGENCY RECOVERY', font=('Segoe UI', 11, 'bold'),
                 fg='#F85149', bg='#0d1117').pack(pady=(12, 2))
        tk.Label(dlg, text='Enter the 16-character recovery code:',
                 font=('Segoe UI', 8), fg='#8b949e', bg='#0d1117').pack()
        code_v = tk.StringVar()
        tk.Entry(dlg, textvariable=code_v, font=('Consolas', 11), justify='center',
                 bg='#161b22', fg='#cdd9e5', insertbackground='#F85149',
                 relief='flat', highlightbackground='#30363d',
                 highlightthickness=1).pack(pady=4, padx=24, fill='x')
        tk.Label(dlg, text='New R-Code secret (enter twice):',
                 font=('Segoe UI', 8), fg='#8b949e', bg='#0d1117').pack(pady=(8, 0))
        new1_v, new2_v = tk.StringVar(), tk.StringVar()
        for v in (new1_v, new2_v):
            tk.Entry(dlg, textvariable=v, show='•', font=('Segoe UI', 10),
                     justify='center', bg='#161b22', fg='#cdd9e5',
                     insertbackground='#F85149', relief='flat',
                     highlightbackground='#30363d', highlightthickness=1
                     ).pack(pady=2, padx=24, fill='x')
        result = {'ok': False}
        def _submit():
            code = code_v.get().strip().lower()
            if _hl.sha256(code.encode()).hexdigest() != stored:
                messagebox.showerror('Recovery', 'Recovery code incorrect.', parent=dlg)
                return
            if len(new1_v.get()) < 4 or new1_v.get() != new2_v.get():
                messagebox.showerror('Recovery',
                    'New secrets must match (min 4 chars).', parent=dlg)
                return
            self._settings['admin_rcode_sha256'] = _hl.sha256(
                new1_v.get().encode()).hexdigest()
            self._settings['admin_emergency_lock'] = False
            self._settings['admin_recovery_sha256'] = ''   # burn the code
            admin_temp_recovery_burn(self._settings)       # delete temp txt, clear expiry
            save_app_settings(self._settings)
            result['ok'] = True
            dlg.destroy()
            messagebox.showinfo('Recovery',
                '✅ New R-Code set, emergency lock cleared.\n'
                'The recovery code is now burned (single-use).', parent=self)
        tk.Button(dlg, text='Recover', font=('Segoe UI', 9, 'bold'),
                  bg='#21262d', fg='#F85149', relief='flat', padx=14, pady=4,
                  cursor='hand2', command=_submit).pack(pady=(8, 10))
        self.wait_window(dlg)
        return result['ok']

    def _launch(self, username: str):
        global CURRENT_KID, CURRENT_OPIE
        CURRENT_KID = username
        # OPIE disabled for now (module removed) — role-aware agent init skipped.
        CURRENT_OPIE = None
        presence_touch(login=True)
        self.destroy()
        SplashScreen().mainloop()



