import sys
import subprocess
import math
import pickle
import csv
import logging as _logging
from datetime import date, timedelta
from tkinter import simpledialog
import matplotlib.patches
import matplotlib.collections
import matplotlib.ticker as mticker
from matplotlib.backends.backend_pdf import PdfPages


# Wealth Management — user-built, %-weighted custom portfolio "packs".
# Any yfinance-resolvable ticker (KL 4-digit .KL codes, plain US tickers,
# etc.) can go in a pack; weights must sum to 100%. Persisted as plain
# JSON (not pickle) so a pack file stays human-readable/editable.
# In-memory only (never persisted — it's recomputed fresh every rebuild):
# {(pack_name, ticker): native_amount_held_back} for whatever cash is
# currently parked as WEALTH_CASH_TICKER because that ticker's own
# market is in 'wait' mode (see wealth_order_price_mode /
# _compute_pack_current_units). Read by check_wealth_pending_fills()
# to estimate a buy-in the moment that market's mode flips out of 'wait'.
_WEALTH_PENDING_NATIVE = {}

# In-memory only (never persisted — rebuilt fresh on every
# _compute_pack_current_units call): {pack_name: [entries]}, one entry
# per ticker that had a deposit scheduled to fill on TODAY's row,
# whatever the outcome — filled live, filled at cache close, or parked
# as Cash because that market's in 'wait'. Purely a visibility aid so
# "why did my money end up as Cash / why is this price X" has an
# on-screen answer instead of looking like a bug — see
# WealthManagementPage's 'Today's Fills' panel.
_WEALTH_FILL_LOG = {}

WEALTH_PACKS_CACHE = os.path.join(DEFAULT_FOLDER, 'wealth_packs.json')
# Smallest fractional unit a Wealth pack can buy of any holding — every
# allocation is floored DOWN to the nearest multiple of this before it's
# added to that holding's running unit count, same "no smaller than the
# minimum tradeable fraction" idea as the MY 5-stock basket's 2-decimal
# unit rounding, just finer-grained since a pack's per-contribution
# amount is typically much smaller than a whole share/board-lot.
WEALTH_MIN_UNIT = 0.0001

# Pseudo-ticker for the "Cash (Cr)" accounting subject a Wealth pack's
# weights can be topped up to 100% with, when the user doesn't want the
# whole amount invested in named holdings. Priced at a flat 1.0 every
# day (see _wealth_cash_price_series below) so its "units" are just the
# native-currency cash amount sitting idle — never fetched from
# yfinance/cache like a real ticker. Matches _US_STOCK_SYMBOL_RE (plain
# 1-5 letter symbol, no suffix) so _ccy_for_label('CASH') resolves to
# 'USD' like any other bare US-style ticker, with no special-casing
# needed there.
WEALTH_CASH_TICKER = 'CASH'
WEALTH_CASH_DISPLAY = 'Cash (Cr)'
TEET_CSV_PATH      = DEFAULT_INPUT_FILE   # merged build: same teet.csv as the main app

# ── DLC (Daily Leverage Certificate) halt/leverage floors — module level
# so both the index-build engine (build_indices) AND the trade popup UI
# (which needs to re-check the underlying independently of whatever the
# last full rebuild's cached snapshot says) share one source of truth.
#
# Index underlyings (MYIPO+ family, FBM KLCI) use point-level tiers;
# single-stock underlyings use RM price-level tiers instead — a typical
# stock (RM0.10-RM20) would never clear the index tiers' 25.0 floor.
IW_ZDL_MAX_LEVERAGE  = 10
IW_ZDL_LEVERAGE_TIERS = [
    (1000.0, 10),
    (500.0,   7),
    (200.0,   5),
    (100.0,   3),
    (25.0,    2),
]   # leverage never exceeds IW_ZDL_MAX_LEVERAGE, always one of {2,3,5,7,10}
IW_ZDL_STOCK_LEVERAGE_TIERS = [
    (10.00, 10),
    (5.00,   7),
    (2.00,   5),
    (0.50,   3),
    (0.10,   2),
]

_STOCK_SYMBOL_RE = re.compile(r'^\d{4}\.KL$')

# Plain US ticker via yfinance: 1-5 letters, optionally a share-class
# suffix like "BRK.B" or "BF.A" — NEVER a "####.KL"/".SI"/".HK"/etc.
# suffix (those are all caught by _ccy_for_label's explicit checks
# first) and never one of the bare-name composite indices (HANG SENG,
# STRAITS TIMES, NIKKEI 225, KOSPI, TAIEX — each has its own explicit
# label match ahead of this, so a 5-letter index name like "KOSPI"
# still resolves correctly and never falls through to this regex).
_US_STOCK_SYMBOL_RE = re.compile(r'^[A-Z]{1,5}(\.[A-Z])?$')

# ── Per-currency MINIMUM ELIGIBILITY price for single-stock IW / IW-ZD /
# IW-ZDL / DLC underlyings — deliberately separate from (and stricter
# than) the RM0.10/RM0.075 halt-floor tiers above. The halt floor only
# governs an ALREADY-eligible stock's later knockout level; this gate
# decides whether a stock is offered as an underlying AT ALL. A stock
# priced below its own market's bar here never gets built into
# iw_zd_snapshot / stock DLC in the first place (see
# is_stock_dlc_eligible() / build_iw_zd_snapshot()'s min_eligible_fn),
# and Search still lists it, tagged ineligible, so it doesn't just
# silently vanish from the results a user typed.
STOCK_DLC_MIN_ELIGIBLE_PRICE = {
    'MYR': 0.50,
    'HKD': 20.00,
    'JPY': 100.00,
    'KRW': 1200.00,
    'SGD': 1.00,
    'TWD': 20.00,   # scaffolding for planned .TW/TWSE expansion
    'USD': 5.00,    # US (NYSE/Nasdaq) — plain tickers, no exchange suffix
}

def _stock_dlc_min_eligible(ccy: str) -> float:
    """Minimum last-close price (in the underlying's own currency) a
    stock must clear before it's offered as an IW/IW-ZD/IW-ZDL/DLC
    underlying at all. Unrecognized currencies fall back to the MYR
    floor — same default _ccy_for_label() itself uses."""
    return STOCK_DLC_MIN_ELIGIBLE_PRICE.get((ccy or '').upper(),
                                             STOCK_DLC_MIN_ELIGIBLE_PRICE['MYR'])


def is_stock_dlc_eligible(label: str, spot) -> bool:
    """True if `spot` (last close, in the underlying's own currency)
    clears the per-market minimum-price bar for IW/IW-ZD/IW-ZDL/DLC
    eligibility on `label`. Currency is resolved from the symbol's
    exchange suffix via _ccy_for_label() (####.KL/.HK/.KS/.T/.SI).
    Returns False (not eligible) for missing/invalid price data,
    never raises."""
    if spot is None:
        return False
    try:
        return float(spot) >= _stock_dlc_min_eligible(_ccy_for_label(label))
    except (TypeError, ValueError):
        return False


def _stock_dlc_floor(spot: float) -> float:
    """A stock already trading below RM0.15 gets a lower RM0.075 halt
    floor instead of the standard RM0.10 one — the flat 0.10 floor would
    leave a deep-penny IPO stock almost no room to trade before every
    DLC on it halts."""
    return 0.075 if spot < 0.15 else IW_ZDL_STOCK_LEVERAGE_TIERS[-1][0]

def _dlc_applicable_floor(label: str, spot: float) -> float:
    """The halt/eligibility floor that applies to THIS underlying right
    now — RM-scaled + dynamic RM0.15/RM0.075 rule for a single-stock
    symbol (####.KL), fixed 25.0-point floor for everything else
    (composite indices, FBM KLCI)."""
    if _STOCK_SYMBOL_RE.match(str(label)):
        return _stock_dlc_floor(spot)
    return IW_ZDL_LEVERAGE_TIERS[-1][0]


def _stock_leverage_tiers_for_ccy(ccy: str):
    """IW_ZDL_STOCK_LEVERAGE_TIERS is RM-scaled (built around the MYR
    0.10-10.00 price band). Scaled proportionally for any other
    currency, using STOCK_DLC_MIN_ELIGIBLE_PRICE's per-currency floor
    relative to its MYR one — e.g. HKD's min-eligible (20.00) is 40x
    MYR's (0.50), so an HKD stock's leverage tiers land at 40x the MYR
    levels too, instead of being compared against RM-sized steps that
    would put almost every HKD/JPY/KRW stock in the top tier."""
    mult = _stock_dlc_min_eligible(ccy) / STOCK_DLC_MIN_ELIGIBLE_PRICE['MYR']
    return [(round(min_spot * mult, 4), lev) for min_spot, lev in IW_ZDL_STOCK_LEVERAGE_TIERS]


def _stock_dlc_floor_for_ccy(spot: float, ccy: str) -> float:
    """Currency-scaled counterpart to _stock_dlc_floor() — same
    deep-penny halt-floor rule, scaled by the same multiplier as
    _stock_leverage_tiers_for_ccy()."""
    mult = _stock_dlc_min_eligible(ccy) / STOCK_DLC_MIN_ELIGIBLE_PRICE['MYR']
    return (0.075 if spot < 0.15 * mult else IW_ZDL_STOCK_LEVERAGE_TIERS[-1][0]) * mult


# ── IW-ZD / DLC engine core — MODULE-level (not nested in build_indices())
# so it can be called two ways: (1) the full batch build every index
# rebuild does over every tracked MY stock + composite index (still
# called from build_indices(), just referencing these top-level names
# now), and (2) get_or_build_stock_dlc_snapshot() below, an ON-DEMAND
# single-symbol build for a Search result that isn't already sitting in
# app.iw_zd_snapshot from the last full rebuild — e.g. an eligible
# HK/KR/JP/SG stock, which the batch build never covers (it only loops
# `tickers_listed`, the MY universe). Same engine, same rules, either
# way — just a different frames dict and, for on-demand, currency-scaled
# tiers/floor via _stock_leverage_tiers_for_ccy()/_stock_dlc_floor_for_ccy().
IW_ZD_START_PRICE    = 1.0000
IW_ZD_LAUNCH_DATE    = pd.Timestamp('2021-01-01')  # DLC didn't exist
# before this — underlying index history can run earlier (e.g. MYIPO+
# inception), so the daily-reset series must be clipped to launch date
# before computing day-over-day returns, otherwise day 1 of the ZD/DLC
# series silently uses a pre-launch pct_change and/or the histochart
# shows years that never traded.


def _iw_zd_pick_leverage(spot: float, tiers=IW_ZDL_LEVERAGE_TIERS):
    for min_spot, lev in tiers:
        if spot >= min_spot:
            return lev
    return None


# DLC's daily reading is anchored purely to the underlying's actual
# CLOSING point, once the market has closed — same as every other index
# in this dashboard (all_frames is built from daily closes throughout).
# No intraday live-quote override: a certificate's day is only "done"
# once the real close is in, consistent with how the whole index engine
# works.
def _iw_zd_daily_series(idx_series: 'pd.Series', leverage: int, direction: str,
                         start_price: float = IW_ZD_START_PRICE,
                         underlying_floor: float = None) -> 'pd.Series':
    """SGX-style constant-leverage DLC: a genuine RUNNING compound from
    IW_ZD_LAUNCH_DATE, rebalanced daily to hold `leverage` x the
    underlying's CLOSE-TO-CLOSE daily return — start_price *
    cumulative_product(1 + leverage * daily_return). This is
    deliberately a cumprod, not an elementwise reset: a real DLC trades
    continuously as one instrument, it is never reissued fresh at par
    each evening.

    MCE (knock-out) — PERMANENT, triggers on either condition:
      1. The running certificate value is driven to/through zero on
         any day (the compounded loss itself wipes it out).
      2. If `underlying_floor` is given, the underlying's own closing
         price that day trades down to/through it (e.g. a stock
         hitting the RM0.10 floor) — trading is halted right there
         regardless of what the certificate's own compounded value
         happens to read that day.
    Either way, once knocked out the certificate stays at 0.0000 for
    every subsequent day in the series — it does not revive the next
    trading day."""
    daily_return = idx_series.pct_change().fillna(0.0)
    if direction == 'short':
        daily_return = -daily_return

    underlying_vals = idx_series.reindex(daily_return.index).to_numpy()
    values = np.empty(len(daily_return))
    value = start_price
    knocked_out = False
    for i, ret in enumerate(daily_return.to_numpy()):
        if knocked_out:
            values[i] = 0.0
            continue
        value = value * (1.0 + leverage * ret)
        if value <= 0.0:
            value = 0.0
            knocked_out = True
        elif underlying_floor is not None and underlying_vals[i] <= underlying_floor:
            # Underlying itself hit the floor (e.g. a stock at RM0.10)
            # — halt right here, even though the certificate's own
            # compounded value hasn't reached zero yet.
            value = 0.0
            knocked_out = True
        values[i] = value
    return pd.Series(values, index=daily_return.index)


def build_iw_zd_snapshot(frames: dict, leverage_tiers=IW_ZDL_LEVERAGE_TIERS,
                          dynamic_floor_fn=None, min_eligible_fn=None):
    """Eligibility/halt floor is normally the LOWEST min_spot in
    `leverage_tiers` itself (25.0 pts for index underlyings, RM0.10 for
    stock underlyings) — deliberately decoupled from the unrelated IW
    structured-warrant ratio gate, since a stock's price scale has
    nothing to do with index-point ratio steps.

    If `dynamic_floor_fn(spot)` is given, it overrides that fixed floor
    PER underlying based on its own spot price — used for deep-penny
    stocks where a flat RM0.10 floor would leave too little room to
    trade (see the RM0.15/RM0.075 stock rule below): a stock already
    priced under RM0.15 gets a lower RM0.075 floor instead of the
    standard RM0.10 one.

    If `min_eligible_fn(label, spot)` is given, it's checked FIRST,
    ahead of the halt floor — this is the per-currency minimum-price
    ELIGIBILITY bar (HKD20/JPY100/KRW1200/SGD1.00/MYR0.50 — see
    is_stock_dlc_eligible()/STOCK_DLC_MIN_ELIGIBLE_PRICE at the top of
    the file), deciding whether the underlying is offered at all,
    separate from the halt floor that governs an already-eligible
    underlying's later knockout level.

    Returns (snapshot, series): snapshot is today's readings per label
    for table display; series is the full pd.Series history per
    label/side (each point = that day's own independent settlement)
    for the histochart window."""
    default_floor = leverage_tiers[-1][0]
    snap, series = {}, {}
    for label, df in frames.items():
        if label not in df.columns:
            continue
        idx_series = df[label].dropna()
        idx_series = idx_series[idx_series.index >= IW_ZD_LAUNCH_DATE]
        if idx_series.empty:
            continue
        spot  = float(idx_series.iloc[-1])   # last CLOSE, not a live quote
        if min_eligible_fn is not None and not min_eligible_fn(label, spot):
            continue
        floor = dynamic_floor_fn(spot) if dynamic_floor_fn else default_floor
        if spot < floor:
            continue

        leverage = _iw_zd_pick_leverage(spot, leverage_tiers) or 1

        # Trading halt: if the underlying itself trades down to/through
        # ITS applicable floor (RM0.10 normally, or RM0.075 for a stock
        # already under RM0.15 — see dynamic_floor_fn above), ALL DLC
        # products on it — long and short alike — are permanently
        # halted, same as a real exchange suspension. This is separate
        # from, and in addition to, each certificate's own MCE
        # knock-out on its compounded value.
        zd_long   = _iw_zd_daily_series(idx_series, 1, 'long', underlying_floor=floor)
        zd_short  = _iw_zd_daily_series(idx_series, 1, 'short', underlying_floor=floor)
        zdl_long  = _iw_zd_daily_series(idx_series, leverage, 'long', underlying_floor=floor)
        zdl_short = _iw_zd_daily_series(idx_series, leverage, 'short', underlying_floor=floor)

        series[label] = {'zd_long': zd_long, 'zd_short': zd_short,
                          'zdl_long': zdl_long, 'zdl_short': zdl_short}
        snap[label] = {
            'underlying_level': round(spot, 2),
            'zdl_leverage':     leverage,
            'zd_long':          round(float(zd_long.iloc[-1]), 4),
            'zd_short':         round(float(zd_short.iloc[-1]), 4),
            'zdl_long':         round(float(zdl_long.iloc[-1]), 4),
            'zdl_short':        round(float(zdl_short.iloc[-1]), 4),
            'zd_long_closed':   bool(zd_long.iloc[-1] <= 0.0),
            'zd_short_closed':  bool(zd_short.iloc[-1] <= 0.0),
            'zdl_long_closed':  bool(zdl_long.iloc[-1] <= 0.0),
            'zdl_short_closed': bool(zdl_short.iloc[-1] <= 0.0),
        }
    return snap, series


def get_or_build_stock_dlc_snapshot(app, symbol: str):
    """Returns (snapshot_entry, series_entry) for `symbol`'s IW-ZD/DLC
    product — SKIPS the "must already be in app.iw_zd_snapshot" check
    and loads/builds it fresh on demand if it's missing, rather than
    just reporting it unavailable. Covers exactly the gap the batch
    build in build_indices() leaves: that build only loops MY's tracked
    universe (`tickers_listed`), so a HK/KR/JP/SG stock found via
    Search (or a MY ticker outside df_listed) never gets a snapshot
    entry there no matter how many times the index is rebuilt.

    Uses the same on-disk price cache (cache_get_prices/cache_set_prices,
    1-day TTL) as every other ticker in this file, so repeat opens are
    instant and don't re-hit yfinance. Currency-scaled leverage tiers
    and halt floor (via _ccy_for_label/_stock_leverage_tiers_for_ccy/
    _stock_dlc_floor_for_ccy) so a JPY/KRW-priced stock isn't compared
    against RM-sized tier steps. Also writes the result into
    app.iw_zd_snapshot/app.iw_zd_series in place (when present) so the
    trade popup and every other reader of those dicts picks it up too,
    not just this one call.

    Returns (None, None) if there's no usable price history, or the
    stock fails its market's minimum-price eligibility bar
    (STOCK_DLC_MIN_ELIGIBLE_PRICE)."""
    snap_all   = getattr(app, 'iw_zd_snapshot', None)
    series_all = getattr(app, 'iw_zd_series', None)
    if snap_all is not None and symbol in snap_all:
        return snap_all[symbol], (series_all or {}).get(symbol)

    try:
        hist = cache_get_prices(symbol, START_DATE_STR)
        if hist is None:
            raw = yf.Ticker(symbol).history(start=START_DATE_STR, interval='1d')
            if raw is not None and not raw.empty:
                hist = raw['Close'].dropna()
                hist.index = hist.index.tz_localize(None)
                cache_set_prices(symbol, hist)
        if hist is None or hist.empty:
            return None, None
    except Exception:
        return None, None

    ccy = _ccy_for_label(symbol)
    frame = {symbol: pd.DataFrame({symbol: hist})}
    snap, series = build_iw_zd_snapshot(
        frame, leverage_tiers=_stock_leverage_tiers_for_ccy(ccy),
        dynamic_floor_fn=lambda spot: _stock_dlc_floor_for_ccy(spot, ccy),
        min_eligible_fn=is_stock_dlc_eligible)
    if symbol not in snap:
        return None, None

    if snap_all is not None:
        snap_all[symbol] = snap[symbol]
    if series_all is not None:
        series_all[symbol] = series[symbol]
    return snap[symbol], series[symbol]


# ── Options Chain (SPX-style) — paper-trading calls/puts across a strip
# of strikes and a few tenors, reusing the same Black-Scholes engine as
# Index Warrants (see _iw_raw_price in build_indices) but as a proper
# chain (multiple strikes side-by-side) instead of one smart-struck
# call/put per index. Priced live off whatever iw_snapshot already has
# (spot + calc_vol_annual) — no separate fetch or engine change needed.
OPT_CHAIN_TENORS = (('30D', 30), ('60D', 60), ('90D', 90))
OPT_CHAIN_STRIKE_STEPS_PCT = (-10, -5, -2.5, 0, 2.5, 5, 10)  # % offset from spot
OPT_CHAIN_MULTIPLIER = 1.0   # Cr per index point per lot — paper trading only

def _ul_dl_label(side: str) -> str:
    """Options Chain display label — Call is shown as 'UL' (Upper Limit:
    profits above the strike), Put as 'DL' (Lower Limit: profits below
    the strike). Purely a display relabel over the SAME underlying
    call/put side value and the same DTE (Days-To-Expiry) pricing engine
    (bs_option_price) — no separate UL/DL product logic, no change to
    what's stored in a position ('call'/'put' unchanged there)."""
    return 'UL' if (side or '').lower() == 'call' else 'DL'
_TTL_FUNDAMENTALS = 86_400 # 1 day — P/E, EPS, market cap change slowly; no

def _json_safe(o):
    """default= hook for json.dump — every persisted save in this file
    (portfolio positions, Cr balance, FDs, savings, ATH/ATL state...)
    stores values computed straight out of pandas/numpy arithmetic, e.g.
    a position's entry_price or qty can land as np.float64/np.int64
    rather than a plain float/int. json.dump raises TypeError on those
    with no default= hook — and _cache_wjson's bare `except: pass` (plus
    the bare dumps elsewhere) was swallowing that error silently, so the
    save looked like it succeeded but nothing actually hit disk. That's
    what was really behind positions/balances vanishing on restart, not
    a missing save call — the save calls were already all there."""
    if isinstance(o, np.integer):
        return int(o)
    if isinstance(o, np.floating):
        return float(o)
    if isinstance(o, np.bool_):
        return bool(o)
    if isinstance(o, np.ndarray):
        return o.tolist()
    if isinstance(o, (pd.Timestamp, datetime)):
        return o.isoformat()
    raise TypeError(f'Object of type {type(o).__name__} is not JSON serializable')

def _cache_wjson(path: str, data: dict):
    import json as _j
    try:
        with open(path, 'w', encoding='utf-8') as f: _j.dump(data, f, default=_json_safe)
    except Exception as e:
        print(f'⚠️  cache write failed for {path}: {e}')


def _last_business_day(d: date) -> date:
    """Most recent Mon-Fri strictly before `d` (coarse floor — ignores
    per-market holiday calendars, just Sat/Sun). Used by cache_get_prices
    to know the calendar date a daily Close cache SHOULD already cover,
    independent of how long ago the cache file itself was written."""
    d -= timedelta(days=1)
    while d.weekday() >= 5:   # Sat=5, Sun=6
        d -= timedelta(days=1)
    return d


def cache_get_prices(ticker: str, start_str: str = None) -> 'pd.Series | None':
    """Return cached daily Close series, or None if stale/missing.

    Staleness is TWO checks, not one — the flat _TTL_PRICE elapsed-time
    check alone let a cache written early Friday (before Friday's own
    close posted) keep reporting 'fresh' for the full 24h, straight
    through into Saturday, even though a whole new close (Friday's) had
    become available and was never fetched. A same-day deposit landing
    on that ticker would then sit parked as pending Cash indefinitely —
    not just for the rest of Friday, but still on Saturday, because
    nothing ever forced a refetch. The date-floor check below closes
    that gap: even a file written minutes ago is stale if its last
    cached row doesn't yet reach the last completed business day."""
    p = _pticker(ticker)
    if not _cache_fresh(p, _TTL_PRICE): return None
    df = _cache_rparquet(p)
    if df is None or df.empty: return None
    s = df['Close'] if 'Close' in df.columns else df.iloc[:, 0]
    try:
        last_cached_date = s.index.max().date()
        if last_cached_date < _last_business_day(date.today()):
            return None
    except Exception:
        pass
    if start_str:
        try: s = s[s.index >= pd.Timestamp(start_str)]
        except: pass
    return s if not s.empty else None

def _get_ticker_dividends(ticker: str) -> 'pd.Series | None':
    """Per-share dividend history for `ticker`, cache-first (see
    cache_get_divs/cache_set_divs above), else a live yfinance pull that
    gets cached for next time. Used by Wealth Pack dividend settlement
    (settle_wealth_pack_dividends) — a pack can hold tickers outside the
    main index universe, so this doesn't assume the ticker was already
    picked up by the batch dividend fetch that runs during the main
    index rebuild."""
    s = cache_get_divs(ticker)
    if s is not None and not s.empty:
        return s
    try:
        divs = yf.Ticker(ticker).dividends
        if divs is None or divs.empty:
            return None
        if divs.index.tz is not None:
            divs.index = divs.index.tz_localize(None)
        if not divs.empty:
            cache_set_divs(ticker, divs)
        return divs if not divs.empty else None
    except Exception:
        return None


def fetch_live_underlying_quote(symbol: str, ttl: int = 60):
    """Direct live last-price ping for ANY single underlying symbol —
    stock or index ticker — via yfinance's fast_info. This is what makes
    "live trading" actually work for an underlying that isn't one of the
    composite indices the background basket-ping loop covers
    (app._index_day_hilo, populated only from app.weights_snapshot): a
    tracked stock, or any new symbol added on the fly through Search and
    opened as DLC/IW-ZD (see get_or_build_stock_dlc_snapshot). Cached for
    `ttl` seconds (default 60, matching LIVE_PING_INTERVAL) so repeat
    calls — e.g. a live-toggle redraw — don't re-hit the network every
    time. Returns None if the symbol has no live quote available."""
    cache_key = f'ping_stock_{symbol}'
    cached = cache_get_live(cache_key, ttl=ttl)
    if cached is not None:
        return cached
    try:
        fi = yf.Ticker(symbol).fast_info
        last = fi.get('last_price') or fi.get('lastPrice')
        if not last:
            return None
        last = float(last)
        cache_set_live(cache_key, last)
        return last
    except Exception:
        return None


# =============================================================================
# MARKET_DATA
# =============================================================================
# Market-session clocks (which exchange session we're in right now), tick
# sizes, and the dividend-alert persistence log. Pure helpers — no
# dependency on INDEX_ENGINE.

def _us_market_session() -> str:
    """Which US-equity session we're in right now, off the US Eastern clock:
      'P' Pre-market   4:00 AM - 9:30 AM  ET
      'L' Live/regular 9:30 AM - 4:00 PM  ET  (Mon-Fri)
      'N' Night market 4:00 PM - 8:00 PM  ET  (after-hours session)
      'H' Holiday      NYSE closed today (NYSE_HOLIDAYS), else same as 'C'
      'C' Closed       everything else
    """
    if not US_EASTERN_TZ:
        return 'C'
    now_et = datetime.now(US_EASTERN_TZ)
    if now_et.weekday() >= 5:   # Saturday=5, Sunday=6
        return 'C'
    if _is_market_holiday('USD', now_et.date()):
        return 'H'
    t = now_et.time()
    if time(4, 0) <= t < time(9, 30):
        return 'P'
    if time(9, 30) <= t < time(16, 0):
        return 'L'
    if time(16, 0) <= t < time(20, 0):
        return 'N'
    return 'C'


def _us_session_tag() -> str:
    """'(P)'/'(L)'/'(N)'/'(C)' for the current US session state."""
    return f'({_us_market_session()})'


_ASIA_SESSIONS = {
    'MYR': [(time(9, 0),  time(12, 30), 'L'), (time(12, 30), time(14, 30), 'M'),
             (time(14, 30), time(16, 45), 'L')],
    'SGD': [(time(9, 0),  time(12, 0),  'L'), (time(12, 0),  time(13, 0),  'M'),
             (time(13, 0), time(17, 0),  'L')],
    'HKD': [(time(9, 30), time(12, 0),  'L'), (time(12, 0),  time(13, 0),  'M'),
             (time(13, 0), time(16, 0),  'L')],
    # TSE (JPY): 09:00-11:30 / 12:30-15:30 JST -> UTC+9, 1hr ahead of
    # Malaysia's UTC+8 clock -> 08:00-10:30 / 11:30-14:30 MYT.
    'JPY': [(time(8, 0),  time(10, 30), 'L'), (time(10, 30), time(11, 30), 'M'),
             (time(11, 30), time(14, 30), 'L')],
    # KRX (KRW): 09:00-15:30 KST continuous, no midday break -> same UTC+9
    # offset as JST -> 08:00-14:30 MYT straight through.
    'KRW': [(time(8, 0),  time(14, 30), 'L')],
    # TWSE (TWD): 09:00-13:30 Taiwan time, continuous, no midday break.
    # Taiwan runs UTC+8 -- same offset as Malaysia -- so no clock shift
    # needed, unlike JPY/KRW. Scaffolding for a planned Taiwan (.TW)
    # expansion; not yet wired into any DLC underlying list.
    'TWD': [(time(9, 0),  time(13, 30), 'L')],
    # ASX (AUD): 10:00-16:00 AEST continuous, no midday break. AEST is
    # UTC+10, 2hr ahead of Malaysia's UTC+8 -> 08:00-14:00 MYT. Like
    # every other entry in this table, this ignores daylight saving
    # (AEDT, UTC+11 over the Australian summer) — same hand-set
    # simplification already used for the rest of this file's "ignore
    # DST" design, not a real per-season clock shift.
    'AUD': [(time(8, 0),  time(14, 0),  'L')],
}


def _stock_market_status(ccy: str):
    """Real cash-equity trading status for `ccy`'s own exchange — plain
    stock buys/sells should gate on THIS, never on
    _iw_zd_effective_phase()/_iw_zd_trading_allowed(), which are the
    daily leveraged-certificate (DLC/IW-ZD) pre-order/overnight cycle,
    a completely different product with its own 4:50 PM/5:00 PM clock.
    A plain stock has no such cycle — it simply trades whenever its own
    exchange is open. Returns (is_open, msg)."""
    tag = _market_session_tag(ccy).strip('()')
    if tag == 'L':
        return True, f'🟢 {ccy} market open — live trading'
    if tag == 'M':
        # Midday break is a pause in matching, not a market close — an
        # order placed now queues at the last live mark and fills at
        # the afternoon re-open, same as any real broker allows.
        return True, f'🟡 {ccy} market on its midday break — order queues, fills at afternoon re-open'
    if tag == 'W':
        return False, f'🔒 {ccy} market closed — weekend'
    if tag == 'P':
        return False, f'🔒 {ccy} market closed — public holiday'
    return False, f'🔒 {ccy} market closed — outside trading hours'


# ── Wealth Management pending-order fill rule ──────────────────────────
# US market            : grace window runs through 8:00 PM ET (matches
#                         _us_market_session()'s 'N' after-hours state).
# Bursa (MYR)           : close + 1h grace.
# Every other market
#   (SGD/HKD/JPY/KRW/TWD): close + 3h grace.
# Inside the grace window, a pending top-up/contribution still fills at
# TODAY's close (fresh enough to trust). Outside it — or before that
# market has opened at all today — the order does NOT fill on a stale
# close; it waits and fills at that market's own NEXT open instead.
POST_CLOSE_GRACE_HOURS = {'MYR': 1}          # everyone else defaults below
POST_CLOSE_GRACE_DEFAULT_HOURS = 3            # SGD/HKD/JPY/KRW/TWD


def wealth_order_price_mode(ccy: str):
    """Returns ('live'|'close'|'wait', msg) for a Wealth Management
    pending order/top-up dated today, based on `ccy`'s own exchange
    clock right now — see module note above for the exact rule.
    'live'  -> fill at the live/current price.
    'close' -> fill at TODAY's close (still inside grace window).
    'wait'  -> stays pending; fills at that market's NEXT open."""
    ccy = (ccy or 'MYR').upper()

    if ccy == 'USD':
        tag = _us_market_session()
        if tag == 'L':
            return 'live', '🟢 US market open — live price'
        if tag == 'P':
            return 'wait', '🔒 Pre-market — waiting for US market open'
        if tag == 'N':
            return 'close', "🟡 After-hours (before 8:00 PM ET) — filling at today's close"
        return 'wait', '🔒 Past 8:00 PM ET / market closed — waiting for next US open'

    if ccy not in ('MYR', 'SGD', 'HKD', 'JPY', 'KRW', 'TWD', 'AUD'):
        return 'live', ''   # nothing to gate on (e.g. CASH)

    tag = _asia_market_session(ccy)
    if tag in ('L', 'M'):
        return 'live', f'🟢 {ccy} market open — live price'
    if tag in ('W', 'P'):
        return 'wait', f'🔒 {ccy} market closed (weekend/holiday) — waiting for next open'

    if not MALAYSIA_TZ:
        return 'wait', ''
    now_t = datetime.now(MALAYSIA_TZ).time()
    mkt_open, mkt_close = _market_open_time(ccy), _market_close_time(ccy)

    if now_t < mkt_open:
        return 'wait', f'🔒 Before {ccy} market open — will fill at opening price'

    grace_hours = POST_CLOSE_GRACE_HOURS.get(ccy, POST_CLOSE_GRACE_DEFAULT_HOURS)
    grace_end = _add_minutes(mkt_close, grace_hours * 60)
    if now_t < grace_end:
        return 'close', f"🟡 {ccy} market closed, within {grace_hours}h grace — filling at today's close"
    return 'wait', f'🔒 {ccy} market closed, past its {grace_hours}h grace — waiting for next open'


def check_wealth_pending_fills(app):
    """Pops up an estimated buy-in the moment a market that had Wealth
    Management cash parked in 'wait' mode (pre-market, or past its
    post-close grace window — see wealth_order_price_mode) actually
    opens (or re-enters its post-close grace window on a fresh day).
    Detects the transition per currency using a simple last-seen-mode
    cache (survives restarts via cache_get_live/cache_set_live), so
    this only fires once per open, not on every rebuild while the
    market stays open. The estimate itself is native_pending_cash /
    CURRENT price — a best-effort figure, since the real fill (handled
    by _compute_pack_current_units on the next rebuild) uses whatever
    price actually prints, not this snapshot. Call once per rebuild,
    alongside settle_stock_pending_orders()/settle_wealth_pack_dividends()."""
    if not _WEALTH_PENDING_NATIVE:
        return
    dash = app.pages.get('Dashboard') if hasattr(app, 'pages') else None
    for ccy in ('USD', 'MYR', 'SGD', 'HKD', 'JPY', 'KRW', 'TWD', 'AUD'):
        mode, _msg = wealth_order_price_mode(ccy)
        cache_key = f'wealth_mode_last_{ccy}'
        prev_mode = cache_get_live(cache_key, ttl=10 ** 9)
        cache_set_live(cache_key, mode)
        if prev_mode != 'wait' or mode not in ('live', 'close'):
            continue

        lines = []
        for key in [k for k in _WEALTH_PENDING_NATIVE if _ccy_for_label(k[1]) == ccy]:
            pack_name, ticker = key
            native_amt = _WEALTH_PENDING_NATIVE.pop(key, 0.0)
            if native_amt <= 0:
                continue
            price = _stock_price_now(app, ticker)
            if not price or price <= 0:
                continue
            est_units = math.floor((native_amt / price) / WEALTH_MIN_UNIT) * WEALTH_MIN_UNIT
            lines.append(f"  {pack_name} — {ticker}: ~{est_units:.4f} units @ {price:,.3f} "
                         f"(≈{native_amt:,.2f} {ccy})")
        if not lines:
            continue

        header = f"📈 {ccy} market is open — estimated Wealth Pack buy-in:"
        full_msg = header + "\n" + "\n".join(lines)
        if dash is not None:
            dash.append_log(full_msg)
        try:
            messagebox.showinfo(f'{ccy} Market Open — Estimated Buy-In', full_msg)
        except Exception:
            pass


def _asia_market_session(ccy: str) -> str:
    """Which session Bursa (MYR) / SGX (SGD) / HKEX (HKD) is in right now.
    All three run on UTC+8 with no DST, same as Malaysia's clock:
      MYR (Bursa) : 09:00-12:30 L, 12:30-14:30 M, 14:30-16:45 L, else C
      SGD (SGX)   : 09:00-12:00 L, 12:00-13:00 M, 13:00-17:00 L, else C
      HKD (HKEX)  : 09:30-12:00 L, 12:00-13:00 M, 13:00-16:00 L, else C
    'L' live, 'M' midday break, 'C' closed (on an actual trading day,
    just outside hours), 'W' weekend, 'P' public holiday — now checked
    for all three via _is_market_holiday()/MARKET_HOLIDAYS_BY_CCY
    (Bursa/SGX/HKEX each have their own calendar)."""
    if not MALAYSIA_TZ:
        return 'C'
    now = datetime.now(MALAYSIA_TZ)
    if now.weekday() >= 5:
        return 'W'
    if _is_market_holiday(ccy, now.date()):
        return 'P'
    t = now.time()
    for start, end, tag in _ASIA_SESSIONS.get((ccy or '').upper(), []):
        if start <= t < end:
            return tag
    return 'C'


def _market_close_time(ccy: str) -> time:
    """The exchange's own last-session close for `ccy` (end of the final
    tuple in _ASIA_SESSIONS) — 16:45 Bursa, 17:00 SGX, 16:00 HKEX. Falls
    back to Bursa's close for anything not in the table, since that was
    this file's only anchor before per-market DLC windows existed."""
    sessions = _ASIA_SESSIONS.get((ccy or '').upper())
    if not sessions:
        return _ASIA_SESSIONS['MYR'][-1][1]
    return sessions[-1][1]


def _market_open_time(ccy: str) -> time:
    """Local market open for `ccy`, MYT clock — this is where the
    overnight Pre-Order window hands off to full Live trading (see
    _iw_zd_session_state()). TSE (JPY), KRX (KRW), and ASX (AUD) all
    open ahead of Malaysia's UTC+8 clock, so they open at 08:00 MYT;
    Bursa/SGX/HKEX all open at 09:00 MYT."""
    return time(8, 0) if (ccy or '').upper() in ('JPY', 'KRW', 'AUD') else time(9, 0)


def _add_minutes(t: time, minutes: int) -> time:
    return (datetime.combine(date(2000, 1, 1), t) + pd.Timedelta(minutes=minutes)).time()


def _ccy_for_label(label: str) -> str:
    """Best-effort exchange currency for a DLC/IW-ZD underlying label.
    Single-stock symbols carry their exchange in the ticker suffix
    (####.KL -> MYR Bursa, .SI -> SGD SGX, .HK -> HKD HKEX, .KS -> KRW
    KOSPI, .T -> JPY TSE, .TW -> TWD TWSE, .AX -> AUD ASX). US tickers carry NO suffix
    at all (e.g. "AAPL", "BRK.B") — matched via _US_STOCK_SYMBOL_RE,
    checked LAST among the pattern-based rules (after every suffixed
    exchange and the explicit composite-index names below) so a US
    ticker never gets misread as an unrecognized-suffix Bursa symbol,
    and a bare index name like KOSPI/TAIEX never gets misread as a US
    ticker. The regional composite indices (Hang Seng, Straits Times,
    Nikkei 225, KOSPI) are DLC underlyings too but carry NO ticker
    suffix at all — just their plain display name — so they need their
    own explicit lookup here or they'd silently fall through to the
    MYR default below and get gated on Bursa's hours instead of their
    own exchange's (HKEX/SGX/TSE/KRX respectively). Everything else
    (MYIPO+/Top-N/FBM KLCI composite labels, or an unrecognized suffix)
    defaults to MYR, since those really are Bursa-anchored."""
    label = str(label or '').upper()
    if label.endswith('.SI'):
        return 'SGD'
    if label.endswith('.HK'):
        return 'HKD'
    if label.endswith('.KS'):
        return 'KRW'
    if label.endswith('.T'):
        return 'JPY'
    if label.endswith('.TW'):
        return 'TWD'
    if label.endswith('.AX'):
        return 'AUD'
    if label == 'HANG SENG':
        return 'HKD'
    if label == 'STRAITS TIMES':
        return 'SGD'
    if label == 'NIKKEI 225':
        return 'JPY'
    if label == 'KOSPI':
        return 'KRW'
    if label == 'TAIEX':
        return 'TWD'
    if _US_STOCK_SYMBOL_RE.match(label):
        return 'USD'
    return 'MYR'


def _market_for_ticker(ticker: str) -> str:
    """Which market/exchange a ticker belongs to, purely from its
    suffix — same suffix rules _ccy_for_label uses for currency, just
    mapped to a human market name instead of a currency code. Used to
    group the Fund Composition list by market instead of only by
    individual ticker."""
    if ticker == WEALTH_CASH_TICKER:
        return 'Cash'
    label = str(ticker or '').upper()
    if label.endswith('.SI'):
        return 'Singapore (SGX)'
    if label.endswith('.HK'):
        return 'Hong Kong (HKEX)'
    if label.endswith('.KS'):
        return 'South Korea (KRX)'
    if label.endswith('.T'):
        return 'Japan (TSE)'
    if label.endswith('.TW'):
        return 'Taiwan (TWSE)'
    if label.endswith('.AX'):
        return 'Australia (ASX)'
    if label.endswith('.KL'):
        return 'Malaysia (Bursa)'
    if _US_STOCK_SYMBOL_RE.match(label):
        return 'United States'
    return 'Malaysia (Bursa)'



