def _is_my_market_holiday(d) -> bool:
    """True if `d` (a date or datetime) is a Bursa Malaysia public holiday
    per BURSA_MY_HOLIDAYS. Falls open (returns False) for any year not in
    the table rather than raising, so an un-refreshed calendar degrades to
    "weekday-only" gating instead of breaking Live Ping outright."""
    if hasattr(d, 'date'):
        d = d.date()
    return d in BURSA_MY_HOLIDAYS


