def _dca_due(plan: dict, today: date) -> bool:
    """Whether `plan` (one symbol's DCA settings) is due to fire today —
    'daily' fires any day it hasn't already run today, 'weekly' every 7
    days since last_run, 'monthly' once per calendar month. A plan with
    no last_run yet is always due (first run)."""
    last = plan.get('last_run')
    if not last:
        return True
    try:
        last_d = pd.Timestamp(last).date()
    except Exception:
        return True
    if last_d >= today:
        return False
    freq = plan.get('frequency', 'daily')
    if freq == 'daily':
        return True
    if freq == 'weekly':
        return (today - last_d).days >= 7
    if freq == 'monthly':
        return (today.year, today.month) != (last_d.year, last_d.month)
    return True


def bs_option_price(spot: float, strike: float, vol: float, tenor_days: float, side: str):
    """Standalone Black-Scholes call/put price + delta — same formula as
    the Index Warrant engine's internal _iw_raw_price (build_indices),
    but not nested inside that closure, so the Options Chain page can
    call it directly for any strike/tenor combo without touching the
    core index-build engine. No dividend yield / risk-free discounting —
    illustrative paper-trading pricing, not exchange quoting."""
    try:
        from scipy.stats import norm
        t = max(tenor_days, 1) / 365.0
        if spot <= 0 or strike <= 0 or vol <= 0:
            raise ValueError
        d1 = (np.log(spot / strike) + 0.5 * vol ** 2 * t) / (vol * np.sqrt(t))
        d2 = d1 - vol * np.sqrt(t)
        if side == 'call':
            price = spot * norm.cdf(d1) - strike * norm.cdf(d2)
            delta = norm.cdf(d1)
        else:
            price = strike * norm.cdf(-d2) - spot * norm.cdf(-d1)
            delta = norm.cdf(d1) - 1.0
    except Exception:
        intrinsic = max(spot - strike, 0.0) if side == 'call' else max(strike - spot, 0.0)
        time_value = spot * (vol if vol else 0.20) * np.sqrt(max(tenor_days, 1) / 365.0) * 0.4
        price = intrinsic + time_value
        delta = 0.5 if side == 'call' else -0.5
    return float(max(price, 0.0)), float(delta)


# ---------------------------------------------------------------------------
# Fixed daily FX snapshot for displaying total credit in another currency.
#
# When the account currency selector is set to something other than USD,
# the displayed "total credit" figure should NOT jitter with the live
# yfinance rate all day — it's fixed once per day, at the same anchor as
# the Cr daily refresh (midnight Malaysia time == 16:00 / 4:00 PM GMT,
# since MYT is GMT+8 with no DST). The snapshot rate is taken once at (or
# after) that rollover and held for the rest of the day, same JSON file
# pattern as the balance state above.
# ---------------------------------------------------------------------------

CR_FX_SNAPSHOT_FILE = os.path.join(_CACHE_DIR, 'cr_fx_snapshot.json')


def _load_cr_fx_snapshot() -> dict:
    """{'date': 'YYYY-MM-DD', 'rates': {'MYR': 4.42, ...}} — one USD-><ccy>
    mid rate per currency, locked in for the day."""
    import json as _j
    if not os.path.exists(CR_FX_SNAPSHOT_FILE):
        return {'date': None, 'rates': {}}
    try:
        with open(CR_FX_SNAPSHOT_FILE, 'r') as f:
            snap = _j.load(f)
        snap.setdefault('date', None)
        snap.setdefault('rates', {})
        return snap
    except Exception:
        return {'date': None, 'rates': {}}


def _save_cr_fx_snapshot(snap: dict):
    import json as _j
    os.makedirs(_CACHE_DIR, exist_ok=True)
    try:
        with open(CR_FX_SNAPSHOT_FILE, 'w') as f:
            _j.dump(snap, f, default=_json_safe)
    except Exception as e:
        print(f'⚠️  cr_fx_snapshot.json save failed: {e}')


def _cr_fx_snapshot_rate(ccy: str) -> float:
    """USD-><ccy> mid rate fixed at the day's Malaysia-midnight anchor.
    Refreshed the first time any currency is looked up after rollover;
    every other lookup that same day reuses the same held rate — so the
    displayed total credit stays flat all day even as the live yfinance
    rate moves. Falls back to a fresh live fetch if this is the very
    first read of a new currency mid-day (e.g. account currency just
    switched to one never snapshotted before)."""
    ccy = (ccy or '').upper()
    today_str = _cr_today_str()
    snap = _load_cr_fx_snapshot()
    if snap.get('date') != today_str:
        snap = {'date': today_str, 'rates': {}}
    cached = snap['rates'].get(ccy)
    # A NaN can end up cached here from a bad yfinance read on an earlier
    # call (now impossible going forward — _fx_mid_rate raises instead —
    # but an already-corrupted snapshot file from before that fix would
    # otherwise sit here poisoning every lookup for the rest of the day,
    # since `ccy in snap['rates']` is True even when the value is NaN).
    if cached is None or not math.isfinite(cached) or cached <= 0:
        snap['rates'][ccy] = _fx_mid_rate(ccy)
        _save_cr_fx_snapshot(snap)
    return snap['rates'][ccy]


# ---------------------------------------------------------------------------
# Display currency — a pure UI preference (which currency Cr amounts are
# SHOWN as, app-wide), completely separate from the trading currency any
# given position/order is denominated in. Persisted to its own tiny JSON
# file (same _CACHE_DIR convention as cr_balance.json) so it survives
# restarts. Defaults to USD (Cr's own peg currency) until the user picks
# something else in Settings.
# ---------------------------------------------------------------------------

DISPLAY_CCY_FILE   = os.path.join(_CACHE_DIR, 'display_ccy.json')
SUPPORTED_DISPLAY_CCYS = ['USD', 'MYR', 'HKD', 'JPY', 'KRW', 'SGD']


def get_display_ccy() -> str:
    """Currently selected display currency (Settings page), USD if never set."""
    try:
        if os.path.exists(DISPLAY_CCY_FILE):
            import json as _j
            with open(DISPLAY_CCY_FILE, 'r') as f:
                ccy = _j.load(f).get('ccy', 'USD')
            if ccy in SUPPORTED_DISPLAY_CCYS:
                return ccy
    except Exception:
        pass
    return 'USD'


def set_display_ccy(ccy: str):
    """Persist the user's chosen display currency. No-op (raises nothing)
    if `ccy` isn't one of SUPPORTED_DISPLAY_CCYS."""
    ccy = (ccy or 'USD').upper()
    if ccy not in SUPPORTED_DISPLAY_CCYS:
        return
    import json as _j
    os.makedirs(_CACHE_DIR, exist_ok=True)
    try:
        with open(DISPLAY_CCY_FILE, 'w') as f:
            _j.dump({'ccy': ccy}, f)
    except Exception as e:
        print(f'⚠️  display_ccy.json save failed: {e}')


