def get_cr_balance_display(ccy: str = 'USD') -> dict:
    """Current total credit (Cr balance), converted into `ccy` at the
    rate locked in at today's Malaysia-midnight anchor (not the live
    rate). USD selection just returns the plain USD-equivalent, no
    spread/snapshot involved since Cr is pegged straight to USD.
    Returns {'ccy', 'cr_balance', 'usd_equiv', 'display_amount',
    'fx_rate', 'spread_pct', 'snapshot_date'}."""
    ccy = (ccy or 'USD').upper()
    cr_balance = get_cr_balance()
    usd_equiv = cr_to_usd(cr_balance)

    if ccy == 'USD':
        return {
            'ccy': 'USD', 'cr_balance': cr_balance, 'usd_equiv': usd_equiv,
            'display_amount': usd_equiv, 'fx_rate': 1.0,
            'spread_pct': 0.0, 'snapshot_date': _cr_today_str(),
        }

    mid = _cr_fx_snapshot_rate(ccy)
    sell_rate = mid * (1 - FX_SPREAD_BASE)  # converting USD/Cr OUT into ccy for display
    return {
        'ccy': ccy,
        'cr_balance': cr_balance,
        'usd_equiv': usd_equiv,
        'display_amount': usd_equiv * sell_rate,
        'fx_rate': sell_rate,
        'spread_pct': FX_SPREAD_BASE,
        'snapshot_date': _load_cr_fx_snapshot().get('date'),
    }


# ---------------------------------------------------------------------------
# Central bank policy rates (annual %), used only to price savings interest.
#
#   USD -> Fed Funds Rate (effective), pulled from FRED's public CSV feed
#          (no API key needed).
#   HKD -> same Fed Funds fetch as USD — HKD is a hard USD peg, so its
#          policy rate tracks the Fed's, not its own separate number.
#   MYR -> Bank Negara Malaysia's OPR (Overnight Policy Rate), scraped
#          off BNM's own rates page since there's no equivalent stable
#          CSV feed for it.
#   JPY -> Bank of Japan central bank rate, via FRED series
#          IRSTCB01JPM156N (OECD-sourced, monthly — lags real-time BOJ
#          announcements by up to a month, but stable and key-free).
#   KRW -> Bank of Korea policy-rate proxy, via FRED series
#          IRSTCI01KRM156N (call money/interbank rate, OECD-sourced,
#          monthly — closest stable public feed to BOK's own rate).
#   SGD -> Singapore Overnight Rate Average (SORA), pulled from MAS's
#          own public datastore API. MAS doesn't run a traditional
#          policy-rate regime (it manages policy via the SGD NEER
#          exchange-rate band instead), so SORA is the standard market
#          proxy used here.
#   Any other currency -> no fetcher wired up yet; falls back to
#          CB_RATE_FALLBACK (0.0% unless added) until a source is added
#          for that currency's own central bank.
#
# Cached for CB_RATE_TTL (24h) via the same cache_get_live used for FX
# quotes elsewhere in this file — policy rates don't move intraday, so
# there's no reason to hit the network more than once a day. If the
# fetch fails (network down, page format changed, etc.), falls back to
# whatever was last cached (even if stale), then to the static
# CB_RATE_FALLBACK constant as a last resort — it never raises out to
# the caller.
# ---------------------------------------------------------------------------

CB_RATE_TTL = 86_400  # 24h — policy rates don't move intraday

CB_RATE_FALLBACK = {
    'USD': 4.33,
    'HKD': 4.33,   # mirrors USD — see note above
    'MYR': 3.00,
    'JPY': 0.50,   # BOJ short-term policy rate ballpark
    'KRW': 2.50,   # BOK base rate ballpark
    'SGD': 2.80,   # SORA ballpark — MAS has no traditional policy rate;
                   # it manages policy via the SGD NEER band instead, so
                   # SORA (overnight rate) is the standard market proxy
    'AUD': 3.60,   # RBA cash rate ballpark — no live fetcher wired up
                   # yet (no CB_RATE_FETCHERS entry), so this static
                   # fallback is always what's used for AUD savings
                   # interest. AUD FD rates below are hand-set flat
                   # figures instead (see FD_RATE_FLAT_AUD), not built
                   # off this policy rate + a spread like the others.
}


def _fetch_fred_series(series_id: str) -> float:
    """Latest value (%) of a FRED series via its public CSV feed — no
    API key required. Shared by the USD, JPY, and KRW fetchers below,
    each pointed at a different OECD-sourced central-bank-rate series."""
    import requests, csv, io
    url = f'https://fred.stlouisfed.org/graph/fredgraph.csv?id={series_id}'
    resp = requests.get(url, timeout=10)
    resp.raise_for_status()
    rows = [r for r in csv.reader(io.StringIO(resp.text)) if r and r[0] != 'DATE']
    return float(rows[-1][1])


def _fetch_fed_funds_rate() -> float:
    """Effective Federal Funds Rate (%) off FRED's public CSV feed."""
    return _fetch_fred_series('DFF')


def _fetch_boj_rate() -> float:
    """Bank of Japan central bank rate (%) — FRED series IRSTCB01JPM156N
    (OECD Main Economic Indicators, monthly). Lags real-time BOJ
    announcements by up to a month since it's a monthly OECD feed, but
    it's a stable, key-free public source."""
    return _fetch_fred_series('IRSTCB01JPM156N')


def _fetch_bok_rate() -> float:
    """Bank of Korea policy-rate proxy (%) — FRED series IRSTCI01KRM156N,
    the call money/interbank rate (OECD Main Economic Indicators,
    monthly), closest stable public feed to BOK's own base rate."""
    return _fetch_fred_series('IRSTCI01KRM156N')


def _fetch_mas_sora() -> float:
    """Singapore Overnight Rate Average (%) off MAS's own public
    datastore API. Used as the SGD policy-rate proxy because MAS
    conducts monetary policy via the SGD NEER exchange-rate band rather
    than a traditional interest-rate target, so there's no BOJ/Fed-style
    single policy rate to fetch — SORA is the standard market proxy."""
    import requests
    url = ('https://eservices.mas.gov.sg/api/action/datastore/search.json'
           '?resource_id=9a0bf149-308c-4bd2-832d-76c8e6cb47ed'
           '&limit=1&sort=end_of_day desc')
    resp = requests.get(url, timeout=10)
    resp.raise_for_status()
    records = resp.json()['result']['records']
    return float(records[0]['sora'])


def _fetch_bnm_opr() -> float:
    """Bank Negara Malaysia's Overnight Policy Rate (%), scraped off
    BNM's own rates page. No stable public CSV feed exists for this one,
    so this is inherently more fragile than the FRED fetch above — any
    parse failure bubbles up and the caller falls back to cache/static."""
    import requests, re
    url = 'https://www.bnm.gov.my/monetary-stability/opr-decisions'
    resp = requests.get(url, timeout=10)
    resp.raise_for_status()
    m = re.search(r'OPR[^%]{0,40}?(\d+\.\d+)\s*%', resp.text)
    if not m:
        raise ValueError('could not parse OPR off the BNM page')
    return float(m.group(1))


CB_RATE_FETCHERS = {
    'USD': _fetch_fed_funds_rate,
    'HKD': _fetch_fed_funds_rate,
    'MYR': _fetch_bnm_opr,
    'JPY': _fetch_boj_rate,
    'KRW': _fetch_bok_rate,
    'SGD': _fetch_mas_sora,
}


def get_cb_policy_rate(ccy: str) -> float:
    """Annual central-bank policy rate (%) for `ccy`, cached 24h. Never
    raises — falls back to stale cache, then to CB_RATE_FALLBACK
    (0.0% if the currency has no fallback configured either)."""
    ccy = (ccy or 'USD').upper()
    key = f'CBRATE_{ccy}'
    cached = cache_get_live(key, ttl=CB_RATE_TTL)
    if cached is not None:
        return float(cached)

    rate = None
    fetcher = CB_RATE_FETCHERS.get(ccy)
    if fetcher:
        try:
            rate = fetcher()
        except Exception:
            rate = None

    if rate is None:
        stale = cache_get_live(key, ttl=10 ** 9)  # any age, just don't refetch
        rate = stale if stale is not None else CB_RATE_FALLBACK.get(ccy, 0.0)

    cache_set_live(key, rate)
    return float(rate)


# ---------------------------------------------------------------------------
# Savings sub-balance — Cr moved out of the trading balance to earn daily
# interest at the relevant central bank's policy rate (see get_cb_policy_rate
# above). Interest accrues daily: annual_rate / 365, applied once per
# Malaysia-midnight rollover, same anchor as the trading-balance top-up.
# ---------------------------------------------------------------------------

CR_SAVINGS_FILE = os.path.join(_CACHE_DIR, 'cr_savings.json')

# A real bank pays depositors LESS than the central bank policy rate — it
# keeps a margin. This account pays the FULL policy rate through to
# savings with ZERO deduction (0.00%). Kept as a named constant (rather
# than just "not subtracting anything") so the margin is explicit and
# easy to change later if that ever needs to stop being 0%.
CR_SAVINGS_RATE_DEDUCTION = 0.0  # percentage points shaved off the policy
                                  # rate before crediting savings interest

# Flat rate paid on Cr that lands in savings — deliberately NOT tied to
# get_cb_policy_rate(): this account isn't meant to be a yield play, just
# a safe place gains above CR_AUTO_SAVE_THRESHOLD get swept to instead of
# sitting idle in the trading balance (or being wiped by the old flat
# "reset to 10,000" behavior). 0.01% p.a., always.
CR_AUTO_SAVE_RATE_PA     = 0.01     # percent per annum, flat
CR_AUTO_SAVE_THRESHOLD   = 10_000   # trading balance floor that auto-sweep protects


def _load_savings_state() -> dict:
    """{'balance': float, 'ccy': 'USD', 'last_accrual_date': str|None}."""
    import json as _j
    if not os.path.exists(CR_SAVINGS_FILE):
        return {'balance': 0.0, 'ccy': 'USD', 'last_accrual_date': None}
    try:
        with open(CR_SAVINGS_FILE, 'r') as f:
            state = _j.load(f)
        state.setdefault('balance', 0.0)
        state.setdefault('ccy', 'USD')
        state.setdefault('last_accrual_date', None)
        return state
    except Exception:
        return {'balance': 0.0, 'ccy': 'USD', 'last_accrual_date': None}


def _save_savings_state(state: dict):
    import json as _j
    os.makedirs(_CACHE_DIR, exist_ok=True)
    try:
        with open(CR_SAVINGS_FILE, 'w') as f:
            _j.dump(state, f, default=_json_safe)
    except Exception as e:
        print(f'⚠️  cr_savings.json save failed: {e}')


def _accrue_savings(state: dict, ccy: str, today_str: str) -> dict:
    """Applies one day's interest at the flat CR_AUTO_SAVE_RATE_PA (0.01%
    p.a., annual_rate/365) for each day that has rolled over since the
    last accrual, then stamps today's date. No-op if already accrued
    today, and no-op on a zero/empty balance."""
    state['ccy'] = ccy
    if state.get('last_accrual_date') == today_str:
        return state
    if state.get('balance', 0.0) > 0:
        daily_rate = (CR_AUTO_SAVE_RATE_PA / 100.0) / 365.0
        state['balance'] = float(state['balance']) * (1 + daily_rate)
    state['last_accrual_date'] = today_str
    return state


def get_savings_balance(ccy: str = 'USD') -> float:
    """Current savings balance (in Cr), applying today's interest accrual
    first if it hasn't happened yet. `ccy` selects which central bank's
    policy rate applies — pass the account's currently selected display
    currency."""
    ccy = (ccy or 'USD').upper()
    state = _load_savings_state()
    today_str = _cr_today_str()
    before = (state.get('balance'), state.get('last_accrual_date'))
    state = _accrue_savings(state, ccy, today_str)
    if (state['balance'], state['last_accrual_date']) != before:
        _save_savings_state(state)
    return max(float(state.get('balance', 0.0)), 0.0)


def deposit_to_savings(amount: float, ccy: str = 'USD') -> dict:
    """Moves `amount` Cr from the trading balance into savings. Rejects
    (no state changed) if the trading balance can't cover it.
    Returns {'success', 'trading_balance', 'savings_balance'}."""
    if amount <= 0:
        raise ValueError('amount must be positive')
    trading = get_cr_balance()
    if amount > trading:
        return {'success': False, 'trading_balance': trading,
                 'savings_balance': get_savings_balance(ccy)}
    apply_cr_delta(-amount)
    state = _load_savings_state()
    state = _accrue_savings(state, ccy, _cr_today_str())
    state['balance'] = float(state.get('balance', 0.0)) + amount
    _save_savings_state(state)
    return {'success': True, 'trading_balance': get_cr_balance(),
             'savings_balance': state['balance']}


def withdraw_from_savings(amount: float, ccy: str = 'USD') -> dict:
    """Moves `amount` Cr from savings back into the trading balance.
    Rejects (no state changed) if savings can't cover it.
    Returns {'success', 'trading_balance', 'savings_balance'}."""
    if amount <= 0:
        raise ValueError('amount must be positive')
    savings = get_savings_balance(ccy)
    if amount > savings:
        return {'success': False, 'trading_balance': get_cr_balance(),
                 'savings_balance': savings}
    state = _load_savings_state()
    state = _accrue_savings(state, ccy, _cr_today_str())
    state['balance'] = max(float(state.get('balance', 0.0)) - amount, 0.0)
    _save_savings_state(state)
    apply_cr_delta(amount)
    return {'success': True, 'trading_balance': get_cr_balance(),
             'savings_balance': state['balance']}


def _auto_sweep_to_savings(today_str: str = None):
    """Whenever the trading balance clears CR_AUTO_SAVE_THRESHOLD (10,000
    Cr) for a full 24 hours straight, sweep the excess into savings
    rather than letting it sit idle in the trading balance. A 24-hour
    grace period (cr_state['above_threshold_since'], an epoch
    timestamp) comes first: the moment the balance crosses above the
    threshold the clock starts, but nothing is swept yet — so, say, a
    profitable IW close doesn't get immediately whisked into savings
    before there's a chance to actually spend it on the next trade a
    few minutes later. Only once that balance has stayed above the
    threshold continuously for 24h does the excess actually get
    swept; dropping back to/under the threshold at any point resets
    the clock, so a fresh 24h window starts the next time it crosses
    back above. Called from the bottom of apply_cr_delta() so it's
    checked on every balance-changing action (buy, close, settle,
    daily top-up)."""
    today_str = today_str or _cr_today_str()
    cr_state = _load_cr_state()
    balance = float(cr_state.get('balance', 0.0))
    excess = balance - CR_AUTO_SAVE_THRESHOLD
    now_ts = time_module.time()
    if excess <= 0:
        if cr_state.get('above_threshold_since') is not None:
            cr_state.pop('above_threshold_since', None)
            _save_cr_state(cr_state)
        return
    since = cr_state.get('above_threshold_since')
    if since is None:
        cr_state['above_threshold_since'] = now_ts
        _save_cr_state(cr_state)
        return
    if (now_ts - float(since)) < 24 * 3600:
        return  # still within the 24h grace period — leave it in trading
    cr_state['balance'] = float(CR_AUTO_SAVE_THRESHOLD)
    cr_state.pop('above_threshold_since', None)
    _save_cr_state(cr_state)
    sv_state = _load_savings_state()
    sv_ccy = sv_state.get('ccy', 'USD')
    sv_state = _accrue_savings(sv_state, sv_ccy, today_str)
    sv_state['balance'] = float(sv_state.get('balance', 0.0)) + excess
    _save_savings_state(sv_state)


def refill_trading_from_savings(target: float = CR_AUTO_SAVE_THRESHOLD, ccy: str = 'USD') -> float:
    """Pulls Cr back from savings into the trading balance, up to
    `target`. Only moves what savings can actually cover; never
    conjures Cr. Returns the amount actually moved (0 if the balance is
    already at/above target, or savings has nothing to give)."""
    current = get_cr_balance()
    if current >= target:
        return 0.0
    shortfall = target - current
    available = get_savings_balance(ccy)
    move = min(shortfall, available)
    if move <= 0:
        return 0.0
    withdraw_from_savings(move, ccy)
    return move


def refill_trading_unlimited(target: float = 10_000, ccy: str = 'USD') -> dict:
    """The paper-trading account's real refill faucet — unlimited, any
    number of times, any time the balance is under `target`. Pulls from
    savings FIRST (so savings actually gets used rather than sitting
    idle while a completely separate pool of free Cr tops things up
    around it), then conjures whatever's still short as a fresh top-up
    — this app's Cr was never real money to begin with (it's pegged
    1:1 to a notional practice balance), so there's no "savings" to
    protect it from being topped up freely. Returns {'from_savings',
    'from_faucet', 'total'}.

    The faucet portion is credited with bypass_lending_repay=True.
    Without that, apply_cr_delta() would treat the free top-up as
    "profit" and hand it straight to repay_lending_from_profit() —
    so anyone carrying a lending balance at or above `target` (up to
    and including someone maxed out at LENDING_MAX_CR) would solve
    the refill's math question, get told they were refilled, and
    still be stuck at Cr 0 with nothing to actually trade with. The
    faucet Cr always lands in the trading balance; lending still gets
    repaid the normal way out of real trading profit."""
    current = get_cr_balance()
    if current >= target:
        return {'from_savings': 0.0, 'from_faucet': 0.0, 'total': 0.0}
    from_savings = refill_trading_from_savings(target, ccy)
    remaining_gap = target - get_cr_balance()
    from_faucet = max(remaining_gap, 0.0)
    if from_faucet > 0:
        apply_cr_delta(from_faucet, bypass_lending_repay=True)
    return {'from_savings': from_savings, 'from_faucet': from_faucet,
            'total': from_savings + from_faucet}


# ---------------------------------------------------------------------------
# Fixed Deposit (FD) — "play FD", minimum 300,000 Cr, locked for a chosen
# tenure (1/3/6/12 months) at a flat rate per tenure (not tied to the
# central bank feed like savings — set FD_TENOR_RATES by hand).
#
# The FD principal itself stays locked until maturity or an early break —
# it is NEVER silently spent. Instead it works as loan COLLATERAL:
#
#   - If a buy exceeds trading + savings, the shortfall can be drawn as
#     OVERDRAFT against open FD principal (spend_cr below), up to the
#     sum of all active FD principal. The FD itself is untouched; this
#     just opens a debt balance secured by it.
#   - Every day, each active FD's own interest accrual is used to pay
#     down any outstanding overdraft FIRST — only interest left over
#     after the overdraft is fully repaid is credited to the trading
#     balance. FD principal itself never moves to cover overdraft
#     directly, only its daily interest does.
#   - Breaking an FD early downgrades ALL interest already earned during
#     its life down to the (current) savings rate — the FD-vs-savings
#     rate gap already paid out gets clawed back — then the principal is
#     released back to trading balance in full. This is an approximation:
#     the clawback uses TODAY's savings rate applied across the whole
#     holding period, since historical daily central-bank rates aren't
#     stored — it does not replay the exact rate on each historical day.
#   - Reaching maturity naturally releases the full principal (no
#     clawback — the full FD rate was legitimately earned).
# ---------------------------------------------------------------------------

FD_MIN_DEPOSIT = 600_000  # Cr — minimum to open any FD

# Per-currency, per-tenor spread (percentage points) added on top of that
# currency's central bank policy rate (get_cb_policy_rate) to form the FD
# rate — set by hand. The 3/6/12-month spreads are the 1-month spread
# doubled/tripled/quadrupled for MYR, SGD, JPY, KRW; USD and HKD instead
# use their own hand-set values at every tenor (no doubling relationship).
FD_RATE_SPREAD = {
    1:  {'MYR': 0.15, 'USD': 0.20, 'HKD': 0.18, 'SGD': 0.05, 'JPY': 0.01, 'KRW': 0.03},
    3:  {'MYR': 0.30, 'USD': 0.50, 'HKD': 0.58, 'SGD': 0.10, 'JPY': 0.02, 'KRW': 0.06},
    6:  {'MYR': 0.45, 'USD': 0.70, 'HKD': 0.88, 'SGD': 0.15, 'JPY': 0.03, 'KRW': 0.09},
    12: {'MYR': 0.60, 'USD': 0.90, 'HKD': 1.18, 'SGD': 0.20, 'JPY': 0.04, 'KRW': 0.12},
}

FD_TENOR_RATES = tuple(FD_RATE_SPREAD)  # months offered, e.g. (1, 3, 6, 12)

# AUD FD rates are hand-given final figures, not derived from a policy
# rate + spread like every other currency above (no live RBA fetcher is
# wired up — see CB_RATE_FALLBACK['AUD']). Checked first in get_fd_rate,
# ahead of the FD_RATE_SPREAD formula.
FD_RATE_FLAT_AUD = {1: 4.15, 3: 4.25, 6: 4.45, 12: 4.65}


def get_fd_rate(ccy: str, tenor_months: int) -> float:
    """Annual FD rate (%) for `ccy` at `tenor_months`. AUD uses the flat
    FD_RATE_FLAT_AUD table directly (exact hand-given figures). Every
    other currency uses that currency's current central bank policy
    rate + the hand-set FD_RATE_SPREAD for this tenor/currency, falling
    back to USD's spread if `ccy` has no spread configured for this
    tenor."""
    ccy = (ccy or 'USD').upper()
    if ccy == 'AUD':
        return FD_RATE_FLAT_AUD.get(tenor_months, FD_RATE_FLAT_AUD[1])
    spreads = FD_RATE_SPREAD.get(tenor_months, {})
    spread = spreads.get(ccy, spreads.get('USD', 0.0))
    return get_cb_policy_rate(ccy) + spread

CR_FD_FILE = os.path.join(_CACHE_DIR, 'cr_fd.json')


def _load_fd_state() -> dict:
    """{'fds': [{'id','principal','tenor_months','rate_pct','open_date',
    'maturity_date','last_accrual_date','status'}], 'overdraft': float}.
    status is 'active' | 'matured' | 'broken'."""
    import json as _j
    if not os.path.exists(CR_FD_FILE):
        return {'fds': [], 'overdraft': 0.0}
    try:
        with open(CR_FD_FILE, 'r') as f:
            state = _j.load(f)
        state.setdefault('fds', [])
        state.setdefault('overdraft', 0.0)
        return state
    except Exception:
        return {'fds': [], 'overdraft': 0.0}


def _save_fd_state(state: dict):
    import json as _j
    os.makedirs(_CACHE_DIR, exist_ok=True)
    try:
        with open(CR_FD_FILE, 'w') as f:
            _j.dump(state, f, default=_json_safe)
    except Exception as e:
        print(f'⚠️  cr_fd.json save failed: {e}')


def _fd_maturity_date(open_date_str: str, tenor_months: int) -> str:
    return (pd.Timestamp(open_date_str) + pd.DateOffset(months=tenor_months)).date().isoformat()


def open_fd(principal: float, tenor_months: int, ccy: str = 'USD') -> dict:
    """Opens a new FD, deducting `principal` from the trading balance.
    Rejects (no state changed) if principal < FD_MIN_DEPOSIT, the tenor
    isn't offered, or the trading balance can't cover it.
    Returns {'success', 'fd' (the new record) | 'reason', 'trading_balance'}."""
    if tenor_months not in FD_TENOR_RATES:
        return {'success': False, 'reason': f'tenor must be one of {sorted(FD_TENOR_RATES)} months',
                 'trading_balance': get_cr_balance()}
    if principal < FD_MIN_DEPOSIT:
        return {'success': False, 'reason': f'minimum FD deposit is {FD_MIN_DEPOSIT:,.0f} Cr',
                 'trading_balance': get_cr_balance()}
    trading = get_cr_balance()
    if principal > trading:
        return {'success': False, 'reason': 'insufficient trading balance',
                 'trading_balance': trading}

    apply_cr_delta(-principal)
    today_str = _cr_today_str()
    state = _load_fd_state()
    fd = {
        'id': (max((f['id'] for f in state['fds']), default=0) + 1),
        'principal': float(principal),
        'tenor_months': tenor_months,
        'ccy': (ccy or 'USD').upper(),
        'rate_pct': get_fd_rate(ccy, tenor_months),
        'open_date': today_str,
        'maturity_date': _fd_maturity_date(today_str, tenor_months),
        'last_accrual_date': today_str,   # interest starts accruing from tomorrow
        'status': 'active',
    }
    state['fds'].append(fd)
    _save_fd_state(state)
    return {'success': True, 'fd': fd, 'trading_balance': get_cr_balance()}


def _accrue_all_fds() -> dict:
    """Runs once per Malaysia-midnight rollover per FD: credits one day's
    interest on every active FD, routing it to pay down outstanding
    overdraft first (see module docstring above), with any leftover
    credited to the trading balance. Any FD whose maturity date has been
    reached is paid its final day, then matured out — principal released
    to trading in full, no clawback. Safe to call as often as needed;
    it's a no-op for anything already up to date today."""
    state = _load_fd_state()
    today_str = _cr_today_str()
    changed = False

    for fd in state['fds']:
        if fd['status'] != 'active':
            continue
        if fd['last_accrual_date'] == today_str:
            continue
        changed = True

        interest = fd['principal'] * (fd['rate_pct'] / 100.0) / 365.0
        overdraft = float(state.get('overdraft', 0.0))
        paydown = min(interest, overdraft)
        state['overdraft'] = max(overdraft - paydown, 0.0)
        leftover = interest - paydown
        if leftover > 0:
            apply_cr_delta(leftover)

        fd['last_accrual_date'] = today_str

        if today_str >= fd['maturity_date']:
            fd['status'] = 'matured'
            apply_cr_delta(fd['principal'])

    if changed:
        _save_fd_state(state)
    return state


def get_fd_list() -> list:
    """All FD records (any status), after running today's accrual."""
    return _accrue_all_fds()['fds']


def get_fd_credit_limit() -> float:
    """Total principal across active (unmatured, unbroken) FDs — the max
    overdraft that can currently be drawn against them."""
    state = _accrue_all_fds()
    return sum(f['principal'] for f in state['fds'] if f['status'] == 'active')


def get_overdraft_balance() -> float:
    """Current outstanding overdraft balance (after today's FD interest
    has had a chance to pay it down)."""
    return float(_accrue_all_fds().get('overdraft', 0.0))


def repay_overdraft(amount: float = None, ccy: str = 'USD') -> dict:
    """Manually pay the FD-secured overdraft down early, straight out of
    the trading balance — the one path that was missing: interest pays
    it down automatically day by day, and breaking an FD releases its
    principal to trading WITHOUT touching the overdraft (see break_fd /
    module docstring), so a broken FD's cash could sit in trading next
    to an untouched overdraft with no button to net the two against
    each other. This is that button.

    `amount` is in the DISPLAY currency `ccy`; converted to Cr the same
    way a buy/deposit is. None (or <= 0) means "pay as much as
    possible". Capped at min(current overdraft, current trading
    balance) — this only ever moves Cr that is already free in trading,
    never savings or FD principal, and never pays down more than is
    actually owed. Returns {'success', 'paid', 'overdraft_balance',
    'trading_balance', 'reason'?}."""
    state = _accrue_all_fds()
    owed = float(state.get('overdraft', 0.0))
    if owed <= 0.005:
        return {'success': False, 'reason': 'No outstanding overdraft.',
                'paid': 0.0, 'overdraft_balance': 0.0, 'trading_balance': get_cr_balance()}

    trading = get_cr_balance()
    if trading <= 0.005:
        return {'success': False, 'reason': 'Trading balance is Cr 0 — nothing free to pay it with.',
                'paid': 0.0, 'overdraft_balance': owed, 'trading_balance': trading}

    if amount is None or amount <= 0:
        requested_cr = min(owed, trading)
    else:
        requested_cr = underlying_to_cr(amount, ccy, direction='buy') if ccy != 'USD' else amount
        requested_cr = max(requested_cr, 0.0)

    paid = min(requested_cr, owed, trading)
    if paid <= 0.005:
        return {'success': False, 'reason': 'Nothing to pay.',
                'paid': 0.0, 'overdraft_balance': owed, 'trading_balance': trading}

    apply_cr_delta(-paid)
    state['overdraft'] = max(owed - paid, 0.0)
    _save_fd_state(state)
    return {'success': True, 'paid': paid, 'overdraft_balance': get_overdraft_balance(),
            'trading_balance': get_cr_balance()}


def break_fd(fd_id: int, ccy: str = 'USD') -> dict:
    """Breaks an active FD early: claws back the gap between what its FD
    rate already paid out and what the (current) savings rate would have
    paid over the same holding period, then releases the principal.

    The released principal pays down any outstanding overdraft FIRST,
    same as daily FD interest already does — this FD's own principal is
    exactly what was securing that overdraft's credit line
    (get_fd_credit_limit() sums active-FD principal), so once the FD is
    broken it isn't backing anything any more and the debt against it
    should actually shrink, not just sit there while trading balance
    goes up next to it untouched. Only whatever's left after that lands
    in trading. See module docstring for the same-day-rate caveat.
    Returns {'success', 'reason'?, 'principal_released'?, 'clawback'?,
    'overdraft_paid'?, 'trading_balance'}."""
    state = _accrue_all_fds()
    fd = next((f for f in state['fds'] if f['id'] == fd_id), None)
    if fd is None:
        return {'success': False, 'reason': 'no such FD', 'trading_balance': get_cr_balance()}
    if fd['status'] != 'active':
        return {'success': False, 'reason': f"FD is already {fd['status']}",
                 'trading_balance': get_cr_balance()}

    days_held = max((pd.Timestamp(_cr_today_str()) - pd.Timestamp(fd['open_date'])).days, 0)
    savings_rate_pct = max(get_cb_policy_rate(ccy) - CR_SAVINGS_RATE_DEDUCTION, 0.0)
    paid_interest = fd['principal'] * (fd['rate_pct'] / 100.0) / 365.0 * days_held
    correct_interest = fd['principal'] * (savings_rate_pct / 100.0) / 365.0 * days_held
    clawback = max(paid_interest - correct_interest, 0.0)

    if clawback > 0:
        apply_cr_delta(-clawback)

    released = fd['principal']
    owed = float(state.get('overdraft', 0.0))
    overdraft_paid = min(released, owed)
    if overdraft_paid > 0:
        state['overdraft'] = max(owed - overdraft_paid, 0.0)
    remainder = released - overdraft_paid
    if remainder > 0:
        apply_cr_delta(remainder)

    fd['status'] = 'broken'
    _save_fd_state(state)
    return {'success': True, 'principal_released': released, 'clawback': clawback,
             'overdraft_paid': overdraft_paid, 'trading_balance': get_cr_balance()}


# ---------------------------------------------------------------------------
# PTS — Prediction Market. Free-play, pari-mutuel, binary (YES/NO) markets
# settled against real closing prices already flowing through the index
# engine — no separate price feed, no house pricing model. Two universes:
#   'index' — a headline MYIPO+/DLC index from all_frames
#   'stock' — a non-MYIPO+ constituent (Quant1 == 0 in df_listed, the
#             candidate pool flagged at build_indices() time — see the
#             "self_df_listed" comment there)
# Every market asks the same shape of question: "will <label> close ABOVE
# <ref_price> (its price when the market opened) on/after <resolve_date>?"
# Bets are staked in Cr via apply_cr_delta (same balance as trading/FD/
# lending). On resolution the losing side's pool is split across the
# winning side pro-rata to stake (classic pari-mutuel) — no house edge,
# since this is the same free-play Cr as the rest of the app.
# ---------------------------------------------------------------------------

CR_PTS_FILE          = os.path.join(_CACHE_DIR, 'cr_pts.json')
PTS_MARKET_TARGET    = 6          # how many open markets pts_generate_markets() tries to maintain
PTS_INDEX_HORIZON_D  = 3          # calendar days ahead for an index market's resolve date
PTS_STOCK_HORIZON_D  = 5          # calendar days ahead for a stock market's resolve date
PTS_MIN_STAKE        = 100        # Cr
PTS_MAX_STAKE        = 100_000    # Cr — well under FD_MIN_DEPOSIT, keeps this a side game
# Headline indices eligible to become 'index' markets — kept short and
# recognizable rather than spamming every Top-N/thematic label.
PTS_INDEX_CANDIDATES = ['MYIPO+ Top 10', 'MYIPO+ Top 20', 'MYIPO+ Top 50', 'MYIPO+ Top 100',
                         'MYIPO+ Top 200', 'MYIPO+ Top 10 PW', 'FBM KLCI']


def _pts_today_str() -> str:
    return (datetime.now(MALAYSIA_TZ) if MALAYSIA_TZ else datetime.now()).date().isoformat()


def _load_pts_state() -> dict:
    """{'next_id': int, 'markets': [{'id','kind','universe','label',
    'question','ref_price','ref_date','resolve_date','status'
    ('open'|'resolved'),'outcome'(None|'YES'|'NO'),'settle_price',
    'yes_pool','no_pool','bets':[{'side','stake','placed_date','payout'}]}]}."""
    import json as _j
    if not os.path.exists(CR_PTS_FILE):
        return {'next_id': 1, 'markets': []}
    try:
        with open(CR_PTS_FILE, 'r') as f:
            state = _j.load(f)
        state.setdefault('next_id', 1)
        state.setdefault('markets', [])
        return state
    except Exception:
        return {'next_id': 1, 'markets': []}


def _save_pts_state(state: dict):
    import json as _j
    os.makedirs(_CACHE_DIR, exist_ok=True)
    try:
        with open(CR_PTS_FILE, 'w') as f:
            _j.dump(state, f, default=_json_safe)
    except Exception as e:
        print(f'⚠️  cr_pts.json save failed: {e}')


def _pts_snap_price(price_series: 'pd.Series', target_date_str: str):
    """Latest available (date, price) pair at or before target_date_str —
    same snap-backward convention used elsewhere in the index engine
    (weekends/holidays fall back to the prior trading day). Returns
    (None, None) if target_date_str is still in the future relative to
    the data on hand."""
    idx = price_series.index
    target = pd.Timestamp(target_date_str)
    pos = idx.searchsorted(target, side='right') - 1
    if pos < 0:
        return None, None
    snapped = idx[pos]
    if snapped < target and pos == len(idx) - 1:
        # the series simply hasn't reached target_date_str yet
        return None, None
    return snapped, float(price_series.iloc[pos])


def pts_generate_markets(app) -> list:
    """Top up open markets to PTS_MARKET_TARGET using whatever indices/
    stocks are currently loaded on `app` (all_frames / df_listed /
    stock_price_df). Silently generates fewer than target if not enough
    fresh candidates are available (e.g. right after a cold start).
    Returns the full current market list."""
    state = _load_pts_state()
    open_markets = [m for m in state['markets'] if m['status'] == 'open']
    already_labelled = {m['label'] for m in open_markets}
    today = _pts_today_str()
    needed = PTS_MARKET_TARGET - len(open_markets)
    if needed <= 0:
        return state['markets']

    all_frames = getattr(app, 'all_frames', {}) or {}
    df_listed  = getattr(app, 'df_listed', None)
    price_df   = getattr(app, 'stock_price_df', None)

    def _add_market(kind, universe, label, question, ref_date, ref_price, horizon_days):
        nonlocal needed
        resolve_date = (pd.Timestamp(ref_date) + pd.Timedelta(days=horizon_days)).date().isoformat()
        state['markets'].append({
            'id': state['next_id'], 'kind': kind, 'universe': universe, 'label': label,
            'question': question, 'ref_price': round(float(ref_price), 4), 'ref_date': ref_date,
            'resolve_date': resolve_date, 'status': 'open', 'outcome': None, 'settle_price': None,
            'yes_pool': 0.0, 'no_pool': 0.0, 'bets': [],
        })
        state['next_id'] += 1
        already_labelled.add(label)
        needed -= 1

    # ── index candidates ────────────────────────────────────────────────
    for label in PTS_INDEX_CANDIDATES:
        if needed <= 0:
            break
        if label in already_labelled or label not in all_frames:
            continue
        frame = all_frames[label]
        if label not in frame.columns or frame.empty:
            continue
        ref_price = float(frame[label].iloc[-1])
        if not (ref_price > 0):
            continue
        ref_date = frame.index[-1].date().isoformat()
        question = (f'Will {label} close ABOVE {ref_price:,.2f} on or after '
                    f'{(pd.Timestamp(ref_date) + pd.Timedelta(days=PTS_INDEX_HORIZON_D)).strftime("%d %b %Y")}?')
        _add_market('direction', 'index', label, question, ref_date, ref_price, PTS_INDEX_HORIZON_D)

    # ── stock candidates — non-MYIPO+ names (Quant1 == 0), per the
    #    candidate pool already flagged at build_indices() time ─────────
    if needed > 0 and df_listed is not None and not df_listed.empty and price_df is not None \
            and not price_df.empty:
        try:
            pool = df_listed[df_listed['Quant1'] == 0]['Symbol'].dropna().unique().tolist()
        except Exception:
            pool = []
        random.shuffle(pool)
        name_lookup = {}
        try:
            name_lookup = df_listed.set_index('Symbol')['Name'].fillna('').to_dict()
        except Exception:
            pass
        for symbol in pool:
            if needed <= 0:
                break
            label = symbol
            if label in already_labelled or symbol not in price_df.columns:
                continue
            series = price_df[symbol].dropna()
            if series.empty:
                continue
            ref_price = float(series.iloc[-1])
            if not (ref_price > 0):
                continue
            ref_date = series.index[-1].date().isoformat()
            disp_name = name_lookup.get(symbol, '')
            tag = f'{symbol} ({disp_name})' if disp_name else symbol
            question = (f'Will {tag} close ABOVE {ref_price:,.3f} on or after '
                        f'{(pd.Timestamp(ref_date) + pd.Timedelta(days=PTS_STOCK_HORIZON_D)).strftime("%d %b %Y")}?')
            _add_market('direction', 'stock', label, question, ref_date, ref_price, PTS_STOCK_HORIZON_D)

    _save_pts_state(state)
    return state['markets']


def pts_resolve_due_markets(app) -> list:
    """Resolve every open market whose resolve_date has real price data
    available now, paying out pari-mutuel winnings via apply_cr_delta.
    Returns the list of markets resolved this call (for a UI toast)."""
    state = _load_pts_state()
    all_frames = getattr(app, 'all_frames', {}) or {}
    price_df   = getattr(app, 'stock_price_df', None)
    resolved_now = []

    for m in state['markets']:
        if m['status'] != 'open':
            continue
        if m['universe'] == 'index':
            frame = all_frames.get(m['label'])
            series = frame[m['label']] if (frame is not None and m['label'] in frame.columns) else None
        else:
            series = price_df[m['label']] if (price_df is not None and m['label'] in price_df.columns) else None
        if series is None or series.dropna().empty:
            continue
        snapped_date, price = _pts_snap_price(series.dropna(), m['resolve_date'])
        if snapped_date is None:
            continue  # data hasn't reached the resolve date yet

        m['status']       = 'resolved'
        m['settle_price'] = round(price, 4)
        m['outcome']      = 'YES' if price > m['ref_price'] else 'NO'
        winners, losers = (m['yes_pool'], m['no_pool']) if m['outcome'] == 'YES' \
            else (m['no_pool'], m['yes_pool'])

        for bet in m['bets']:
            won = (bet['side'] == m['outcome'])
            if won:
                share = (bet['stake'] / winners) if winners > 0 else 0.0
                payout = bet['stake'] + share * losers
                bet['payout'] = round(payout, 2)
                apply_cr_delta(payout)
            else:
                bet['payout'] = 0.0
        resolved_now.append(m)

    if resolved_now:
        _save_pts_state(state)
    return resolved_now


def pts_get_markets() -> list:
    """All markets, open first (soonest resolve_date first), then
    resolved (most recent first) — the shape the GUI list expects."""
    state = _load_pts_state()
    open_m = sorted((m for m in state['markets'] if m['status'] == 'open'),
                     key=lambda m: m['resolve_date'])
    resolved_m = sorted((m for m in state['markets'] if m['status'] != 'open'),
                         key=lambda m: m['resolve_date'], reverse=True)
    return open_m + resolved_m


def pts_place_bet(market_id: int, side: str, stake: float) -> dict:
    """Stake `stake` Cr on `side` ('YES'/'NO') of an open market. Debits
    the Cr balance immediately via apply_cr_delta (same balance FD/
    lending/trading share) — a market that never resolves in the
    player's favor loses the stake, exactly like a real prediction
    market or the index's own paper-trading positions."""
    side = side.upper()
    if side not in ('YES', 'NO'):
        return {'success': False, 'reason': "side must be 'YES' or 'NO'"}
    try:
        stake = float(stake)
    except (TypeError, ValueError):
        return {'success': False, 'reason': 'invalid stake'}
    if stake < PTS_MIN_STAKE:
        return {'success': False, 'reason': f'minimum stake is {PTS_MIN_STAKE:,.0f} Cr'}
    if stake > PTS_MAX_STAKE:
        return {'success': False, 'reason': f'maximum stake is {PTS_MAX_STAKE:,.0f} Cr'}
    if stake > get_cr_balance():
        return {'success': False, 'reason': 'insufficient Cr balance', 'trading_balance': get_cr_balance()}

    state = _load_pts_state()
    market = next((m for m in state['markets'] if m['id'] == market_id and m['status'] == 'open'), None)
    if market is None:
        return {'success': False, 'reason': 'market not open (or no longer exists)'}

    apply_cr_delta(-stake)
    market['bets'].append({'side': side, 'stake': stake, 'placed_date': _pts_today_str(), 'payout': None})
    market[f'{side.lower()}_pool'] += stake
    _save_pts_state(state)
    return {'success': True, 'market': market, 'trading_balance': get_cr_balance()}


# ---------------------------------------------------------------------------
# Lending Mode — borrow Cr as trading leverage, secured against total
# assets (trading + savings + active FD principal), capped at
# LENDING_MAX_CR (1,000,000 Cr) outstanding at any time.
#
# Status flow:
#   'none'    -> nothing borrowed
#   'lending' -> principal outstanding, accruing daily interest
#   'paid'    -> the borrowed principal has been fully cleared by profit
#                (see repay_lending_from_profit below); stays 'paid' as a
#                record until a new lending is opened, which resets it to
#                'lending' again.
#
# Repayment is profit-driven, not manual: every positive Cr delta applied
# via apply_cr_delta() is intercepted by repay_lending_from_profit() BEFORE
# it reaches the trading balance. It pays down outstanding lending
# principal + accrued interest first; only the leftover (if the lending is
# already 'paid', or fully cleared by this same profit) continues on to
# the trading balance / auto-sweep-to-savings as normal.
# ---------------------------------------------------------------------------

CR_LENDING_FILE = os.path.join(_CACHE_DIR, 'cr_lending.json')
LENDING_MAX_CR = 1_000_000  # informational reference only now — no rate
                             # tiering or hard rejection is keyed off this
                             # anymore, see _accrue_lending/open_lending.
LENDING_RATE_PA = 6.0       # flat annual borrow rate, % (hand-set, like FD spreads) —
                             # applies to the WHOLE outstanding balance, any size.


def _load_lending_state() -> dict:
    """{'principal': float, 'open_date': str|None, 'last_accrual_date':
    str|None, 'status': 'none'|'lending'|'paid'}."""
    import json as _j
    default = {'principal': 0.0, 'open_date': None,
               'last_accrual_date': None, 'status': 'none'}
    if not os.path.exists(CR_LENDING_FILE):
        return default
    try:
        with open(CR_LENDING_FILE, 'r') as f:
            state = _j.load(f)
        for k, v in default.items():
            state.setdefault(k, v)
        return state
    except Exception:
        return default


def _save_lending_state(state: dict):
    import json as _j
    os.makedirs(_CACHE_DIR, exist_ok=True)
    try:
        with open(CR_LENDING_FILE, 'w') as f:
            _j.dump(state, f, default=_json_safe)
    except Exception as e:
        print(f'⚠️  cr_lending.json save failed: {e}')


def _accrue_lending(state: dict, today_str: str, ccy: str = 'USD', app=None) -> dict:
    """One day's interest on outstanding lending principal for each day
    rolled over since last accrual. No-op if nothing outstanding or
    already accrued today. Flat LENDING_RATE_PA on the WHOLE principal,
    regardless of size — no tiering. (ccy/app kept as accepted params,
    unused now, so existing call sites that pass them don't break.)"""
    if state.get('status') == 'lending' and state.get('principal', 0.0) > 0:
        if state.get('last_accrual_date') != today_str:
            daily_rate = (LENDING_RATE_PA / 100.0) / 365.0
            state['principal'] = float(state['principal']) * (1 + daily_rate)
    state['last_accrual_date'] = today_str
    return state


def get_wealth_pack_display_value(app, pack: dict, target_ccy: str, pack_name: str = None) -> float:
    """Same holdings as get_wealth_pack_value_cr, but converted straight
    into `target_ccy` — skipping the Cr peg's USD-leg spread entirely for
    any holding whose OWN currency already matches target_ccy (see
    convert_native_ccy). get_wealth_pack_value_cr stays USD/Cr-pegged
    on purpose (it's the shared accounting figure used by Total Assets,
    Lending collateral, etc.); this one exists specifically for the
    Wealth Management page's user-facing Cash Value line, where paying
    a real FX spread to convert MYR into MYR makes no sense."""
    target_ccy = (target_ccy or 'USD').upper()
    holdings = pack.get('holdings', [])
    total = 0.0
    if holdings:
        units = _compute_pack_current_units(app, pack, pack_name=pack_name)
        for t, u in units.items():
            if not (u > 0):
                continue
            if t == WEALTH_CASH_TICKER:
                total += convert_native_ccy(u, 'USD', target_ccy)  # CASH is always 1.0 USD/unit
                continue
            px_last = _wealth_last_price(app, t, pack.get('created') or START_DATE_STR)
            if not (px_last > 0):
                continue
            ccy = _ccy_for_label(t)
            total += convert_native_ccy(u * px_last, ccy, target_ccy)
    unrouted = pack.get('unrouted_dividends', 0)
    unrouted = float(unrouted) if unrouted is not None else 0.0
    if math.isfinite(unrouted):
        # unrouted_dividends is stored in Cr (already pegged at credit
        # time — see settle_wealth_pack_dividends), so unlike a live
        # holding there's no native-currency figure left to compare
        # 1:1 against; the Cr->display leg is unavoidable here.
        total += convert_cr_to_ccy(unrouted, target_ccy)['display_amount']
    return total


def get_wealth_pack_value_cr(app, pack: dict, pack_name: str = None) -> float:
    """Current liquidation value (in Cr) of a SINGLE Wealth Pack — same
    units-held × last-price + unrouted-dividends calculation
    get_wealth_packs_total_value() sums across every pack, pulled out
    standalone so a pack can be cashed out individually (e.g. on
    deletion — see WealthManagementPage._delete_pack()) without
    re-deriving every other pack's value too."""
    holdings = pack.get('holdings', [])
    total_cr = 0.0
    if holdings:
        units = _compute_pack_current_units(app, pack, pack_name=pack_name)
        for t, u in units.items():
            if not (u > 0):
                continue
            if t == WEALTH_CASH_TICKER:
                total_cr += usd_to_cr(u)
                continue
            px_last = _wealth_last_price(app, t, pack.get('created') or START_DATE_STR)
            if not (px_last > 0):
                continue
            ccy = _ccy_for_label(t)
            total_cr += underlying_to_cr(u * px_last, ccy, direction='sell')
    unrouted = pack.get('unrouted_dividends', 0)
    unrouted = float(unrouted) if unrouted is not None else 0.0
    if math.isfinite(unrouted):
        total_cr += unrouted
    return total_cr


def get_wealth_packs_total_value(app=None, force: bool = False) -> float:
    """Current market value of every Wealth Pack — units-held × last
    price per holding (via _compute_pack_current_units, the same
    replay used for each pack's own chart) plus each pack's unrouted
    dividend cash, all converted to Cr. Rolled into get_total_assets()
    below so a pack's actual holdings count as part of overall net
    worth, not just money still sitting in Trading/Savings/FDs.
    Cached for 60s (cache_get_live/cache_set_live) since this replays
    full price history per pack and get_total_assets() is called from
    latency-sensitive paths (e.g. a lending-collateral check).

    `force=True` skips that 60s cache (the Wealth page's own summary
    card passes it) — and every pack mutation (create / edit / deposit /
    withdraw / delete / top-up) now drops the cache via
    _save_wealth_packs(), so a brand-new pack can never be missing from
    the total while its deposit is already counted in Total Deposited
    (that mismatch was what showed up as a phantom loss equal to the
    new pack's whole deposit)."""
    if not force:
        cached = cache_get_live('wealth_packs_total_value', ttl=60)
        if cached is not None and math.isfinite(float(cached)):
            return float(cached)
    packs = _load_wealth_packs()
    total_cr = 0.0
    for name, pack in packs.items():
        # NOTE: do NOT skip packs with empty 'holdings' — a merged pack
        # (see WealthManagementPage._do_merge_packs) can legitimately
        # have an empty holdings/weight table while still holding real
        # value via pack['seed_units']. Skipping here used to make such
        # a pack's ENTIRE value vanish from Total Assets / lending
        # collateral, even though the Wealth page itself displayed it
        # fine (_compute_pack_current_units already handles this case
        # correctly on its own — no need to gate the call on holdings).
        units = _compute_pack_current_units(app, pack, pack_name=name)
        if units:
            for t, u in units.items():
                # Iterate over `units` itself (not just `holdings`) so
                # the implicit Cash (Cr) remainder (see
                # _wealth_weights_with_cash) counts toward the pack's
                # value too — it's real money sitting in the pack even
                # though it isn't one of the pack's named holdings.
                if not (u > 0):
                    continue
                if t == WEALTH_CASH_TICKER:
                    total_cr += usd_to_cr(u)   # CASH is always flat 1.0 USD/unit
                    continue
                px_last = _wealth_last_price(app, t, pack.get('created') or START_DATE_STR)
                if not (px_last > 0):
                    continue
                ccy = _ccy_for_label(t)
                total_cr += underlying_to_cr(u * px_last, ccy, direction='sell')
        unrouted = pack.get('unrouted_dividends', 0)
        unrouted = float(unrouted) if unrouted is not None else 0.0
        if math.isfinite(unrouted):
            total_cr += unrouted
    cache_set_live('wealth_packs_total_value', total_cr)
    return total_cr


def get_total_assets(ccy: str = 'USD', app=None) -> float:
    """Trading + savings + active FD principal + Wealth Pack holdings
    (market value + unrouted dividends) — the full collateral/net-worth
    base a lending draw is measured against."""
    trading = get_cr_balance()
    savings = get_savings_balance(ccy)
    fd_principal = sum(f['principal'] for f in get_fd_list() if f['status'] == 'active')
    wealth = get_wealth_packs_total_value(app)
    return trading + savings + fd_principal + wealth


def get_lending_balance(app=None) -> float:
    """Current outstanding lending principal (after today's accrual)."""
    state = _load_lending_state()
    today_str = _cr_today_str()
    before = (state.get('principal'), state.get('last_accrual_date'))
    state = _accrue_lending(state, today_str, app=app)
    if (state['principal'], state['last_accrual_date']) != before:
        _save_lending_state(state)
    return float(state.get('principal', 0.0)) if state.get('status') == 'lending' else 0.0


def get_lending_status() -> str:
    return _load_lending_state().get('status', 'none')


def open_lending(amount: float, ccy: str = 'USD', app=None) -> dict:
    """Borrows `amount` Cr as leverage into the trading balance. Rejects
    (no state changed) if amount <= 0, or if it exceeds current total
    assets (trading + savings + active FD principal) used as collateral.
    No hard cap at LENDING_MAX_CR — outstanding principal accrues a flat
    LENDING_RATE_PA no matter how large it gets (see _accrue_lending).
    Returns {'success', 'reason'?, 'lending_balance', 'trading_balance'}."""
    if amount <= 0:
        return {'success': False, 'reason': 'amount must be positive',
                 'lending_balance': get_lending_balance(app), 'trading_balance': get_cr_balance()}

    state = _load_lending_state()
    today_str = _cr_today_str()
    state = _accrue_lending(state, today_str, ccy=ccy, app=app)
    outstanding = float(state.get('principal', 0.0)) if state.get('status') == 'lending' else 0.0

    # No hard rejection at LENDING_MAX_CR — a draw that pushes outstanding
    # principal past it is allowed; it all still accrues at the same flat
    # LENDING_RATE_PA (see _accrue_lending). Collateral is the real limit.

    collateral = get_total_assets(ccy, app)
    if amount > collateral:
        return {'success': False,
                 'reason': f'exceeds total assets available as collateral ({collateral:,.0f} Cr)',
                 'lending_balance': outstanding, 'trading_balance': get_cr_balance()}

    state['principal'] = outstanding + amount
    state['status'] = 'lending'
    if not state.get('open_date'):
        state['open_date'] = today_str
    state['last_accrual_date'] = today_str
    _save_lending_state(state)

    apply_cr_delta(amount, from_lending_draw=True)  # credited as leverage, not profit
    return {'success': True, 'lending_balance': get_lending_balance(app),
             'trading_balance': get_cr_balance()}


def repay_lending_from_profit(profit: float) -> float:
    """Given a positive Cr amount about to be credited (a realized gain),
    pays down outstanding lending principal + accrued interest first.
    Returns the leftover amount (>=0) that should continue on to the
    trading balance / auto-sweep-to-savings as normal. A non-positive
    `profit`, or no outstanding lending, passes the full amount through
    unchanged. Flips status to 'paid' the moment principal hits 0."""
    if profit <= 0:
        return profit
    state = _load_lending_state()
    today_str = _cr_today_str()
    state = _accrue_lending(state, today_str)
    outstanding = float(state.get('principal', 0.0)) if state.get('status') == 'lending' else 0.0
    if outstanding <= 0:
        _save_lending_state(state)
        return profit

    paydown = min(profit, outstanding)
    state['principal'] = outstanding - paydown
    if state['principal'] <= 1e-9:
        state['principal'] = 0.0
        state['status'] = 'paid'
    _save_lending_state(state)
    return profit - paydown  # leftover flows on to trading/savings as usual


def repay_lending_manual(amount: float, ccy: str = 'USD') -> dict:
    """Manually pay down outstanding lending principal on demand, straight
    out of the trading balance — separate from repay_lending_from_profit(),
    which only fires automatically off realized trading profit. This lets
    someone clear (or chip away at) a lending balance directly, e.g. right
    after a fresh 10,000 Cr refill, instead of waiting to trade a profit.
    Rejects (no state changed) if amount <= 0, there's nothing outstanding,
    or the trading balance can't cover it. Returns {'success', 'reason'?,
    'lending_balance', 'trading_balance'}."""
    if amount <= 0:
        return {'success': False, 'reason': 'amount must be positive',
                 'lending_balance': get_lending_balance(), 'trading_balance': get_cr_balance()}

    state = _load_lending_state()
    today_str = _cr_today_str()
    state = _accrue_lending(state, today_str)
    outstanding = float(state.get('principal', 0.0)) if state.get('status') == 'lending' else 0.0

    if outstanding <= 0:
        _save_lending_state(state)
        return {'success': False, 'reason': 'no outstanding lending to repay',
                 'lending_balance': 0.0, 'trading_balance': get_cr_balance()}

    trading_balance = get_cr_balance()
    if amount > trading_balance:
        return {'success': False,
                 'reason': f'exceeds trading balance available ({trading_balance:,.2f} Cr)',
                 'lending_balance': outstanding, 'trading_balance': trading_balance}

    paydown = min(amount, outstanding)
    state['principal'] = outstanding - paydown
    if state['principal'] <= 1e-9:
        state['principal'] = 0.0
        state['status'] = 'paid'
    _save_lending_state(state)

    apply_cr_delta(-paydown, bypass_lending_repay=True)  # a manual repayment, not new profit
    return {'success': True, 'repaid': paydown, 'lending_balance': get_lending_balance(),
             'trading_balance': get_cr_balance()}


# ─── Share Lending — lending out a full-lot STOCK position for daily
# interest. Unrelated to the Cr-borrowing "Lending Mode" above (that's
# margin debt owed BY the user; this is the user lending shares OUT
# and earning interest FROM it) — kept as its own small file/state so
# the two aren't confused. ───────────────────────────────────────────
CR_STOCK_LENDING_FILE = os.path.join(_CACHE_DIR, 'cr_stock_lending.json')
STOCK_LENDING_DAILY_RATE_PCT = 0.01     # flat daily rate, % of the Cr value locked in at lend time
STOCK_LENDING_LOT_SIZE = 100            # a full board lot — odd lots aren't eligible
STOCK_LENDING_MIN_CR = 100_000.0
STOCK_LENDING_MAX_CR = 5_000_000.0


def _load_stock_lending_state() -> dict:
    import json as _j
    if not os.path.exists(CR_STOCK_LENDING_FILE):
        return {'next_id': 1, 'lendings': []}
    try:
        with open(CR_STOCK_LENDING_FILE, 'r') as f:
            state = _j.load(f)
    except Exception:
        return {'next_id': 1, 'lendings': []}
    state.setdefault('next_id', 1)
    state.setdefault('lendings', [])
    return state


def _save_stock_lending_state(state: dict):
    import json as _j
    os.makedirs(_CACHE_DIR, exist_ok=True)
    try:
        with open(CR_STOCK_LENDING_FILE, 'w') as f:
            _j.dump(state, f, default=_json_safe)
    except Exception:
        pass


def stock_lending_eligible(qty: float, value_cr: float) -> bool:
    """A position can only be lent out for interest when it's a whole
    number of full board lots (STOCK_LENDING_LOT_SIZE units each — no
    odd lots) AND its current market value falls inside the
    STOCK_LENDING_MIN_CR..STOCK_LENDING_MAX_CR band. Callers pass the
    already-floored LENDABLE portion of a holding (see
    stock_lending_lot_split) — a 350-unit position isn't rejected
    outright just because it isn't itself an exact multiple of 100;
    its 300-unit lendable slice is what gets checked here, with the
    50-unit odd lot simply excluded rather than blocking the whole
    position from earning anything."""
    return (qty > 0 and qty % STOCK_LENDING_LOT_SIZE == 0
            and STOCK_LENDING_MIN_CR <= value_cr <= STOCK_LENDING_MAX_CR)


def stock_lending_lot_split(qty: float) -> tuple:
    """Splits a held quantity into (lendable_qty, odd_qty): lendable_qty
    is the largest whole multiple of STOCK_LENDING_LOT_SIZE not
    exceeding qty (0 if fewer than one full lot is held), odd_qty is
    whatever's left over (0-99 units) — never eligible for lending,
    but still a normal, fully-counted part of the position everywhere
    else in the app (Units Held, pack value, net worth, collateral).
    Fractional qty (e.g. a partial-share fill) floors its odd_qty down
    to a whole-unit remainder same as Bursa's own odd-lot handling."""
    full_lots = int(qty // STOCK_LENDING_LOT_SIZE)
    lendable_qty = full_lots * STOCK_LENDING_LOT_SIZE
    odd_qty = qty - lendable_qty
    return lendable_qty, odd_qty


def _accrue_stock_lendings(state: dict) -> dict:
    """Flat STOCK_LENDING_DAILY_RATE_PCT/day on each active lending's
    `value_cr` — the value LOCKED IN at the moment it was lent out, same
    principle as an FD's principal not moving once opened, so the
    interest schedule doesn't chase the position's daily mark-to-market
    swings. Idempotent per calendar day, same accrue-once pattern as
    _accrue_lending/_accrue_all_fds."""
    today = _cr_today_str()
    changed = False
    for L in state['lendings']:
        if L.get('status') != 'active':
            continue
        last = L.get('accrued_date', L.get('start_date'))
        days = max((pd.Timestamp(today) - pd.Timestamp(last)).days, 0)
        if days <= 0:
            continue
        interest = L['value_cr'] * (STOCK_LENDING_DAILY_RATE_PCT / 100.0) * days
        if interest > 0:
            apply_cr_delta(interest, bypass_lending_repay=True)  # lending income, not trading profit
            L['accrued_interest'] = L.get('accrued_interest', 0.0) + interest
        L['accrued_date'] = today
        changed = True
    if changed:
        _save_stock_lending_state(state)
    return state


def get_stock_lendings() -> list:
    """Every Share Lending record, interest accrued up to today."""
    return _accrue_stock_lendings(_load_stock_lending_state())['lendings']


def open_stock_lending(ticker: str, qty: float, value_cr: float) -> dict:
    """Lends out `qty` units of `ticker` (must pass stock_lending_eligible)
    at its current `value_cr` for STOCK_LENDING_DAILY_RATE_PCT/day. The
    shares themselves aren't moved or sold anywhere in this app's model
    — this only tracks the lending agreement and its daily interest;
    the position keeps showing in Holdings exactly as before. Only one
    active lending per ticker at a time. Returns {'success', 'reason'?,
    'id'?}."""
    if not stock_lending_eligible(qty, value_cr):
        return {'success': False,
                 'reason': (f'Needs a whole multiple of {STOCK_LENDING_LOT_SIZE} units and a value '
                            f'between Cr {STOCK_LENDING_MIN_CR:,.0f} and Cr {STOCK_LENDING_MAX_CR:,.0f} '
                            f'(this position is {qty:g} units, Cr {value_cr:,.2f}).')}
    state = _load_stock_lending_state()
    if any(L['ticker'] == ticker and L.get('status') == 'active' for L in state['lendings']):
        return {'success': False, 'reason': f'{ticker} already has an active Share Lending agreement.'}
    lend_id = state['next_id']
    state['next_id'] += 1
    today = _cr_today_str()
    state['lendings'].append({
        'id': lend_id, 'ticker': ticker, 'qty': qty, 'value_cr': value_cr,
        'start_date': today, 'accrued_date': today, 'accrued_interest': 0.0,
        'status': 'active',
    })
    _save_stock_lending_state(state)
    return {'success': True, 'id': lend_id}


def recall_stock_lending(lend_id: int) -> dict:
    """Ends an active Share Lending agreement — no penalty, no clawback
    (unlike an FD's Break Early); whatever interest already accrued
    stays credited. Returns {'success', 'reason'?, 'total_interest'?}."""
    state = _accrue_stock_lendings(_load_stock_lending_state())
    L = next((x for x in state['lendings'] if x['id'] == lend_id), None)
    if L is None or L.get('status') != 'active':
        return {'success': False, 'reason': 'No such active Share Lending agreement.'}
    L['status'] = 'recalled'
    _save_stock_lending_state(state)
    return {'success': True, 'total_interest': L.get('accrued_interest', 0.0)}


def spend_cr(amount: float, ccy: str = 'USD') -> dict:
    """Auto-deduct for a buy, in three tiers:
      1) trading balance
      2) savings (today's interest accrued first)
      3) overdraft secured by active FD principal (FD itself untouched —
         see the FD module docstring above for how that debt gets repaid)
    Rejects the whole spend — no state changed at all — if all three
    together still can't cover it, so a buy never partially executes.
    Returns {'success', 'from_trading', 'from_savings', 'from_overdraft',
    'shortfall', 'trading_balance', 'savings_balance', 'overdraft_balance'}."""
    if amount <= 0:
        raise ValueError('amount must be positive')

    trading = get_cr_balance()
    savings = get_savings_balance(ccy)
    fd_state = _accrue_all_fds()
    credit_limit = sum(f['principal'] for f in fd_state['fds'] if f['status'] == 'active')
    available_credit = max(credit_limit - float(fd_state.get('overdraft', 0.0)), 0.0)
    total = trading + savings + available_credit

    if amount > total:
        return {'success': False, 'from_trading': 0.0, 'from_savings': 0.0,
                 'from_overdraft': 0.0, 'shortfall': amount - total,
                 'trading_balance': trading, 'savings_balance': savings,
                 'overdraft_balance': float(fd_state.get('overdraft', 0.0))}

    from_trading = min(amount, trading)
    remaining = amount - from_trading
    from_savings = min(remaining, savings)
    remaining -= from_savings
    from_overdraft = remaining  # already proven <= available_credit above

    apply_cr_delta(-from_trading)
    if from_savings > 0:
        s_state = _load_savings_state()
        s_state = _accrue_savings(s_state, ccy, _cr_today_str())
        s_state['balance'] = max(float(s_state.get('balance', 0.0)) - from_savings, 0.0)
        _save_savings_state(s_state)
    if from_overdraft > 0:
        fd_state['overdraft'] = float(fd_state.get('overdraft', 0.0)) + from_overdraft
        _save_fd_state(fd_state)

    return {'success': True, 'from_trading': from_trading, 'from_savings': from_savings,
             'from_overdraft': from_overdraft, 'shortfall': 0.0,
             'trading_balance': get_cr_balance(), 'savings_balance': get_savings_balance(ccy),
             'overdraft_balance': get_overdraft_balance()}


# Wealth Pack deposits (Initial Investment + '+ Deposit') no longer hard-stop
# when the account can't fully cover them. True  -> the deposit always goes
# through: whatever the Trading -> Savings -> FD-credit cascade CAN cover is
# deducted (balance floors at 0, never negative) and the rest is recorded on
# the deposit as 'unfunded_cr'. False -> old behaviour (reject with
# "Not enough funds"). Recurring top-ups stay gated either way — they fire
# automatically, so silently minting unfunded money every period isn't wanted.
WEALTH_ALLOW_UNFUNDED_DEPOSITS = False

# True -> Wealth deposits are gated on the Cr Balance shown in the page
# header (Trading only): a balance of 0 blocks every deposit, and an amount
# above the balance is rejected — Savings / FD credit are NOT tapped to
# make up the difference. False -> old behaviour (Trading + Savings + FD
# credit combined).
WEALTH_DEPOSIT_TRADING_ONLY = True


def wealth_deposit_gate(amount: float):
    """None if a Wealth deposit of `amount` Cr may proceed, else the
    error text to show. Only enforced when WEALTH_DEPOSIT_TRADING_ONLY."""
    if not WEALTH_DEPOSIT_TRADING_ONLY:
        return None
    bal = get_cr_balance()
    if bal <= 0:
        return 'Cr Balance is 0 — deposit blocked. Top up your balance first.'
    if amount > bal + 1e-9:
        return (f'Amount exceeds your Cr Balance ({bal:,.2f}) — '
                f'short by Cr {amount - bal:,.2f}.')
    return None


def get_spendable_cr(ccy: str = 'USD') -> dict:
    """What spend_cr() could cover right now, by tier (all in Cr):
    {'trading', 'savings', 'credit', 'total'} — 'credit' is the unused
    part of the FD-secured overdraft line."""
    trading = get_cr_balance()
    savings = get_savings_balance(ccy)
    fd_state = _accrue_all_fds()
    credit_limit = sum(f['principal'] for f in fd_state['fds'] if f['status'] == 'active')
    credit = max(credit_limit - float(fd_state.get('overdraft', 0.0)), 0.0)
    return {'trading': trading, 'savings': savings, 'credit': credit,
            'total': trading + savings + credit}


def spend_cr_allow_unfunded(amount: float, ccy: str = 'USD') -> dict:
    """spend_cr() that never rejects for lack of funds. Spends everything
    the normal cascade can cover (trading -> savings -> FD overdraft) —
    exactly what spend_cr() would do for a covered amount — and reports
    the part it could NOT cover as 'unfunded' instead of failing the
    whole call. A balance of exactly 0 is fine: nothing is deducted and
    the full amount comes back as 'unfunded'.
    Returns spend_cr()'s keys plus 'unfunded' (Cr, >= 0); 'success' is
    always True here."""
    if amount <= 0:
        raise ValueError('amount must be positive')
    result = spend_cr(amount, ccy)
    if result['success']:
        result['unfunded'] = 0.0
        return result

    # Everything the cascade can cover — computed with the same
    # arithmetic spend_cr() uses, so spending exactly this amount can
    # never trip its own "amount > total" gate.
    covered = get_spendable_cr(ccy)['total']
    out = {'success': True, 'from_trading': 0.0, 'from_savings': 0.0, 'from_overdraft': 0.0,
           'shortfall': 0.0, 'trading_balance': get_cr_balance(),
           'savings_balance': get_savings_balance(ccy),
           'overdraft_balance': get_overdraft_balance(), 'unfunded': amount}
    if covered > 0.005:
        partial = spend_cr(covered, ccy)
        if not partial['success']:
            partial = spend_cr(covered * (1 - 1e-9), ccy)   # float-noise retry
        if partial['success']:
            out.update({k: partial[k] for k in ('from_trading', 'from_savings', 'from_overdraft',
                                                'trading_balance', 'savings_balance',
                                                'overdraft_balance')})
            out['unfunded'] = max(amount - covered, 0.0)
    return out


# IW-ZD / IW-ZDL trading lifecycle — a genuine DAILY product anchored on
# Bursa close (~5:00 PM):
#   4:50 PM  — PRE-ORDER window opens. Subscribe at an indicative price
#              (today's par-basis reading) against a 40% deposit; order
#              is 'pending' until finalized.
#   5:00 PM  — SETTLEMENT of the certificate that opened the PREVIOUS
#              evening: its value is locked off today's actual Bursa
#              close (this is exactly the close-to-close day-t reading
#              already stored in iw_zd_series — see _iw_zd_daily_series).
#              Any position still open from that prior cycle is settled
#              and its P/L is final from this point — it does NOT track
#              tonight's brand-new certificate afterward.
#   5:15 PM  — OPEN PRICE FINALIZED for TONIGHT's certificate, off the
#              same day's actual close. Any pending pre-orders are
#              confirmed at the finalized price (balance 60% deemed
#              settled) and become live positions; outright Buy/Open
#              also opens from here.
#   5:15 PM → 6:00 AM (next day) — LIVE overnight trading/order window.
#   6:00 AM  — Order window closes (no new orders), but the certificate
#              itself keeps running unsettled until 5:00 PM that same
#              day (see above) — a full close-to-close cycle.
#   6:00 AM → 4:50 PM — CLOSED to new orders. Existing positions await
#              their 5:00 PM settlement.
IW_ZD_PREORDER_OPEN   = time(16, 50)   # MYR/Bursa default — 4:50 PM pre-order/subscription opens (40% deposit)
IW_ZD_SETTLEMENT_TIME = time(17, 0)    # MYR/Bursa default — 5:00 PM next day, prior cycle's cert settles off today's close
IW_ZD_FINALIZE_TIME   = time(17, 15)   # MYR/Bursa default — 5:15 PM, tonight's open price finalized off actual Bursa close
IW_ZD_SESSION_CLOSE   = time(6, 0)     # 6:00 AM next day, same for every market — order window closes (settlement is separate)
IW_ZD_PREORDER_DEPOSIT_PCT = 0.40      # 40% deposit taken at pre-order
# The three MYR times above are all offsets off Bursa's own last-session
# close (16:45): +5min preorder-open, +15min settlement, +30min finalize.
# _iw_zd_window_times() reapplies those same offsets to whichever
# market's own close applies (SGX 17:00, HKEX 16:00, ...) so a DLC on a
# non-MYR underlying isn't gated by Bursa's schedule.


def _iw_zd_window_times(ccy: str = 'MYR'):
    """(preorder_open, settlement_time, finalize_time, session_close) for
    `ccy`'s own exchange, anchored to that exchange's actual last-session
    close via _market_close_time() rather than Bursa's fixed 4:50/5:00/
    5:15 PM. MYR keeps the original literal constants (same values,
    computed the same way) so nothing shifts for the default market."""
    close = _market_close_time(ccy)
    return (
        _add_minutes(close, 5),
        _add_minutes(close, 15),
        _add_minutes(close, 30),
        IW_ZD_SESSION_CLOSE,
    )


def _iw_zd_session_state(ccy: str = 'MYR'):
    """Returns (phase, is_open_for_new_orders, label) for the IW-ZD/
    IW-ZDL daily lifecycle right now, anchored to `ccy`'s own exchange
    open/close (Bursa/SGX/HKEX/TSE/KRX), Malaysia clock throughout
    (all five run on fixed UTC offsets with no DST, so a single MYT
    clock reads them all correctly):

      'pre_order' — TODAY's close+5min (e.g. 4:50 PM) continuously
                    through TOMORROW's market open (8:00 AM for JPY/
                    KRW, 9:00 AM everyone else) — this is one single
                    overnight subscription window (40% deposit), not a
                    short evening slot followed by an already-"live"
                    overnight leg. A Sunday-evening pre-order (opened by
                    Friday's close) is for Monday's cycle; the same
                    pattern repeats every trading night Mon-Fri.
      'live'      — market open through that same day's market close —
                    the pre-order finalizes into a fully-paid position
                    at the actual opening print and tracks the
                    underlying intraday until close, when it settles
                    (RV = settle price x qty).
      'closed'    — the two short gaps either side of the trading day:
                    market close through close+5min (settlement/
                    finalization processing before the next pre-order
                    opens), and 6:00 AM through market open (pre-order
                    has closed for that morning's cycle, market hasn't
                    opened yet).
    is_open_for_new_orders is True only for 'pre_order' and 'live'.

    Every cycle is anchored to an actual close/open on `ccy`'s own
    exchange — there is no session on a weekend or that exchange's
    public holiday (_is_market_holiday(ccy, ...), each market's own
    calendar) — so no new pre-order may open, and no live session may
    start, on one. Friday evening's pre-order still correctly carries
    through Saturday/Sunday into Monday's live session; the weekend days
    themselves can never start a fresh cycle of their own."""
    if not MALAYSIA_TZ:
        return 'closed', False, 'Session time unavailable'
    preorder_open, settlement_time, _finalize_time, session_close = _iw_zd_window_times(ccy)
    market_open = _market_open_time(ccy)
    market_close = _market_close_time(ccy)
    now = datetime.now(MALAYSIA_TZ)
    now_t = now.time()

    def _is_trading_day(d) -> bool:
        return d.weekday() < 5 and not _is_market_holiday(ccy, d)

    open_str  = market_open.strftime("%I:%M %p").lstrip("0")
    close_str = market_close.strftime("%I:%M %p").lstrip("0")

    # 00:00 - 6:00 AM: tail of the pre-order window opened by the PRIOR
    # day's close (a 2 AM check is really asking "did yesterday's close
    # open a cycle for today?").
    if now_t < session_close:
        prior_day = (now - pd.Timedelta(days=1)).date()
        if not _is_trading_day(prior_day):
            return ('closed', False,
                    '🔒 Market closed — no overnight pre-order cycle open. '
                    'Existing positions are unaffected.')
        return ('pre_order', True,
                f'🟡 Pre-Order window — {IW_ZD_PREORDER_DEPOSIT_PCT*100:.0f}% deposit, '
                f'goes live at {ccy} market open ({open_str})')

    # 6:00 AM - market open: pre-order has closed for today's cycle,
    # finalizing; the market itself hasn't opened yet.
    if now_t < market_open:
        return ('closed', False,
                f'🔒 Pre-order closed for today\'s cycle — {ccy} market opens '
                f'{open_str}, live trading resumes then.')

    # market open - market close: today's finalized position, fully
    # live and tracking the underlying intraday.
    if now_t < market_close:
        if not _is_trading_day(now.date()):
            return ('closed', False,
                    f'🔒 Market closed — {ccy} did not trade today. '
                    f'Existing positions are unaffected.')
        return ('live', True,
                f'🟢 Live — {ccy} market open, full price on entry, until {close_str}')

    # market close - close+5min: brief settlement/finalization gap
    # before tonight's pre-order window opens.
    if now_t < preorder_open:
        return ('closed', False,
                f'🔒 Market closed — settling today\'s position '
                f'(RV paid {settlement_time.strftime("%I:%M %p").lstrip("0")}), '
                f'pre-order reopens {preorder_open.strftime("%I:%M %p").lstrip("0")}')

    # close+5min onward: tonight's pre-order window, open through 6 AM.
    if not _is_trading_day(now.date()):
        return ('closed', False,
                f'🔒 Market closed — {ccy} did not trade today, no new cycle to pre-order. '
                f'Existing positions are unaffected.')
    return ('pre_order', True,
            f'🟡 Pre-Order window — {IW_ZD_PREORDER_DEPOSIT_PCT*100:.0f}% deposit, '
            f'goes live at {ccy} market open ({open_str})')


def _iw_zd_effective_phase(ccy: str = 'MYR'):
    """Same 3-way (phase, accepting_orders, msg) as _iw_zd_session_state(),
    except the daily-cert Pre-Order/Live CLOCK is overridden to 'live'
    whenever `ccy`'s own underlying market is genuinely open right now
    (_market_session_tag() reports 'L'). The Pre-Order deposit step only
    makes sense once the underlying has actually closed for the day and
    a fresh overnight certificate is being subscribed to indicatively —
    while the market itself is still trading, every trade surface
    (DLC/IW-ZD, Index Warrants, plain stocks) should just be live, full
    price on entry, same as before this daily lifecycle existed. This is
    what every _refresh()/_buy() in this file should read instead of
    _iw_zd_session_state()/_iw_zd_trading_allowed() directly, so the
    phase driving deposit_pct and the phase driving the displayed label
    can never disagree."""
    phase, accepting_orders, session_msg = _iw_zd_session_state(ccy)
    tag = _market_session_tag(ccy).strip('()')
    if phase != 'live' and tag == 'L':
        return ('live', True,
                f'🟢 Live — {ccy} market open, full price on entry')
    # Midday break (Bursa/SGX/HKEX/TSE lunch, 'M') is still the SAME
    # trading day/session — the exchange just pauses matching for an
    # hour, it isn't closed for the day the way evening/weekend is. An
    # order placed during the break fills at the last live mark and
    # simply carries through to the afternoon re-open, same as any
    # real broker allows resting/queued orders through lunch.
    if phase != 'live' and tag == 'M':
        return ('live', True,
                f'🟡 Live — {ccy} market on its midday break, order queues at last mark')
    return phase, accepting_orders, session_msg


def _iw_zd_trading_allowed(ccy: str = 'MYR') -> bool:
    """Whether a NEW DLC/IW-ZD position may be opened right now: true if
    EITHER the product's own overnight pre-order/live cycle is open
    (_iw_zd_session_state(ccy), now anchored to `ccy`'s own exchange
    close) OR the underlying index's own market is currently live
    (_market_session_tag() reports 'L') \u2014 whichever of the two says
    trading is open wins. Does not change session_msg/phase used for
    display; callers that gate an actual order should use this instead
    of accepting_orders alone.

    Public holiday, per instrument's own market: blocks new orders on a
    weekend or on `ccy`'s own exchange holiday calendar
    (MARKET_HOLIDAYS_BY_CCY / _is_market_holiday \u2014 Bursa for MYR, SGX
    for SGD, HKEX for HKD, NYSE for USD), NOT unconditionally on Bursa's
    calendar \u2014 a market that is open today must not be blocked just
    because Bursa happens to be closed, and vice versa. Same
    belt-and-suspenders check _buy() re-verifies right before writing a
    position, applied consistently at the gate level too so no
    instrument can slip through on its own holiday via the 'index
    live' path."""
    if MALAYSIA_TZ:
        _now = datetime.now(MALAYSIA_TZ)
        if _now.weekday() >= 5 or _is_market_holiday(ccy, _now.date()):
            return False
    _phase, accepting_orders, _msg = _iw_zd_session_state(ccy)
    if accepting_orders:
        return True
    return _market_session_tag(ccy).strip('()') in ('L', 'M')


def _iw_zd_settled_value(series, entry_date_str):
    """A daily product's certificate for a given day is a fixed,
    independent settlement (see _iw_zd_daily_series — never carried
    forward). So once a position's entry day is in the past, its P/L is
    LOCKED to THAT day's own reading in `series`, not to today's
    unrelated brand-new certificate. Returns (value, is_locked) — value
    is None if that date isn't in the series (shouldn't normally
    happen once data's been rebuilt)."""
    try:
        entry_ts = pd.Timestamp(entry_date_str)
    except Exception:
        return None, False
    try:
        pos = series.index.get_indexer([entry_ts], method='nearest')[0]
        if pos < 0:
            return None, False
        return float(series.iloc[pos]), True
    except Exception:
        return None, False


def _iw_zd_next_settle_date(entry_date_str, ccy: str = 'MYR'):
    """The actual calendar date a position entered on `entry_date_str`
    settles — next `ccy`-exchange trading day after entry, skipping
    weekends and that exchange's own holiday calendar
    (_is_market_holiday(ccy, ...)). Shared by _iw_zd_settlement_due()
    (the gating check: 'has that moment arrived yet') and
    _settle_due_positions() (the display value recorded once it has), so
    the two can never disagree on which date a Friday/pre-holiday entry
    actually settled."""
    entry_date = pd.Timestamp(entry_date_str).date()
    settle_date = entry_date + pd.Timedelta(days=1)
    while settle_date.weekday() >= 5 or _is_market_holiday(ccy, settle_date):
        settle_date = settle_date + pd.Timedelta(days=1)
    return settle_date


def _iw_zd_settlement_due(entry_date_str, ccy: str = 'MYR'):
    """A position bought on day T settles at that exchange's own
    settlement time (_iw_zd_window_times(ccy), e.g. 5:00 PM for MYR,
    5:15 PM for SGD) on the NEXT trading day for `ccy`'s exchange — not
    blindly calendar T+1. A Friday entry settles Monday at that time
    (skipping Sat/Sun), and rolls further past any public holiday on
    that exchange's own calendar (e.g. Monday a PH pushes settlement to
    Tuesday). Returns True once 'now' (Malaysia time — every supported
    exchange here runs on UTC+8) has reached that moment."""
    if not MALAYSIA_TZ:
        return False
    try:
        settle_date = _iw_zd_next_settle_date(entry_date_str, ccy)
    except Exception:
        return False
    _, settlement_time, _, _ = _iw_zd_window_times(ccy)
    settle_dt = datetime.combine(settle_date, settlement_time)
    settle_dt = settle_dt.replace(tzinfo=MALAYSIA_TZ)
    return datetime.now(MALAYSIA_TZ) >= settle_dt


def _fetch_stock_fundamentals(symbol: str) -> dict:
    """Trailing-twelve-month fundamentals for a single constituent, off
    yfinance's .info endpoint (slower than fast_info/history, so this is
    disk-cached for _TTL_FUNDAMENTALS = 1 day rather than hit on every
    popup open). Returns {} on any failure — callers must treat a
    missing/zero trailingPE as "exclude from aggregate", not as 0."""
    cache_key = f'fundamentals_{symbol}'
    cached = cache_get_live_dict(cache_key, ttl=_TTL_FUNDAMENTALS)
    if cached:
        return cached
    try:
        info = yf.Ticker(symbol).get_info()
    except Exception:
        try:
            info = yf.Ticker(symbol).info  # older yfinance fallback
        except Exception:
            return {}
    if not info:
        return {}
    out = {
        'trailingPE':     info.get('trailingPE'),
        'forwardPE':      info.get('forwardPE'),
        'trailingEps':    info.get('trailingEps'),
        'marketCap':      info.get('marketCap'),
        'totalRevenue':   info.get('totalRevenue'),
        'profitMargins':  info.get('profitMargins'),
        'returnOnEquity': info.get('returnOnEquity'),
        'dividendYield':  info.get('dividendYield'),
        'sector':         info.get('sector'),
        'industry':       info.get('industry'),
        'shortName':      info.get('shortName') or info.get('longName'),
    }
    cache_set_live_dict(cache_key, out)
    return out


def _fetch_ticker_name(symbol: str) -> str:
    """Just the display name for a symbol yfinance recognizes but isn't in
    any local dataset (e.g. HK/KR/JP/SG tickers typed into Search) — a
    much cheaper ask than full fundamentals, but still goes through
    .info, so disk-cached for the same _TTL_FUNDAMENTALS window and kept
    to a single field. Returns '' on any failure/unknown symbol; callers
    treat that as 'no name available', not an error."""
    cache_key = f'tickername_{symbol}'
    cached = cache_get_live_dict(cache_key, ttl=_TTL_FUNDAMENTALS)
    if cached:
        return cached.get('name', '')
    try:
        info = yf.Ticker(symbol).get_info()
    except Exception:
        try:
            info = yf.Ticker(symbol).info
        except Exception:
            info = {}
    name = (info or {}).get('shortName') or (info or {}).get('longName') or ''
    cache_set_live_dict(cache_key, {'name': name})
    return name


def _fetch_ticker_last_price(symbol: str):
    """Just the last close for a symbol not in any local dataset — used
    by Search to badge IW/IW-ZD/IW-ZDL/DLC eligibility (see
    is_stock_dlc_eligible()) for HK/KR/JP/SG tickers, which have no
    local price cache the way MY's df_listed does. Cheap 1-day history
    call rather than .info, disk-cached under _TTL_PRICE (1 day) so
    Search doesn't re-hit yfinance on every keystroke. Returns None on
    any failure/unknown symbol."""
    cache_key = f'tickerlastpx_{symbol}'
    cached = cache_get_live_dict(cache_key, ttl=_TTL_PRICE)
    if cached and cached.get('price') is not None:
        return cached.get('price')
    try:
        hist = yf.Ticker(symbol).history(period='5d', interval='1d')
        if hist is None or hist.empty:
            # '5d' comes back empty for a thinly-traded stock with zero
            # trades in the last 5 calendar days, not just a genuinely
            # missing/delisted one — widen before giving up on it.
            hist = yf.Ticker(symbol).history(period='1mo', interval='1d')
        price = float(hist['Close'].dropna().iloc[-1]) if hist is not None and not hist.empty else None
    except Exception:
        price = None
    if price is not None:
        cache_set_live_dict(cache_key, {'price': price})
    return price


def _compute_market_pe(app, label: str = 'MYIPO+'):
    """Aggregate index-level P/E, computed the way S&P calculates the
    S&P 500's P/E: NOT a simple average of constituent P/Es, but
    (total constituent market cap) / (total constituent earnings) —
    equivalent to the market-cap-weighted HARMONIC mean of the
    individual P/Es:  MarketPE = 1 / Σ(weight_i / PE_i)
    Constituents with no/zero/negative trailing P/E (loss-making, or
    fundamentals unavailable) are excluded from both the numerator and
    denominator — same convention S&P uses for negative-earnings
    constituents — and their weight is renormalized across the rest so
    a handful of missing names doesn't silently understate the figure.
    Returns (market_pe, n_included, n_total) — market_pe is None if
    fewer than one usable constituent is found."""
    w_snap = (app.weights_snapshot or {}).get(label)
    if w_snap is None or w_snap.empty:
        return None, 0, 0
    n_total = len(w_snap)
    inv_pe_weighted, used_weight, n_included = 0.0, 0.0, 0
    for sym, wt in w_snap.items():
        fnd = _fetch_stock_fundamentals(sym)
        pe = fnd.get('trailingPE')
        if not pe or pe <= 0:
            continue
        inv_pe_weighted += float(wt) / pe
        used_weight += float(wt)
        n_included += 1
    if n_included == 0 or used_weight <= 0 or inv_pe_weighted <= 0:
        return None, n_included, n_total
    # Renormalize: inv_pe_weighted was built from raw weights that summed
    # to `used_weight` (< 1.0 if some constituents were excluded) — divide
    # through so the excluded names' weight doesn't drag the figure down.
    market_pe = used_weight / inv_pe_weighted
    return market_pe, n_included, n_total



