def _apply_theme(name):
    """Reassigns the module-level color globals every widget builder
    (_card, each page's build(), chart styling) reads at creation time.
    Doesn't touch already-built widgets — the app does a full UI rebuild
    right after calling this so the new palette actually takes effect."""
    global _BG, _PANEL, _CARD, _BORDER, _TEXT, _SUBTEXT, _ACCENT, _GREEN, _RED
    global _TREE_BG, _BTN_TEXT
    t = _THEMES.get(name, _THEMES['dark'])
    _BG, _PANEL, _CARD, _BORDER = t['BG'], t['PANEL'], t['CARD'], t['BORDER']
    _TEXT, _SUBTEXT, _ACCENT    = t['TEXT'], t['SUBTEXT'], t['ACCENT']
    _GREEN, _RED                = t['GREEN'], t['RED']
    _TREE_BG, _BTN_TEXT         = t['TREE_BG'], t['BTN_TEXT']


