# =============================================================================
# Upcoming-IPO notification store
# =============================================================================
# Persists which upcoming IPOs the user has already acknowledged, so the
# "New IPO coming soon" popup only interrupts once per IPO — dismissing it
# doesn't suppress genuinely new listings added on a later rebuild.

_IPO_ACK_CACHE = os.path.join(DEFAULT_FOLDER, 'upcoming_ipo_ack.json')
UPCOMING_IPO_WINDOW_DAYS = 14   # surface IPOs whose D-1 falls within this many days


def _load_ipo_ack() -> set:
    import json as _j
    try:
        with open(_IPO_ACK_CACHE, 'r', encoding='utf-8') as f:
            return set(_j.load(f))
    except Exception:
        return set()


def _save_ipo_ack(ack: set):
    import json as _j
    try:
        with open(_IPO_ACK_CACHE, 'w', encoding='utf-8') as f:
            _j.dump(sorted(ack), f)
    except Exception:
        pass


def _load_wealth_packs() -> dict:
    """Returns {pack_name: {'created': 'YYYY-MM-DD', 'holdings':
    [{'ticker': str, 'weight': float}, ...]}}. Weight is a % (0-100)."""
    import json as _j
    try:
        with open(WEALTH_PACKS_CACHE, 'r', encoding='utf-8') as f:
            return _j.load(f)
    except Exception:
        return {}


def _wealth_invalidate_value_cache():
    """Drops the 60s 'wealth_packs_total_value' live cache so the very
    next get_wealth_packs_total_value() call re-prices every pack.
    Called from _save_wealth_packs(), i.e. on EVERY pack mutation."""
    try:
        os.remove(_ljson('wealth_packs_total_value'))
    except Exception:
        pass


def _save_wealth_packs(packs: dict):
    import json as _j
    try:
        with open(WEALTH_PACKS_CACHE, 'w', encoding='utf-8') as f:
            _j.dump(packs, f, indent=2)
    except Exception:
        pass
    # Any saved change to a pack (new pack, edited holdings, deposit,
    # withdrawal, top-up, deletion, dividend routing) makes the cached
    # total stale — drop it so Total Value / Unrealized P/L / Cash Value
    # update immediately instead of lagging up to 60s behind the ledger.
    _wealth_invalidate_value_cache()


# How far BEFORE a pack's creation date a fresh price pull reaches back.
# A pack created on a weekend / holiday / before today's close has no
# close on-or-after its creation date yet, so the buy anchors to the
# last close BEFORE it (see _wealth_load_close_series) — which only
# works if that earlier history was actually fetched. Fetching with
# `start=created` (the old behaviour) returned nothing for exactly that
# case, which is how a ticker with no warm cache (e.g. 2819.HK) ended
# up 'missing' from a pack created today.
WEALTH_PRICE_LOOKBACK_DAYS = 400
_WEALTH_PRICE_FAIL = {}        # {ticker: epoch of last failed fetch} — avoids re-hitting a dead symbol every repaint
_WEALTH_PRICE_FAIL_TTL = 300   # seconds


def _wealth_prefetch_pack_prices(app, pack: dict, created=None, progress_cb=None):
    """Batch-downloads price history for every real ticker in this pack
    in one or a few chunked, sequential, throttled yf.download() calls —
    same pattern build_indices() uses for the main index universe —
    instead of _wealth_load_close_series hitting Yahoo with one
    yf.Ticker(t).history() call per ticker. A pack with, say, 8 tickers
    used to mean 8 separate individual requests every time its cache
    went stale; that's exactly the shape of traffic that trips Yahoo's
    rate limiter (see the same fix already applied to build_indices'
    own download step). Results are written straight to the normal disk
    cache (cache_set_prices), so _wealth_load_close_series' existing
    per-ticker lookup picks them up as a free cache hit right after —
    this function doesn't change what gets used, only how it gets
    fetched.

    Cheap to call often: skips any ticker that's already covered by a
    fresh disk cache or the in-memory index-build DataFrame, and skips
    any ticker that failed within the last _WEALTH_PRICE_FAIL_TTL
    seconds, so a warm pack (the common case — most repaints) costs
    nothing extra here at all.

    progress_cb(done, total), if given, is called after each chunk
    finishes (done = chunks completed so far, total = chunk count) —
    lets a caller show a live % while a cold-cache pack's download is
    in flight instead of a static 'Computing…' with no sense of
    progress. Not called at all if there's nothing to fetch."""
    created = created or pack.get('created') or START_DATE_STR
    tickers, _weights = _wealth_weights_with_cash(pack)
    real_tickers = [t for t in tickers if t != WEALTH_CASH_TICKER]
    if not real_tickers:
        return

    px = getattr(app, 'stock_price_df', None)
    now = time_module.time()
    need = []
    for t in real_tickers:
        if px is not None and t in getattr(px, 'columns', []):
            continue   # already in-memory from the last index build
        if cache_get_prices(t) is not None:
            continue   # already fresh on disk
        last_fail = _WEALTH_PRICE_FAIL.get(t, 0)
        if (now - last_fail) <= _WEALTH_PRICE_FAIL_TTL:
            continue   # failed recently — don't re-hit it yet
        need.append(t)
    if not need:
        return

    start_str = (pd.Timestamp(created) - pd.Timedelta(days=WEALTH_PRICE_LOOKBACK_DAYS)).strftime('%Y-%m-%d')
    CHUNK  = _smart_chunk_size(len(need), max_single_chunk=20, min_chunk=5, target_chunks=4)
    chunks = [need[i:i+CHUNK] for i in range(0, len(need), CHUNK)]
    n_chunks = len(chunks)

    import io as _io, contextlib as _ctx
    _CHUNK_PAUSE_SEC  = 1.5
    _RETRY_PAUSES_SEC = [3, 8]

    for chunk_idx, chunk in enumerate(chunks):
        _sink = _io.StringIO()
        raw_full = None
        for attempt in range(1 + len(_RETRY_PAUSES_SEC)):
            if attempt > 0:
                time_module.sleep(_RETRY_PAUSES_SEC[attempt - 1])
            try:
                with _ctx.redirect_stdout(_sink), _ctx.redirect_stderr(_sink):
                    raw_full = yf.download(chunk, start=start_str,
                                            auto_adjust=True, progress=False)
                break
            except Exception:
                raw_full = None
                continue

        if raw_full is None or raw_full.empty:
            for t in chunk:
                _WEALTH_PRICE_FAIL[t] = time_module.time()
        else:
            try:
                raw = raw_full['Close']
                if isinstance(raw, pd.Series):
                    raw = raw.to_frame(name=chunk[0])
            except Exception:
                raw = pd.DataFrame()
            got = set()
            for col in raw.columns:
                s = raw[col].dropna()
                if not s.empty:
                    cache_set_prices(str(col), s)
                    got.add(str(col))
            for t in chunk:
                if t not in got:
                    _WEALTH_PRICE_FAIL[t] = time_module.time()

        if progress_cb is not None:
            try:
                progress_cb(chunk_idx + 1, n_chunks)
            except Exception:
                pass

        if chunk is not chunks[-1]:
            time_module.sleep(_CHUNK_PAUSE_SEC)


def _wealth_load_close_series(app, t, created):
    """ONE shared price lookup for every Wealth Pack code path (chart
    replay, current-units replay, All-Packs replay, last-price lookups).
    Returns a daily-Close pd.Series covering `created` onward, or None
    if the ticker truly has no price at all.

    Tiers (fastest first, same order the page always used):
      1) app.stock_price_df (in-memory, already pulled by the index build)
      2) on-disk price cache — read WITHOUT a start filter. The old
         cache_get_prices(t, created) call filtered to rows >= created
         and returned None for a pack created today/on a weekend, which
         both hid a perfectly good cache AND made the 'anchor to the
         previous close' step below impossible.
      3) a fresh yfinance pull starting WEALTH_PRICE_LOOKBACK_DAYS before
         `created` (then cached).
      4) last resort: a single live quote, used as a one-row series at
         `created`, so a thinly-traded ETF with no daily history yet is
         still investable instead of silently dropped.

    Anchor rule: if nothing has posted on/after `created` yet (created
    today before the close, or a weekend), use the most recent close
    before it, relabelled to `created`, so the pack still prices and
    still invests instead of returning empty."""
    created_ts = pd.Timestamp(created)
    s = None
    px = getattr(app, 'stock_price_df', None)
    if px is not None and t in getattr(px, 'columns', []):
        s = px[t].dropna()
    if s is None or s.empty:
        try:
            s = cache_get_prices(t)
        except Exception:
            s = None
    if s is None or s.empty:
        last_fail = _WEALTH_PRICE_FAIL.get(t, 0)
        if (time_module.time() - last_fail) > _WEALTH_PRICE_FAIL_TTL:
            try:
                start = (created_ts - pd.Timedelta(days=WEALTH_PRICE_LOOKBACK_DAYS)).strftime('%Y-%m-%d')
                fetched = yf.Ticker(t).history(start=start)['Close']
                if fetched is not None and not fetched.empty:
                    fetched = fetched.dropna()
                    if getattr(fetched.index, 'tz', None) is not None:
                        fetched.index = fetched.index.tz_localize(None)
                    if not fetched.empty:
                        cache_set_prices(t, fetched)
                        s = fetched
            except Exception:
                s = None
            if s is None or s.empty:
                _WEALTH_PRICE_FAIL[t] = time_module.time()
    if s is None or s.empty:
        try:
            live = fetch_live_underlying_quote(t, ttl=300)
        except Exception:
            live = None
        if live and live > 0:
            return pd.Series([float(live)], index=pd.DatetimeIndex([created_ts]))
        return None

    s = s.dropna()
    try:
        s.index = pd.DatetimeIndex(s.index)
        if s.index.tz is not None:
            s.index = s.index.tz_localize(None)
    except Exception:
        pass
    s_after = s[s.index >= created_ts]
    if not s_after.empty:
        return s_after
    s_before = s[s.index < created_ts]
    if s_before.empty:
        return None
    anchor = s_before.iloc[[-1]].copy()
    anchor.index = pd.DatetimeIndex([created_ts])
    return anchor


def _wealth_last_price(app, t, created) -> float:
    """Latest known close for `t` (0.0 if none) — the value helpers'
    replacement for `cache_get_prices(t, created).iloc[-1]`, which came
    back empty (=> value 0) for any pack created today or on a weekend."""
    try:
        s = _wealth_load_close_series(app, t, created)
        if s is not None and not s.empty:
            v = float(s.iloc[-1])
            return v if v > 0 else 0.0
    except Exception:
        pass
    return 0.0


def _wealth_cash_price_series(start):
    """Flat price-1.0 series for the WEALTH_CASH_TICKER pseudo-holding,
    one entry per calendar day from `start` through today. A constant
    keeps its "units" numerically equal to the native-currency cash
    amount contributed, and daily (not business-day) coverage means it
    never introduces a gap that pd.concat(...).dropna(how='any') would
    otherwise trim from the real tickers alongside it."""
    idx = pd.date_range(start=pd.Timestamp(start), end=pd.Timestamp(datetime.now().date()), freq='D')
    if len(idx) == 0:
        idx = pd.DatetimeIndex([pd.Timestamp(start)])
    return pd.Series(1.0, index=idx)


def _wealth_weights_with_cash(pack):
    """(tickers, weights) for a pack's holdings, plus an implicit
    WEALTH_CASH_TICKER weight for whatever fraction of the target
    weights doesn't add up to 100% — so money that isn't earmarked for
    any real holding sits as literal uninvested cash (same 'Cash (Cr)'
    accounting subject the builder's 'Set Remainder as Cash' button
    writes explicitly) instead of being silently spread proportionally
    across whichever tickers ARE configured. This is what actually
    drives the buy-order math now (see _compute_pack_current_units /
    WealthManagementPage._apply()) — not just a display gloss — so a
    pack whose weights sum to, say, 8% now genuinely invests 8% of
    every deposit and leaves 92% sitting as cash, matching what the
    Composition/Units Held tables show. No-op if the pack already
    explicitly lists WEALTH_CASH_TICKER as a holding, or its weights
    already sum to (about) 100%."""
    holdings = pack.get('holdings', [])
    tickers = [h['ticker'] for h in holdings]
    weights = {h['ticker']: h['weight'] for h in holdings}
    if WEALTH_CASH_TICKER not in weights:
        remainder = 100.0 - sum(weights.values())
        if remainder > 0.01:
            tickers = tickers + [WEALTH_CASH_TICKER]
            weights = dict(weights)
            weights[WEALTH_CASH_TICKER] = remainder
    return tickers, weights


def _compute_pack_current_units(app, pack: dict, pack_name: str = None) -> dict:
    """Replays a pack's deposit/withdrawal schedule (base amount +
    extra_deposits — real top-up charges land there too, see
    WealthManagementPage._process_due_topups) against price history to
    get each holding's CURRENT unit count. This is the same
    purchase/sale-by-weight replay WealthManagementPage._apply() runs
    for its own chart, pulled out standalone so dividend settlement can
    call it with no UI/chart-cache dependency. Kept as a small,
    deliberate duplication rather than refactoring _apply() itself,
    which is wired directly into that page's rendering pipeline."""
    holdings = pack.get('holdings', [])
    seed_units = pack.get('seed_units') or {}
    if not holdings:
        # A merged pack that ended up with NO real-ticker weights (e.g.
        # every source pack was pure Cash, or every ticker's merged
        # weight rounded to 0) used to fall through this guard and
        # return {} — silently wiping out its seeded units below and
        # making a freshly-merged pack look like it lost its entire
        # position. Seeded units don't depend on the weight table at
        # all, so hand them back directly instead of discarding them.
        return {t: float(u or 0.0) for t, u in seed_units.items()} if seed_units else {}
    created = pack.get('created') or START_DATE_STR
    base_amount = pack.get('base_amount', 0) or 0
    tickers, weights = _wealth_weights_with_cash(pack)
    px = getattr(app, 'stock_price_df', None)

    # One chunked batch download for every stale ticker in this pack,
    # ahead of the per-ticker loop below — see _wealth_prefetch_pack_prices.
    _wealth_prefetch_pack_prices(app, pack, created)

    series_by_ticker = {}
    for t in tickers:
        if t == WEALTH_CASH_TICKER:
            series_by_ticker[t] = _wealth_cash_price_series(created)
            continue
        s = _wealth_load_close_series(app, t, created)
        if s is not None and not s.empty:
            series_by_ticker[t] = s

    if not series_by_ticker:
        # Same reasoning as the holdings guard above: a transient price-
        # fetch failure for every weight-table ticker on this call
        # (cache miss + yfinance hiccup) must not erase units that were
        # already carried over via seed_units — it just means no NEW
        # buying can be replayed against the (unpriceable) weight table
        # right now.
        return {t: float(u or 0.0) for t, u in seed_units.items()} if seed_units else {}
    # how='all' (not 'any'): a single laggard ticker with no price yet for
    # a given day used to zero out that ENTIRE day's buy for every OTHER
    # ticker in the pack too — dropna(how='any') drops the whole row the
    # moment one column is NaN. Only drop a day if every ticker is
    # missing it; the per-ticker `px_t and px_t > 0` guard below already
    # skips just the laggard on days where the rest have real data.
    closes = pd.concat(series_by_ticker, axis=1).ffill().dropna(how='all')
    ok_tickers = [t for t in tickers if t in closes.columns]
    w_total = sum(weights[t] for t in ok_tickers)
    if not ok_tickers or w_total <= 0 or closes.empty:
        return {}

    created_ts = pd.Timestamp(created)
    invest_dates = [created_ts]
    invest_amounts = [base_amount]
    for dep in pack.get('extra_deposits', []):
        try:
            dep_amt = float(dep.get('amount', 0) or 0)
        except (TypeError, ValueError):
            continue
        if dep_amt == 0:
            continue
        invest_dates.append(pd.Timestamp(dep.get('date') or created))
        invest_amounts.append(dep_amt)
    order = sorted(range(len(invest_dates)), key=lambda i: invest_dates[i])
    invest_dates = [invest_dates[i] for i in order]
    invest_amounts = [invest_amounts[i] for i in order]

    units = {t: 0.0 for t in ok_tickers}
    if seed_units:
        # A merged pack (see WealthManagementPage._do_merge_packs) is
        # seeded with the SOURCE packs' actual summed unit counts, not
        # just an equivalent Cr value re-bought at today's weight — so
        # merging doesn't quietly round-trip through a Cr<->native FX
        # conversion (sell leg on cash-out, buy leg on re-buy) and lose
        # a sliver of units to spread. base_amount still lands as a
        # normal dated deposit below and buys ADDITIONAL units on top
        # of this seed, same as any other pack's Initial Investment.
        for t, u in seed_units.items():
            if t in units:
                units[t] += float(u or 0.0)
            else:
                units[t] = float(u or 0.0)
    # `amt`/`sell_total` above are Cr (deposits/withdrawals are always
    # charged/credited in Cr — see spend_cr() calls at deposit time),
    # but `closes` holds each ticker's price in its OWN listing
    # currency (MYR/USD/HKD/...). Dividing a Cr figure straight by a
    # native price silently treats 1 Cr as 1 unit of that currency —
    # off by whatever the real Cr<->currency rate is (CR_PER_USD alone
    # is 10,000×, before the FX leg on non-USD tickers). Converting
    # through cr_to_usd()/fx_usd_leg_quote() (same USD-leg spread used
    # for a real trade's cost_cr) once per ticker up front avoids
    # repeating that live-rate lookup on every date in the loop below.
    ccy_of = {t: _ccy_for_label(t) for t in ok_tickers}
    fx_quote_of = {t: fx_usd_leg_quote(ccy_of[t]) for t in ok_tickers if ccy_of[t] != 'USD'}

    def _cr_to_native(cr_amt, t):
        usd = cr_to_usd(cr_amt)
        return usd if ccy_of[t] == 'USD' else usd * fx_quote_of[t]['buy_rate']

    def _native_to_cr(native_amt, t):
        return usd_to_cr(native_amt) if ccy_of[t] == 'USD' else usd_to_cr(native_amt / fx_quote_of[t]['sell_rate'])

    today_ts = pd.Timestamp(_cr_today_str())
    sched_idx = 0
    today_fill_log = []  # visibility for the 'Today's Fills' panel — see _WEALTH_FILL_LOG
    for dt in closes.index:
        cash_before_this_row = units.get(WEALTH_CASH_TICKER, 0.0)
        while sched_idx < len(invest_dates) and invest_dates[sched_idx] <= dt:
            amt = invest_amounts[sched_idx]
            if amt >= 0:
                # A deposit dated TODAY, landing on today's row, is only
                # fillable at today's close if `dt` is actually today AND
                # that ticker's own market is still 'live' or inside its
                # post-close grace window (wealth_order_price_mode). Any
                # ticker that's 'wait' (before its own open, or past its
                # grace) has its share of THIS deposit held back as
                # WEALTH_CASH_TICKER instead — same "in-flight, not yet
                # converted" treatment already used for a deposit dated
                # after the last available close (see pending_cr below).
                # Historical (past) rows are unaffected — the market
                # clock only gates TODAY's own not-yet-final row.
                is_today_row = (dt == today_ts)
                for t in ok_tickers:
                    cr_share = amt * weights[t] / w_total
                    px_t = closes.at[dt, t]
                    fillable = bool(px_t and px_t > 0)
                    price_source = 'close'
                    if fillable and is_today_row:
                        mode, _msg = wealth_order_price_mode(ccy_of[t])
                        if mode == 'wait':
                            fillable = False
                        elif t != WEALTH_CASH_TICKER:
                            # This is the actual bug behind a buy
                            # landing at a worse cost than the ticker's
                            # real price at execution time: `closes`
                            # holds one cached daily-Close value for
                            # 'today', fetched whenever that cache
                            # entry last refreshed — which can be hours
                            # stale mid-session. A deposit filling
                            # TODAY, while this ticker's market is live
                            # (or in its post-close grace window), must
                            # fill at the CURRENT live price, not that
                            # stale cached close, or the recorded cost
                            # basis is simply wrong from the moment
                            # it's written. Once written it still never
                            # changes again — only today's still-open
                            # fill uses live, every past day keeps its
                            # own real historical close untouched.
                            live_px = fetch_live_underlying_quote(t, ttl=app.LIVE_PING_INTERVAL)
                            if live_px and live_px > 0:
                                px_t = live_px
                                price_source = 'live'
                    if not fillable:
                        # Previously this share was just `continue`d when
                        # the ticker had no usable price on this exact
                        # historical day — dropped with no record
                        # anywhere, not invested AND not parked as cash
                        # either. That silently lost real deposited money
                        # from the replay. Park it as Cash instead, same
                        # as the today/'wait' case, so it's visible and
                        # gets picked up by the cash-sweep below the next
                        # day that ticker actually has a price.
                        units[WEALTH_CASH_TICKER] = units.get(WEALTH_CASH_TICKER, 0.0) + \
                            math.floor(cr_to_usd(cr_share) / WEALTH_MIN_UNIT) * WEALTH_MIN_UNIT
                        if is_today_row and pack_name:
                            # Track this specific ticker's held-back cash
                            # (native currency) so a market-open popup can
                            # later estimate how many units it'll convert
                            # into once that market's price mode flips out
                            # of 'wait' — see check_wealth_pending_fills().
                            key = (pack_name, t)
                            _WEALTH_PENDING_NATIVE[key] = _cr_to_native(cr_share, t)
                            today_fill_log.append({
                                'ticker': t, 'status': 'waiting',
                                'note': "market closed (pre-order/wait) — parked as Cash",
                                'cr_share': cr_share,
                            })
                        continue
                    native_share = _cr_to_native(cr_share, t)
                    raw = native_share / px_t
                    bought_units = math.floor(raw / WEALTH_MIN_UNIT) * WEALTH_MIN_UNIT
                    units[t] += bought_units
                    if is_today_row and pack_name and t != WEALTH_CASH_TICKER:
                        today_fill_log.append({
                            'ticker': t,
                            'status': 'live' if price_source == 'live' else 'closed_price',
                            'note': (f"filled at LIVE price" if price_source == 'live'
                                     else "filled at cached close (no live quote available)"),
                            'price': px_t, 'units': bought_units, 'cr_share': cr_share,
                        })
            else:
                sell_total = -amt   # Cr
                is_today_row = (dt == today_ts)
                held_value_cr = sum(_native_to_cr(units[t] * closes.at[dt, t], t) for t in ok_tickers)
                if held_value_cr > 0:
                    for t in ok_tickers:
                        px_t = closes.at[dt, t]
                        price_source = 'close'
                        if is_today_row and t != WEALTH_CASH_TICKER and px_t and px_t > 0:
                            # Same reasoning as a same-day buy: a
                            # withdrawal liquidating TODAY should sell
                            # at the CURRENT live price, not a possibly
                            # stale cached close, or the recorded
                            # proceeds are wrong from the moment
                            # they're written. Falls back to the
                            # cached close if no live quote is
                            # available right now.
                            live_px = fetch_live_underlying_quote(t, ttl=app.LIVE_PING_INTERVAL)
                            if live_px and live_px > 0:
                                px_t = live_px
                                price_source = 'live'
                        if px_t and px_t > 0 and units[t] > 0:
                            cur_val_cr = _native_to_cr(units[t] * px_t, t)
                            cur_share = cur_val_cr / held_value_cr
                            native_amt_t = _cr_to_native(sell_total * cur_share, t)
                            raw = native_amt_t / px_t
                            sold = math.floor(raw / WEALTH_MIN_UNIT) * WEALTH_MIN_UNIT
                            units[t] = max(units[t] - sold, 0.0)
                            if is_today_row and pack_name and sold > 0:
                                today_fill_log.append({
                                    'ticker': t,
                                    'status': 'live_sell' if price_source == 'live' else 'closed_sell',
                                    'note': (f"sold at LIVE price" if price_source == 'live'
                                             else "sold at cached close (no live quote available)"),
                                    'price': px_t, 'units': sold,
                                    'cr_share': _native_to_cr(sold * px_t, t),
                                })
            sched_idx += 1

        # Cash sweep: any WEALTH_CASH_TICKER units sitting around that
        # AREN'T the pack's own deliberate target cash allocation (i.e.
        # weights don't include a real CASH weight — see
        # _wealth_weights_with_cash) are stray money parked above because
        # a price wasn't available on the day it was supposed to buy.
        # Without this, that cash sits there forever even once the
        # ticker's price comes back — nothing ever retries it.
        #
        # This USED to skip today's own row entirely (`dt != today_ts`),
        # meaning stray cash parked on an earlier day only got reinvested
        # starting the NEXT calendar day even if the ticker's market
        # opened again TODAY — "buy at open" only actually happened a
        # day late. Now: on today's row, sweep `cash_before_this_row`
        # (cash that was already stray BEFORE today's deposit handling
        # ran, i.e. parked on a prior day) using the CURRENT live price
        # if that ticker's market is open right now — a real buy, not
        # just the check_wealth_pending_fills() popup's estimate. Cash
        # freshly parked by TODAY's own deposit (if any) is deliberately
        # left out of this round so it still gets a chance to surface in
        # that popup first, exactly as before; it becomes plain stray
        # cash — and eligible for this same live sweep — starting
        # tomorrow if it's still sitting there. Past (non-today) rows
        # behave exactly as before, using that day's own close price.
        is_today_sweep = (dt == today_ts)
        sweepable_usd = cash_before_this_row if is_today_sweep else units.get(WEALTH_CASH_TICKER, 0.0)
        if weights.get(WEALTH_CASH_TICKER, 0.0) <= 0.01 and sweepable_usd > 0:
            real_tickers = [t for t in ok_tickers if t != WEALTH_CASH_TICKER]
            w_real_total = sum(weights[t] for t in real_tickers)
            if w_real_total > 0:
                stray_cr = usd_to_cr(sweepable_usd)
                invested_cr = 0.0
                for t in real_tickers:
                    px_t = closes.at[dt, t]
                    price_source = 'close'
                    if is_today_sweep:
                        mode, _msg = wealth_order_price_mode(ccy_of[t])
                        if mode == 'wait':
                            continue
                        live_px = fetch_live_underlying_quote(t, ttl=app.LIVE_PING_INTERVAL)
                        if live_px and live_px > 0:
                            px_t = live_px
                            price_source = 'live'
                    if not (px_t and px_t > 0):
                        continue
                    share_cr = stray_cr * weights[t] / w_real_total
                    native_share = _cr_to_native(share_cr, t)
                    raw = native_share / px_t
                    bought = math.floor(raw / WEALTH_MIN_UNIT) * WEALTH_MIN_UNIT
                    if bought > 0:
                        units[t] += bought
                        invested_cr += _native_to_cr(bought * px_t, t)
                        if is_today_sweep and pack_name:
                            today_fill_log.append({
                                'ticker': t,
                                'status': 'live_sweep' if price_source == 'live' else 'sweep',
                                'note': (f"stray cash from an earlier 'wait' park bought in "
                                         f"at market open ({'LIVE price' if price_source == 'live' else 'close'})"),
                                'price': px_t, 'units': bought, 'cr_share': _native_to_cr(bought * px_t, t),
                            })
                if invested_cr > 0:
                    units[WEALTH_CASH_TICKER] = max(
                        0.0, units.get(WEALTH_CASH_TICKER, 0.0) - cr_to_usd(invested_cr))

    # Any deposit dated AFTER the last available price close (market
    # hasn't posted that day's data yet — the deposit is still
    # "in-flight" on the actual buy order) never gets a chance to run
    # through the while-loop above, because that loop only walks
    # `closes.index`, and `closes` won't have a row for today until a
    # price provider actually posts one — which for a fresh same-day
    # deposit is almost never yet. Previously the ENTIRE amount got
    # parked as cash here regardless of whether any ticker's market
    # was actually live right now, silently ignoring a perfectly good
    # live quote just because the daily-close table hadn't caught up.
    # Now: attempt a live-price buy per ticker first (same gate as the
    # same-day path inside the while-loop — wealth_order_price_mode +
    # fetch_live_underlying_quote), exactly like a normal 'today' fill
    # would, and only park whatever's left (tickers whose own market
    # really is shut, plus the pack's own deliberate cash weight) as
    # WEALTH_CASH_TICKER. Only deposits (positive amounts) are handled
    # this way; a pending withdrawal hasn't touched any units yet
    # either, so there's nothing to represent.
    pending_cr = sum(a for a in invest_amounts[sched_idx:] if a > 0)
    if pending_cr > 0:
        filled_cr = 0.0
        for t in ok_tickers:
            if t == WEALTH_CASH_TICKER:
                continue
            mode, _msg = wealth_order_price_mode(ccy_of[t])
            if mode == 'wait':
                continue
            live_px = fetch_live_underlying_quote(t, ttl=app.LIVE_PING_INTERVAL)
            if not live_px or live_px <= 0:
                continue
            cr_share = pending_cr * weights[t] / w_total
            native_share = _cr_to_native(cr_share, t)
            raw = native_share / live_px
            bought_units = math.floor(raw / WEALTH_MIN_UNIT) * WEALTH_MIN_UNIT
            if bought_units <= 0:
                continue
            units[t] += bought_units
            filled_cr += cr_share
            if pack_name:
                today_fill_log.append({
                    'ticker': t, 'status': 'live_pending_fill',
                    'note': "today's close not posted yet — filled at LIVE price instead",
                    'price': live_px, 'units': bought_units, 'cr_share': cr_share,
                })
        pending_cr = max(0.0, pending_cr - filled_cr)

    if pending_cr > 0:
        units[WEALTH_CASH_TICKER] = units.get(WEALTH_CASH_TICKER, 0.0) + \
            math.floor(cr_to_usd(pending_cr) / WEALTH_MIN_UNIT) * WEALTH_MIN_UNIT
        if pack_name:
            # Whatever's left after the live-fill attempt above: either
            # tickers whose own market genuinely isn't open right now,
            # or the pack's own deliberate target cash weight. Still
            # logged so a brand-new deposit never looks like it
            # "didn't update" even though part (or all) of it landed
            # correctly as Cash pending its first pricing pass.
            today_fill_log.append({
                'ticker': 'ALL (pending)', 'status': 'pending_data',
                'note': "remaining balance: no live price / market closed — parked as Cash",
                'cr_share': pending_cr,
            })

    if pack_name:
        _WEALTH_FILL_LOG[pack_name] = {
            'checked_at': datetime.now().strftime('%H:%M:%S'),
            'entries': today_fill_log,
        }

    return units


def _compute_pack_value_invested_series(app, pack):
    """Standalone replay of a single pack's (value_series, invested_series,
    missing) history in Cr — same buy/withdraw/cash-sweep mechanics as
    WealthManagementPage._fetch_and_plot's inner loop, trimmed to just
    the two series (no drift_series/cost_native/UI ties) so the 'All
    Packs' combined view can build every pack's history without opening
    each one's individual detail tab. Kept as its own small duplication
    of that loop — same deliberate tradeoff _compute_pack_current_units'
    docstring already accepts — rather than threading a UI-page method
    through a non-UI caller."""
    holdings = pack.get('holdings', [])
    empty = (pd.Series(dtype=float), pd.Series(dtype=float), [])
    if not holdings:
        return empty
    created = pack.get('created') or START_DATE_STR
    base_amount = pack.get('base_amount', 0) or 0
    tickers, weights = _wealth_weights_with_cash(pack)
    px = getattr(app, 'stock_price_df', None)

    # One chunked batch download for every stale ticker in this pack —
    # see _wealth_prefetch_pack_prices.
    _wealth_prefetch_pack_prices(app, pack, created)

    series_by_ticker = {}
    for t in tickers:
        if t == WEALTH_CASH_TICKER:
            series_by_ticker[t] = _wealth_cash_price_series(created)
            continue
        s = _wealth_load_close_series(app, t, created)
        if s is not None and not s.empty:
            series_by_ticker[t] = s

    if not series_by_ticker:
        return (pd.Series(dtype=float), pd.Series(dtype=float), tickers)
    closes = pd.concat(series_by_ticker, axis=1).ffill().dropna(how='all')
    if closes.empty:
        return (pd.Series(dtype=float), pd.Series(dtype=float), tickers)

    ok_tickers = [t for t in tickers if t in closes.columns]
    missing = [t for t in tickers if t not in closes.columns]
    w_total = sum(weights[t] for t in ok_tickers)
    if not ok_tickers or w_total <= 0:
        return (pd.Series(dtype=float), pd.Series(dtype=float), missing)

    created_ts = pd.Timestamp(created)
    invest_dates = [created_ts]
    invest_amounts = [base_amount]
    for dep in pack.get('extra_deposits', []):
        try:
            dep_amt = float(dep.get('amount', 0) or 0)
        except (TypeError, ValueError):
            continue
        if dep_amt == 0:
            continue
        invest_dates.append(pd.Timestamp(dep.get('date') or created))
        invest_amounts.append(dep_amt)
    order = sorted(range(len(invest_dates)), key=lambda i: invest_dates[i])
    invest_dates = [invest_dates[i] for i in order]
    invest_amounts = [invest_amounts[i] for i in order]

    units = {t: 0.0 for t in ok_tickers}
    value_series = pd.Series(index=closes.index, dtype=float)
    invested_series = pd.Series(index=closes.index, dtype=float)
    invested_cum = 0.0

    ccy_of = {t: _ccy_for_label(t) for t in ok_tickers}
    fx_quote_of = {t: fx_usd_leg_quote(ccy_of[t]) for t in ok_tickers if ccy_of[t] != 'USD'}

    def _cr_to_native(cr_amt, t):
        usd = cr_to_usd(cr_amt)
        return usd if ccy_of[t] == 'USD' else usd * fx_quote_of[t]['buy_rate']

    def _native_to_cr(native_amt, t):
        return usd_to_cr(native_amt) if ccy_of[t] == 'USD' else usd_to_cr(native_amt / fx_quote_of[t]['sell_rate'])

    sched_idx = 0
    for date in closes.index:
        while sched_idx < len(invest_dates) and invest_dates[sched_idx] <= date:
            amt = invest_amounts[sched_idx]
            invested_cum += amt
            if amt >= 0:
                for t in ok_tickers:
                    px_t = closes.at[date, t]
                    if px_t and px_t > 0:
                        cr_share = amt * weights[t] / w_total
                        native_share = _cr_to_native(cr_share, t)
                        raw = native_share / px_t
                        units[t] += math.floor(raw / WEALTH_MIN_UNIT) * WEALTH_MIN_UNIT
                    else:
                        cr_share = amt * weights[t] / w_total
                        units[WEALTH_CASH_TICKER] = units.get(WEALTH_CASH_TICKER, 0.0) + \
                            math.floor(cr_to_usd(cr_share) / WEALTH_MIN_UNIT) * WEALTH_MIN_UNIT
            else:
                sell_total = -amt
                held_value_cr = sum(_native_to_cr(units[t] * closes.at[date, t], t) for t in ok_tickers)
                if held_value_cr > 0:
                    for t in ok_tickers:
                        px_t = closes.at[date, t]
                        if px_t and px_t > 0 and units[t] > 0:
                            cur_val_cr = _native_to_cr(units[t] * px_t, t)
                            cur_share = cur_val_cr / held_value_cr
                            native_amt_t = _cr_to_native(sell_total * cur_share, t)
                            raw = native_amt_t / px_t
                            sold = math.floor(raw / WEALTH_MIN_UNIT) * WEALTH_MIN_UNIT
                            units[t] = max(units[t] - sold, 0.0)
            sched_idx += 1

        if weights.get(WEALTH_CASH_TICKER, 0.0) <= 0.01:
            stray_usd = units.get(WEALTH_CASH_TICKER, 0.0)
            if stray_usd > 0:
                real_tickers = [t for t in ok_tickers if t != WEALTH_CASH_TICKER]
                w_real_total = sum(weights[t] for t in real_tickers)
                if w_real_total > 0:
                    stray_cr = usd_to_cr(stray_usd)
                    invested_cr = 0.0
                    for t in real_tickers:
                        px_t = closes.at[date, t]
                        if not (px_t and px_t > 0):
                            continue
                        share_cr = stray_cr * weights[t] / w_real_total
                        native_share = _cr_to_native(share_cr, t)
                        raw = native_share / px_t
                        bought = math.floor(raw / WEALTH_MIN_UNIT) * WEALTH_MIN_UNIT
                        if bought > 0:
                            units[t] += bought
                            invested_cr += _native_to_cr(bought * px_t, t)
                    if invested_cr > 0:
                        units[WEALTH_CASH_TICKER] = max(0.0, stray_usd - cr_to_usd(invested_cr))

        day_value = sum(_native_to_cr(units[t] * closes.at[date, t], t) for t in ok_tickers)
        value_series[date] = day_value
        invested_series[date] = invested_cum

    return (value_series, invested_series, missing)


def settle_wealth_pack_dividends(app):
    """Credits each Wealth Pack's 'Unrouted Dividends' Cr balance
    (pack['unrouted_dividends']) for any dividend its holdings paid
    since the pack's last check (pack['div_last_check'], defaulting to
    the pack's creation date on the first run). Approximation: uses the
    pack's CURRENT unit count for every holding (see
    _compute_pack_current_units) rather than the unit count actually
    held on each individual historical ex-dividend date — consistent
    with the rest of this app's end-of-day-level pricing, not a
    tick/lot-accurate ledger.

    Unrouted dividend cash sits on the pack until the user explicitly
    routes it from the Wealth Management page — to Savings
    (deposit_to_savings) or transferred into another pack as a plain Cr
    top-up split by that pack's target weights (an extra_deposits
    entry there, same mechanism as a manual '+ Deposit'). It is never
    auto-reinvested back into the paying pack itself. Runs every main
    rebuild, alongside settle_stock_pending_orders()."""
    packs = _load_wealth_packs()
    if not packs:
        return
    today = (datetime.now(MALAYSIA_TZ) if MALAYSIA_TZ else datetime.now())
    today_str = today.strftime('%Y-%m-%d')
    changed = False
    for name, pack in packs.items():
        holdings = pack.get('holdings', [])
        if not holdings:
            continue
        # One-time migration: dividend settlement originally ran with a
        # unit-purchase bug (Cr treated as native currency with no FX
        # conversion — see _compute_pack_current_units) that inflated
        # unit counts by ~1,000-2,000x. Any 'unrouted_dividends' or
        # 'dividend_log' saved before the fix is wrong by that same
        # factor and would otherwise sit there forever, silently
        # corrupting get_wealth_packs_total_value(). Wipe and
        # reprocess this pack's full dividend history exactly once —
        # `div_math_fixed` marks that it's been done so later runs go
        # back to the normal incremental (since-last-check) path.
        if not pack.get('div_math_fixed'):
            pack['unrouted_dividends'] = 0.0
            pack['dividend_log'] = []
            pack['div_last_check'] = pack.get('created') or START_DATE_STR
            pack['div_math_fixed'] = True
            changed = True
        last_check = pack.get('div_last_check') or pack.get('created') or START_DATE_STR
        last_check_ts = pd.Timestamp(last_check)
        units = _compute_pack_current_units(app, pack, pack_name=name)
        if units:
            pack_native_cr = 0.0
            for h in holdings:
                t = h['ticker']
                u = units.get(t, 0.0)
                if u <= 0:
                    continue
                divs = _get_ticker_dividends(t)
                if divs is None or divs.empty:
                    continue
                idx = divs.index
                if idx.tz is not None:
                    divs = divs.copy()
                    divs.index = idx.tz_localize(None)
                new_divs = divs[(divs.index > last_check_ts) & (divs.index <= pd.Timestamp(today_str))]
                if new_divs.empty:
                    continue
                native_amount = float(new_divs.sum()) * u
                if native_amount <= 0:
                    continue
                ccy = _ccy_for_label(t)
                pack_native_cr += underlying_to_cr(native_amount, ccy, direction='sell')
            if pack_native_cr > 0:
                pack['unrouted_dividends'] = float(pack.get('unrouted_dividends', 0) or 0) + pack_native_cr
                pack.setdefault('dividend_log', []).append({
                    'date': today_str, 'type': 'credited', 'amount': pack_native_cr,
                    'note': 'Dividend credited (unrouted)',
                })
                changed = True
        pack['div_last_check'] = today_str
        changed = True
    if changed:
        _save_wealth_packs(packs)


def route_pack_dividend_to_savings(pack_name: str, amount: float, ccy: str = 'USD') -> dict:
    """Moves up to `amount` Cr of a pack's unrouted-dividend balance
    into Savings. Unlike deposit_to_savings(), this does NOT debit the
    trading Cr balance first — dividend cash was never credited to
    trading, it only ever existed in pack['unrouted_dividends'], so
    deposit_to_savings()'s "do you have this much free in trading?"
    check would reject it even though the dividend money is real.
    Credits Savings directly (same _load_savings_state/_accrue_savings/
    _save_savings_state sequence deposit_to_savings uses internally).
    Returns {'success', 'savings_balance', 'pack_remaining'} — no
    'trading_balance' key, since trading is untouched by this."""
    packs = _load_wealth_packs()
    pack = packs.get(pack_name)
    if pack is None:
        return {'success': False, 'reason': 'no such pack', 'pack_remaining': 0.0}
    available = float(pack.get('unrouted_dividends', 0) or 0)
    amount = min(amount, available)
    if amount <= 0:
        return {'success': False, 'reason': 'no unrouted dividends', 'pack_remaining': available}
    state = _load_savings_state()
    state = _accrue_savings(state, ccy, _cr_today_str())
    state['balance'] = float(state.get('balance', 0.0)) + amount
    _save_savings_state(state)
    pack['unrouted_dividends'] = available - amount
    pack.setdefault('dividend_log', []).append({
        'date': _cr_today_str(), 'type': 'to_savings', 'amount': -amount,
        'note': 'Dividend routed to Savings',
    })
    _save_wealth_packs(packs)
    return {'success': True, 'reason': '', 'savings_balance': state['balance'],
            'pack_remaining': pack['unrouted_dividends']}


def route_pack_dividend_to_pack(from_pack: str, to_pack: str, amount: float) -> dict:
    """Moves up to `amount` Cr of from_pack's unrouted-dividend balance
    into to_pack as a plain Cr top-up — an extra_deposits entry dated
    today, split across to_pack's holdings by its TARGET weights on the
    next replay, exactly like a manual '+ Deposit' on that pack (see
    WealthManagementPage._apply()). Returns {'success', 'reason',
    'amount_moved', 'from_pack_remaining'}."""
    if from_pack == to_pack:
        return {'success': False, 'reason': 'source and destination pack are the same',
                'amount_moved': 0.0, 'from_pack_remaining': 0.0}
    packs = _load_wealth_packs()
    src = packs.get(from_pack)
    dst = packs.get(to_pack)
    if src is None or dst is None:
        return {'success': False, 'reason': 'pack not found', 'amount_moved': 0.0,
                'from_pack_remaining': float((src or {}).get('unrouted_dividends', 0) or 0)}
    available = float(src.get('unrouted_dividends', 0) or 0)
    amount = min(amount, available)
    if amount <= 0:
        return {'success': False, 'reason': 'no unrouted dividends', 'amount_moved': 0.0,
                'from_pack_remaining': available}
    today_str = (datetime.now(MALAYSIA_TZ) if MALAYSIA_TZ else datetime.now()).strftime('%Y-%m-%d')
    dst.setdefault('extra_deposits', []).append({
        'date': today_str, 'amount': amount,
        'note': f'Dividend transfer from "{from_pack}"',
    })
    src['unrouted_dividends'] = available - amount
    src.setdefault('dividend_log', []).append({
        'date': today_str, 'type': 'to_pack', 'amount': -amount,
        'note': f'Dividend routed to "{to_pack}"',
    })
    _save_wealth_packs(packs)
    return {'success': True, 'reason': '', 'amount_moved': amount,
            'from_pack_remaining': src['unrouted_dividends']}


class UpcomingIPOPopup(tk.Toplevel):
    """'New IPO coming soon' notification — lists IPOs entering the
    UPCOMING_IPO_WINDOW_DAYS window that the user hasn't dismissed yet."""

    def __init__(self, parent, rows):
        super().__init__(parent)
        self.title('New IPO Coming Soon')
        self.configure(bg=_CARD)
        self.geometry('460x360')
        self.resizable(False, False)
        self.transient(parent)
        self._rows = rows
        self._ack_keys = set()

        tk.Label(self, text='🔔  New IPO Coming Soon', font=_FONT_H1,
                 bg=_CARD, fg=_ACCENT, anchor='w').pack(fill='x', padx=16, pady=(16, 4))
        tk.Label(self, text=f'{len(rows)} listing(s) within the next {UPCOMING_IPO_WINDOW_DAYS} days.',
                 font=_FONT_MD, bg=_CARD, fg=_SUBTEXT, anchor='w').pack(fill='x', padx=16, pady=(0, 10))

        list_wrap = tk.Frame(self, bg=_CARD)
        list_wrap.pack(fill='both', expand=True, padx=16)
        cols = ('Symbol', 'Board', 'Trade Date', 'D-1')
        tree = ttk.Treeview(list_wrap, columns=cols, show='headings', height=8)
        for c in cols:
            tree.heading(c, text=c)
            tree.column(c, anchor='center', width=100)
        for r in rows:
            key = f"{r['Symbol']}|{r['Trade Date']}"
            self._ack_keys.add(key)
            tree.insert('', 'end', values=(
                r['Symbol'], r.get('Board', ''),
                r['Trade Date'].strftime('%d %b %Y') if pd.notna(r['Trade Date']) else '—',
                r['D-1'].strftime('%d %b %Y') if pd.notna(r['D-1']) else '—',
            ))
        tree.pack(fill='both', expand=True)

        btn_row = tk.Frame(self, bg=_CARD)
        btn_row.pack(fill='x', padx=16, pady=14)
        tk.Button(btn_row, text='Remind me later', command=self._later,
                  bg=_PANEL, fg=_TEXT, relief='flat', font=_FONT_MD,
                  cursor='hand2').pack(side='left', expand=True, fill='x', padx=(0, 6))
        tk.Button(btn_row, text='Got it', command=self._dismiss,
                  bg=_ACCENT, fg=_BTN_TEXT, relief='flat', font=_FONT_H2,
                  cursor='hand2').pack(side='left', expand=True, fill='x')

    def _dismiss(self):
        ack = _load_ipo_ack()
        ack |= self._ack_keys
        _save_ipo_ack(ack)
        self.destroy()

    def _later(self):
        self.destroy()


class V2SplashScreen(tk.Toplevel):
    """Borderless loading screen shown while the very first data build
    runs. The IW (Index Warrant) engine's KLCI fetch is the single
    heaviest step in that first build, so this exists mainly to cover
    that wait with something better than a frozen-looking window."""
    def __init__(self, parent):
        super().__init__(parent)
        self.overrideredirect(True)
        self.configure(bg=_PANEL)
        w, h = 460, 220

        def _center():
            # Recompute and re-apply on every call — a borderless
            # (overrideredirect) Toplevel's very first geometry() can be
            # silently ignored by the window manager, especially right
            # after the parent was withdraw()n, leaving the splash
            # pinned at (0,0) in the corner of the screen instead of the
            # centered position this math actually requests. Calling
            # this twice — once immediately, once after the window has
            # had a chance to realize via update_idletasks() — makes the
            # second call land after the WM has actually mapped the
            # window, so the position sticks.
            sw = self.winfo_screenwidth()
            sh = self.winfo_screenheight()
            sx = (sw - w) // 2
            sy = (sh - h) // 2
            self.geometry(f'{w}x{h}+{sx}+{sy}')

        self.update_idletasks()
        _center()
        self.attributes('-topmost', True)

        frame = tk.Frame(self, bg=_PANEL, highlightbackground=_ACCENT,
                          highlightthickness=1)
        frame.pack(fill='both', expand=True)

        tk.Label(frame, text='📈  MYIPO Index Dashboard', font=_FONT_H1,
                 bg=_PANEL, fg=_TEXT).pack(pady=(30, 6))
        tk.Label(frame, text='Loading market data, indices & warrant pricing…',
                 font=_FONT_SM, bg=_PANEL, fg=_SUBTEXT).pack(pady=(0, 18))

        self.progress = ttk.Progressbar(frame, mode='indeterminate', length=340)
        self.progress.pack(pady=(0, 14))
        self.progress.start(12)

        self.status_var = tk.StringVar(value='Starting up…')
        tk.Label(frame, textvariable=self.status_var, font=_FONT_SM, bg=_PANEL,
                 fg=_SUBTEXT, wraplength=400, justify='center').pack(padx=16)

        # Re-apply once more after the window has actually been mapped —
        # this is the call that wins against the WM's own placement.
        self.update_idletasks()
        _center()
        self.after(50, _center)

    def set_status(self, msg):
        try:
            self.status_var.set(str(msg))
        except Exception:
            pass

    def close(self):
        try:
            self.progress.stop()
            self.destroy()
        except Exception:
            pass


class MYIPODashboardApp(tk.Frame):
    """Data/engine controller for the platform features (Futures, Options,
    0DTE, IW/DLC, Wealth, FD, PTS ...). It has NO window chrome of its own:
    no header, no nav bar, no theme switch. Each feature page is a regular
    tab of the PAA notebook (PAA's look, PAA's tab bar, PAA's status bar),
    parented to host._v2_tab_frames[name]. This hidden frame only owns the
    shared state and background jobs. Created lazily on the first visit to
    any of those tabs; same process, K-ID session and Cr wallet as PAA."""

    PAGES = ('Dashboard', 'Portfolio', 'Wealth', 'Invest', 'Indices', 'Companies', 'Search', 'IW', 'DLC', 'Options',
             '0DTE', 'Futures', 'FD', 'PTS', 'Coming Soon', 'Analytics', 'Settings')

    def __init__(self, master=None, host=None, initial_page='Dashboard'):
        # No standalone access: only constructible by the signed-in PAA app.
        if master is None or host is None or not (CURRENT_KID or '').strip():
            raise RuntimeError('Platform v2 is part of the signed-in PAA app '
                               '(no standalone access).')
        self._v2_after_ids = set()          # tracked so destroy() can cancel them
        super().__init__(master, bg=_BG)
        self.host = host                    # the main MYIPOApp
        # PAA's own status bar + a toolbar rebuild button stand in for the
        # old v2 header.
        self.status_var = host.status_var
        self.refresh_btn = host._v2_rebuild_btn
        self.refresh_price_btn = host._v2_price_btn

        # Show a lightweight splash screen while the first data build (index
        # engine + ATH/ATL + IW pricing) runs in the background — the IW
        # engine's KLCI fetch in particular can take a few seconds on a cold
        # cache, so this covers that wait.
        self._splash = V2SplashScreen(self)
        self._splash_closed = False

        # Shared build state, populated by _rebuild()
        self.all_frames        = {}
        self.output_df         = None
        self.weights_snapshot  = {}
        self.board_map         = {}
        self.short_name_map    = {}
        self.future_ipos       = pd.DataFrame()
        self.pipeline_ipos     = pd.DataFrame()
        self.stock_price_df    = pd.DataFrame()
        self.delist_candidates = pd.DataFrame()
        self.df_listed         = pd.DataFrame()
        self.ath_alerts        = []
        self.atl_alerts        = []
        self.iw_snapshot       = {}
        # label -> {'zd_long','zd_short','zdl_long','zdl_short',
        # 'zdl_leverage', ..._closed flags} — today's Zero-Decay
        # certificate readings (see build_iw_zd_snapshot()).
        self.iw_zd_snapshot    = {}
        # label -> {'zd_long','zd_short','zdl_long','zdl_short'} pd.Series
        # — full daily-reset history per certificate, for the histochart
        # window (IWZDChartPopup).
        self.iw_zd_series      = {}
        # {N: [history contract records]} for every Top-N — populated on
        # first build (see _rebuild()).
        self.top_series_history = {}
        # label -> side ('zd_long'/'zd_short'/'zdl_long'/'zdl_short') ->
        # list of open position dicts: {'qty','entry_price','entry_date'}.
        # Persisted to disk (iw_zd_positions.json), same convention as
        # iw_positions — see save_iw_zd_positions()/load_iw_zd_positions().
        # New positions only allowed while _iw_zd_trading_allowed() is
        # True — i.e. either the overnight pre-order/live cycle is open
        # OR the underlying index's own market is currently live;
        # existing positions can still be closed any time.
        self.iw_zd_positions   = load_iw_zd_positions()
        # label -> side -> list of realized records once a position's
        # cycle reaches its 5:00 PM settlement — {'qty','entry_price',
        # 'settle_price','entry_date','settle_date','rv_paid','pl'}. RV
        # (Redemption Value = settle_price * qty) is paid out to the
        # buyer at settlement and the position closes automatically —
        # it does not linger in the open-positions list.
        self.iw_zd_realized    = load_iw_zd_realized()
        # label -> {'upper', 'lower', 'method'} — today's UL/DL for every
        # index, from index_limits_today() (see build_indices()). 'method'
        # is 'constituent' for MYIPO+ (precise, per-constituent band) or
        # 'generic' for every other index (±30% off its own prev close).
        self.index_limits      = {}
        # label -> (ul_series, dl_series) — full-history UL/DL band, for
        # plotting the ceiling/floor as lines across the whole chart
        # (MYIPO+'s precise band, or the generic ±30% one for everything
        # else). index_limits (above) only holds today's single value.
        self.index_limits_series = {}
        # label -> side ('call'/'put') -> list of open position dicts:
        #   {'qty', 'entry_price', 'entry_date', 'strike', 'ratio', 'cost'}
        # Persisted to disk (iw_positions.json) so a position survives an
        # app restart — see save_iw_positions()/load_iw_positions(). New
        # positions are blocked while that underlying's CB is locked (see
        # iw_snapshot[label]['cb_locked']); existing positions stay open
        # and can still be closed regardless of CB state.
        self.iw_positions      = load_iw_positions()
        # label -> side -> list of realized (closed) IW trade records —
        # {'qty','entry_price','exit_price','entry_date','exit_date','pl'}.
        # Written by IWTradePopup._close_selected() right before the open
        # position is deleted, so a closed trade — including one struck
        # under an older, since-superseded tranche — stays reviewable
        # afterward instead of vanishing with no trace. See
        # save_iw_realized()/load_iw_realized().
        self.iw_realized       = load_iw_realized()
        # label -> 'long'|'short' -> list of open futures position dicts
        # {'qty','entry_price','entry_date','margin_paid','mark',
        # 'mark_date','mtm_total'}. Persisted (futures_positions.json);
        # daily-settled by settle_futures_daily() during every rebuild —
        # see that function's docstring for the variation-margin
        # mechanic. self.futures_snapshot (built alongside all_frames
        # every rebuild) holds the current one-contract-per-label pricing.
        self.futures_positions = load_futures_positions()
        self.futures_realized  = load_futures_realized()
        self.futures_snapshot  = {}
        # label -> f'{tenor_days}|{strike}|{side}' -> list of open Options
        # Chain position dicts: {'qty','entry_price','entry_date','cost'}.
        # Persisted to disk (options_positions.json), same convention as
        # iw_positions — see save_options_positions()/load_options_positions().
        self.options_positions = load_options_positions()
        # symbol -> list of open equity position dicts:
        #   {'qty', 'entry_price', 'entry_date'} — plain long-only stock
        # holdings, bought/sold outright at the live/last price (no
        # leverage, no side, no settlement cycle). Persisted to disk
        # (stock_positions.json) — see save_stock_positions()/
        # load_stock_positions().
        self.stock_positions   = load_stock_positions()
        # symbol -> {'enabled', 'unit_qty', 'frequency', 'last_run'} —
        # standing DCA (Dollar-Cost Averaging) instructions: auto-buy a
        # fixed fractional unit qty (as low as DCA_MIN_UNIT = 0.01
        # shares) of that symbol every day/week/month the market is
        # open, no manual click needed each cycle. Persisted to disk
        # (dca_plans.json) — see save_dca_plans()/load_dca_plans().
        # Checked and auto-executed once per _on_data_refresh cycle via
        # _run_due_dca_plans() below.
        self.dca_plans         = load_dca_plans()
        self._building         = False
        self._last_build_time  = None
        self._current_page     = initial_page

        # Live Ping — periodic lightweight quote check on the selected
        # index's top constituents (by weight), giving a "last movement"
        # read between full rebuilds without re-running the whole index
        # engine. Defaults to MYIPO+ until the user picks another index
        # from the Live Pulse selector.
        self.live_pulse = {'chg_pct': None, 'ts': None, 'ok': False}
        self.live_pulse_index = 'MYIPO+'
        self._live_ping_stop = False

        self.pages = {}
        self._build_pages()
        self.show_page(initial_page)
        self.after(300, self._initial_build)
        # Background Wealth Pack cash sweep — every 60s, regardless of
        # which page (if any) is open. Without this, stray cash parked
        # while a ticker's market was 'wait' only got reinvested next
        # time something happened to call _compute_pack_current_units
        # for that pack — a manual Rebuild click, or that one pack's own
        # detail page being open with its per-pack 'Live price' checkbox
        # ticked. A market flipping from closed to live at, say, 9:00am
        # did nothing on its own if nobody was looking at that pack right
        # then. get_wealth_packs_total_value(force=True) already calls
        # _compute_pack_current_units for every pack as a side effect of
        # computing net worth — reusing that here (silently; the return
        # value isn't needed) is what actually makes "buy at the time
        # the market opens" true rather than "buy next time someone
        # happens to check."
        self.after(5_000, self._wealth_sweep_tick)

    def _wealth_sweep_tick(self):
        try:
            get_wealth_packs_total_value(self, force=True)
        except Exception:
            pass
        finally:
            self.after(60_000, self._wealth_sweep_tick)
        self._start_live_ping()

    def _close_splash(self):
        if not self._splash_closed:
            self._splash_closed = True
            if self._splash is not None:
                self._splash.close()
                self._splash = None

    # ── Housekeeping ───────────────────────────────────────────────────
    def after(self, ms, func=None, *args):
        aid = tk.Misc.after(self, ms, func, *args)
        if func is not None and aid:
            self._v2_after_ids.add(aid)
        return aid

    def destroy(self):
        self._live_ping_stop = True
        for aid in list(self._v2_after_ids):
            try:
                self.after_cancel(aid)
            except Exception:
                pass
        super().destroy()

    _PAGE_CLASSES = (
        ('Dashboard', 'DashboardPage'), ('Portfolio', 'PortfolioPage'),
        ('Wealth', 'WealthManagementPage'), ('Invest', 'DirectInvestingPage'),
        ('Indices', 'IndicesPage'), ('Companies', 'CompaniesPage'),
        ('Search', 'TickerSearchPage'), ('IW', 'IWSearchPage'),
        ('DLC', 'IWZDSearchPage'), ('Options', 'OptionsChainPage'),
        ('0DTE', 'ZeroDTEPage'), ('Futures', 'FuturesSearchPage'),
        ('FD', 'FDPage'), ('PTS', 'PredictionMarketPage'),
        ('Analytics', 'AnalyticsPage'),
    )

    def _build_pages(self):
        """Each page is a plain tab of the PAA notebook (pages still build
        their widgets lazily, on first show)."""
        g = globals()
        for name, cls in self._PAGE_CLASSES:
            page = g[cls](self.host._v2_tab_frames[name], self)
            page.pack(fill='both', expand=True)
            self.pages[name] = page

    def show_page(self, name):
        """Cross-page links (e.g. 'open IW') just select that PAA tab."""
        if name == 'Coming Soon':           # PAA's own IPO Coming Soon tab
            self.host.notebook.select(self.host.tab_coming)
            return
        tab = self.host._v2_tab_frames.get(name)
        if tab is None or name not in self.pages:
            return
        self._current_page = name
        if self.host.notebook.select() == str(tab):
            self.pages[name].on_show()      # already showing: just refresh
        else:
            self.host.notebook.select(tab)  # tab-change handler runs on_show()

    def set_theme(self, name):
        """Platform pages follow PAA's look — there is no separate theme."""
        return

    # -------------------------------------------------------- build/log
    def _log(self, msg):
        def _do():
            # Batched multi-line log entries (ATH/ATL/IW sections) carry
            # embedded newlines for the log box, but the one-line status
            # bar and splash screen should only ever show the headline.
            headline = str(msg).split('\n', 1)[0]
            self.status_var.set(headline)
            if 'Dashboard' in self.pages:
                self.pages['Dashboard'].append_log(msg)
            if self._splash is not None:
                self._splash.set_status(headline)
        self.after(0, _do)

    def _initial_build(self):
        self._rebuild()

    def _rebuild(self):
        if self._building:
            return
        self._building = True
        self.refresh_btn.configure(state='disabled', text='Building…')

        def worker():
            try:
                result = build_indices(TEET_CSV_PATH, log_cb=self._log, prefer_online=True)
                (all_frames, output_df, weights_snapshot, board_map, short_name_map,
                 future_ipos, stock_price_df, delist_candidates, df_listed,
                 ath_alerts, atl_alerts, iw_snapshot, index_limits_snapshot,
                 index_limits_series, iw_zd_snapshot, iw_zd_series,
                 top_series_history, pipeline_ipos) = result
                self.all_frames        = all_frames
                _futures_today = pd.Timestamp((datetime.now(MALAYSIA_TZ) if MALAYSIA_TZ
                                                else datetime.now()).date()).as_unit('s')
                self.futures_snapshot  = build_futures_snapshot(all_frames, _futures_today)
                settle_futures_daily(self.futures_snapshot, _futures_today)
                settle_stock_pending_orders(self)
                settle_wealth_pack_dividends(self)
                check_wealth_pending_fills(self)
                pts_generate_markets(self)
                pts_resolve_due_markets(self)
                self.output_df         = output_df
                self.weights_snapshot  = weights_snapshot
                self.board_map         = board_map
                self.short_name_map    = short_name_map
                self.future_ipos       = future_ipos
                self.pipeline_ipos     = pipeline_ipos
                self.stock_price_df    = stock_price_df
                self.delist_candidates = delist_candidates
                self.df_listed         = df_listed
                self.ath_alerts        = ath_alerts
                self.atl_alerts        = atl_alerts
                self.iw_snapshot       = iw_snapshot
                self.iw_zd_snapshot    = iw_zd_snapshot
                self.iw_zd_series      = iw_zd_series
                # {N: [history contract records]} for every Top-N in
                # TOP_SERIES_LABELS — each record has 'date'/'in'/'out'/
                # 'constituents' for the Who's In/Who's Out board.
                self.top_series_history = top_series_history
                self.index_limits      = index_limits_snapshot
                self.index_limits_series = index_limits_series
                self._last_build_time  = datetime.now(MALAYSIA_TZ) if MALAYSIA_TZ else datetime.now()
                self._log(f'✅ Build complete — {len(all_frames)} indices ready.')

                flashy = [a for a in (ath_alerts + atl_alerts) if a.get('flashy')]
                if flashy:
                    def _notify_ath():
                        lines = [f"{a['symbol']} ({a['name']}): {a['price']:.3f} "
                                 f"({a['tier']} {'high' if a['pct_vs_ref'] >= 0 else 'low'}, "
                                 f"day {a['day_chg_pct']:+.2f}%)"
                                 for a in flashy[:8]]
                        messagebox.showinfo(
                            '🔥 Flashy ATH/ATL Alert',
                            'Fresh high/low with a strong same-day move:\n\n' + '\n'.join(lines))
                    self.after(0, _notify_ath)
            except Exception as exc:
                self._log(f'❌ Build failed: {exc}')
            finally:
                def _done():
                    self.refresh_btn.configure(state='normal', text='⟳  Rebuild Platform')
                    self._building = False
                    self._run_due_dca_plans()
                    for page in self.pages.values():
                        page.on_data_refresh()
                    self._close_splash()
                    self._maybe_show_ipo_popup()
                self.after(0, _done)

        threading.Thread(target=worker, daemon=True).start()

    def _refresh_price(self):
        """Manual 'just get fresh prices' button — separate from
        Rebuild. Pings live quotes (bypassing the LIVE_PING_INTERVAL
        cache for this one pass) and re-renders every already-built
        page off them, but never touches all_frames/output_df/
        stock_price_df/df_listed/etc. — those only change via a real
        Rebuild (build_indices()). Safe to spam; a Rebuild or another
        refresh already in flight makes this a no-op."""
        if self._building or getattr(self, '_refreshing_price', False):
            return
        self._refreshing_price = True
        self.refresh_price_btn.configure(state='disabled', text='Refreshing…')

        def worker():
            # Every read below that's normally cached for
            # LIVE_PING_INTERVAL seconds — the basket pulse ping, the
            # index day H/L feed, and each page's own
            # fetch_live_underlying_quote(..., ttl=app.LIVE_PING_INTERVAL)
            # calls inside on_data_refresh() — treats its cache as
            # stale and re-pings live while this is 0, instead of
            # silently reusing whatever was last fetched within the
            # last minute. Restored once every page has redrawn.
            orig_ttl = self.LIVE_PING_INTERVAL
            self.LIVE_PING_INTERVAL = 0
            try:
                if self.weights_snapshot:
                    self._do_live_ping()
                    self._update_index_day_hilo()
            except Exception as exc:
                self._log(f'⚠️ Price refresh failed: {exc}')

            def _done():
                try:
                    for page in self.pages.values():
                        page.on_data_refresh()
                finally:
                    self.LIVE_PING_INTERVAL = orig_ttl
                    self.refresh_price_btn.configure(state='normal', text='💲  Refresh Price')
                    self._refreshing_price = False
                    self._log('💲 Prices refreshed.')
            self.after(0, _done)

        threading.Thread(target=worker, daemon=True).start()

    # -------------------------------------------------------------- DCA
    def _run_due_dca_plans(self):
        """Auto-executes every enabled DCA plan that's due today (see
        _dca_due()) — buys that symbol's configured fractional unit_qty
        (as low as DCA_MIN_UNIT, 0.01 shares) at the latest known close,
        through the exact same spend_cr()/stock_positions pipeline a
        manual Buy uses, then stamps last_run so it doesn't fire again
        until its next cycle. Called once per rebuild (see _rebuild's
        _done()) so every plan gets picked up on the freshest prices,
        with no separate timer of its own to manage."""
        if not self.dca_plans:
            return
        today = (datetime.now(MALAYSIA_TZ) if MALAYSIA_TZ else datetime.now()).date()
        changed_plans = False
        changed_positions = False
        for symbol, plan in self.dca_plans.items():
            if not plan.get('enabled') or not _dca_due(plan, today):
                continue
            price = None
            px = getattr(self, 'stock_price_df', None)
            if px is not None and symbol in getattr(px, 'columns', []):
                s = px[symbol].dropna()
                if not s.empty:
                    price = float(s.iloc[-1])
            if price is None:
                s = cache_get_prices(symbol, START_DATE_STR)
                if s is not None and not s.empty:
                    price = float(s.iloc[-1])
            if price is None or price <= 0:
                continue   # no price yet this cycle — try again next rebuild
            qty = max(float(plan.get('unit_qty', DCA_MIN_UNIT)), DCA_MIN_UNIT)
            ccy = _ccy_for_label(symbol)
            cost_native = price * qty
            cost_cr = underlying_to_cr(cost_native, ccy, direction='sell')
            result = spend_cr(cost_cr, ccy)
            today_str = today.strftime('%Y-%m-%d')
            if not result['success']:
                # Skip this cycle (insufficient Cr even across Trading +
                # Savings + FD overdraft) but still stamp last_run so a
                # 'daily' plan doesn't retry every few seconds — it'll
                # simply pick back up on its next scheduled date.
                plan['last_run'] = today_str
                plan['last_skip_reason'] = f"insufficient balance (short Cr {result['shortfall']:,.2f})"
                changed_plans = True
                continue
            self.stock_positions.setdefault(symbol, []).append({
                'qty': qty, 'entry_price': price, 'entry_date': today_str,
                'cost_cr': cost_cr, 'status': 'open', 'dca': True,
            })
            plan['last_run'] = today_str
            plan.pop('last_skip_reason', None)
            changed_plans = True
            changed_positions = True
        if changed_positions:
            save_stock_positions(self.stock_positions)
        if changed_plans:
            save_dca_plans(self.dca_plans)

    # ------------------------------------------------------ Live Ping
    LIVE_PING_INTERVAL = 60   # seconds between pings

    def _start_live_ping(self):

        def loop():
            while not self._live_ping_stop:
                try:
                    if _myr_live_window() and self.weights_snapshot:
                        self._do_live_ping()
                        self._update_index_day_hilo()
                except Exception:
                    pass
                for _ in range(self.LIVE_PING_INTERVAL):
                    if self._live_ping_stop:
                        return
                    time_module.sleep(1)

        threading.Thread(target=loop, daemon=True).start()

    def _do_live_ping(self):
        """Cheap 'is the index moving' check between full rebuilds: reads
        the currently-selected index's top-5 weighted constituents'
        latest quote vs previous close and reports a weighted average %
        move. Cached for LIVE_PING_INTERVAL so repeat calls (e.g.
        switching tabs) don't re-hit the network. Which index is pinged
        is user-selectable via self.live_pulse_index (Dashboard's Live
        Pulse dropdown)."""
        idx_label = self.live_pulse_index or 'MYIPO+'
        w_snap = self.weights_snapshot.get(idx_label)
        if w_snap is None or w_snap.empty:
            return
        top_syms = list(w_snap.head(5).items())  # [(symbol, weight), ...]

        total_w, weighted_chg, n_ok = 0.0, 0.0, 0
        for sym, wt in top_syms:
            cache_key = f'ping_{idx_label}_{sym}'
            cached = cache_get_live(cache_key, ttl=self.LIVE_PING_INTERVAL)
            if cached is not None:
                chg = cached
            else:
                try:
                    fi = yf.Ticker(sym).fast_info
                    last = fi.get('last_price') or fi.get('lastPrice')
                    prev = fi.get('previous_close') or fi.get('previousClose')
                    if not last or not prev:
                        continue
                    chg = (last - prev) / prev * 100.0
                    cache_set_live(cache_key, chg)
                except Exception:
                    continue
            weighted_chg += chg * float(wt)
            total_w += float(wt)
            n_ok += 1

        if total_w > 0 and n_ok > 0:
            pulse_chg = weighted_chg / total_w
            self.live_pulse = {'chg_pct': pulse_chg,
                                'ts': datetime.now(MALAYSIA_TZ) if MALAYSIA_TZ else datetime.now(),
                                'ok': True,
                                'index': idx_label}

            def _apply():
                dash = self.pages.get('Dashboard')
                if dash is not None:
                    dash.update_live_pulse(self.live_pulse)
            self.after(0, _apply)

    def set_live_pulse_index(self, label: str):
        """Called by the Dashboard's Live Pulse dropdown when the user
        picks a different index to track. Switches the pinged index and
        forces an immediate re-ping (off the LIVE_PING_INTERVAL cache)
        so the card doesn't sit showing the old index's stale % for up
        to a minute after the switch."""
        if not label or label == self.live_pulse_index:
            return
        self.live_pulse_index = label
        self.live_pulse = {'chg_pct': None, 'ts': None, 'ok': False}
        dash = self.pages.get('Dashboard')
        if dash is not None:
            dash.pulse_var.set('Waiting for ping…')
            dash.pulse_ts_var.set('')
            dash._pulse_label.configure(fg=_TEXT)
            dash._pulse_dot.configure(fg=_SUBTEXT)
        threading.Thread(target=self._do_live_ping, daemon=True).start()

    def _update_index_day_hilo(self):
        """Runs once a minute (piggy-backing on the live-ping loop) inside
        the 9:00-17:00 window. For every built index, derives a live level
        as last daily close * (1 + full-basket weighted % move), and folds
        that single reading into a running Today's-High/Today's-Low pair
        — resets fresh each calendar day, same convention as a real quote
        widget's daily H/L. This intentionally does NOT rebuild the
        per-minute candle chart (removed) — it only feeds the LTC/O/H/L/C
        strip on the Indices page with real, refreshing H/L instead of the
        two-point (prior close vs today) synthesis."""
        if not hasattr(self, '_index_day_hilo'):
            self._index_day_hilo = {}
        now_my = datetime.now(MALAYSIA_TZ) if MALAYSIA_TZ else datetime.now()
        today_key = now_my.strftime('%Y-%m-%d')

        for label, w_snap in (self.weights_snapshot or {}).items():
            if w_snap is None or w_snap.empty:
                continue
            total_w, weighted_chg, n_ok = 0.0, 0.0, 0
            for sym, wt in w_snap.items():
                cache_key = f'ping_{sym}'
                cached = cache_get_live(cache_key, ttl=self.LIVE_PING_INTERVAL)
                if cached is not None:
                    chg = cached
                else:
                    try:
                        fi = yf.Ticker(sym).fast_info
                        last = fi.get('last_price') or fi.get('lastPrice')
                        prev = fi.get('previous_close') or fi.get('previousClose')
                        if not last or not prev:
                            continue
                        chg = (last - prev) / prev * 100.0
                        cache_set_live(cache_key, chg)
                    except Exception:
                        continue
                weighted_chg += chg * float(wt)
                total_w += float(wt)
                n_ok += 1
            if total_w <= 0 or n_ok == 0:
                continue

            frame = self.all_frames.get(label)
            if frame is None or frame.empty or label not in frame.columns:
                continue
            base_series = frame[label].dropna()
            if base_series.empty:
                continue
            level = float(base_series.iloc[-1]) * (1 + (weighted_chg / total_w) / 100.0)

            entry = self._index_day_hilo.get(label)
            if entry is None or entry.get('date') != today_key:
                entry = {'date': today_key, 'high': level, 'low': level, 'last': level}
            else:
                entry['high'] = max(entry['high'], level)
                entry['low']  = min(entry['low'], level)
                entry['last'] = level
            self._index_day_hilo[label] = entry

        def _apply():
            idx_page = self.pages.get('Indices')
            if idx_page is not None:
                idx_page.refresh_ohlc_strip()
                idx_page.refresh_live_stats()
        self.after(0, _apply)

    def _on_close(self):
        self._live_ping_stop = True
        self.destroy()


    def _maybe_show_ipo_popup(self):
        """Surface a 'New IPO coming soon' popup for any upcoming listing
        (D-1 within UPCOMING_IPO_WINDOW_DAYS) the user hasn't already
        dismissed on a prior build/launch."""
        if self.future_ipos is None or self.future_ipos.empty:
            return
        now_my = datetime.now(MALAYSIA_TZ) if MALAYSIA_TZ else datetime.now()
        cutoff = pd.Timestamp(now_my.date()) + pd.Timedelta(days=UPCOMING_IPO_WINDOW_DAYS)
        soon = self.future_ipos[self.future_ipos['D-1'] <= cutoff].copy()
        if soon.empty:
            return
        ack = _load_ipo_ack()
        rows = []
        for _, row in soon.iterrows():
            key = f"{row['Symbol']}|{row['Trade Date']}"
            if key not in ack:
                rows.append(row)
        if not rows:
            return
        UpcomingIPOPopup(self, rows)


class BasePage(tk.Frame):
    """Common scaffold for every nav page."""
    def __init__(self, parent, app):
        super().__init__(parent, bg=_BG)
        self.app = app
        self._built = False

    def on_show(self):
        if not self._built:
            self.build()
            self._built = True
        self.on_data_refresh()

    def build(self):
        pass

    def on_data_refresh(self):
        pass


def _card(parent, **kw):
    f = tk.Frame(parent, bg=_CARD, **kw)
    return f


def _make_scrollable(parent, bg, width=None):
    """Builds a vertically-scrollable area: canvas + a real tk.Scrollbar
    (not ttk — ttk's default trough/thumb colors can end up nearly
    invisible against a dark theme, which is what made the old sidebar
    scrollbar look 'missing'). Returns (outer_frame, inner_frame) —
    build content inside inner_frame. Scrolls via wheel or by dragging
    the visible thumb."""
    outer = tk.Frame(parent, bg=bg)
    canvas = tk.Canvas(outer, bg=bg, highlightthickness=0,
                        width=width if width else None)
    scroll = tk.Scrollbar(outer, orient='vertical', command=canvas.yview,
                           width=14, bg=_CARD, troughcolor=bg,
                           activebackground=_ACCENT, bd=0,
                           highlightthickness=0, elementborderwidth=0)
    inner = tk.Frame(canvas, bg=bg)
    inner.bind('<Configure>', lambda e: canvas.configure(scrollregion=canvas.bbox('all')))
    win_kwargs = dict(anchor='nw')
    if width:
        win_kwargs['width'] = width
    canvas_win = canvas.create_window((0, 0), window=inner, **win_kwargs)
    if not width:
        canvas.bind('<Configure>', lambda e: canvas.itemconfigure(canvas_win, width=e.width))
    canvas.configure(yscrollcommand=scroll.set)
    canvas.pack(side='left', fill='both', expand=True)
    scroll.pack(side='right', fill='y')

    def _on_mousewheel(event):
        delta = event.delta
        if delta == 0:
            delta = 120 if getattr(event, 'num', None) == 4 else -120
        canvas.yview_scroll(int(-1 * (delta / 120)), 'units')
    def _bind_wheel(_e):
        canvas.bind_all('<MouseWheel>', _on_mousewheel)
        canvas.bind_all('<Button-4>', _on_mousewheel)
        canvas.bind_all('<Button-5>', _on_mousewheel)
    def _unbind_wheel(_e):
        canvas.unbind_all('<MouseWheel>')
        canvas.unbind_all('<Button-4>')
        canvas.unbind_all('<Button-5>')
    canvas.bind('<Enter>', _bind_wheel)
    canvas.bind('<Leave>', _unbind_wheel)

    return outer, inner


def _init_hover(ax):
    """Google-Finance-style hover rig for a line chart: a vertical guide
    line down to the axis, a highlighted dot on the line, and a solid
    tooltip box with the date/value. Returns a dict of the artists;
    _update_hover / _clear_hover drive them from a motion event."""
    vline = ax.axvline(0, color=_ACCENT, linewidth=0.8, linestyle='--',
                        alpha=0.6, visible=False, zorder=8)
    dot, = ax.plot([], [], 'o', color=_ACCENT, ms=6, visible=False,
                    zorder=10, markeredgecolor=_CARD, markeredgewidth=1.2)
    annot = ax.annotate(
        '', xy=(0, 0), xytext=(14, 14), textcoords='offset points',
        bbox=dict(boxstyle='round,pad=0.5', fc=_CARD, ec=_ACCENT, lw=1.2),
        fontsize=9, color=_TEXT, visible=False, zorder=11,
        ha='left', va='bottom')
    return {'vline': vline, 'dot': dot, 'annot': annot}


def _update_hover(hov, ax, canvas, series, event, value_fmt='{:,.2f}'):
    """Snaps the hover rig to the series point nearest the mouse and
    redraws. Returns True if something was drawn (caller can skip a
    redundant draw_idle if it wants)."""
    if series is None or len(series) == 0 or event.inaxes != ax or event.xdata is None:
        return _clear_hover(hov, canvas)
    try:
        xs = mdates.date2num(series.index.to_pydatetime())
    except Exception:
        return _clear_hover(hov, canvas)
    idx = int(np.argmin(np.abs(xs - event.xdata)))
    x_val, y_val = series.index[idx], series.iloc[idx]
    hov['vline'].set_xdata([xs[idx], xs[idx]])
    hov['vline'].set_visible(True)
    hov['dot'].set_data([xs[idx]], [y_val])
    hov['dot'].set_visible(True)
    hov['annot'].xy = (xs[idx], y_val)
    # Flip the box to the left of the point once we're in the right
    # half of the axes so it never runs off the chart edge.
    xlim = ax.get_xlim()
    frac = (xs[idx] - xlim[0]) / (xlim[1] - xlim[0]) if xlim[1] != xlim[0] else 0
    dx = -14 if frac > 0.6 else 14
    ha = 'right' if frac > 0.6 else 'left'
    hov['annot'].set_position((dx, 14))
    hov['annot'].set_ha(ha)
    hov['annot'].set_text(f'{x_val.strftime("%d %b %Y")}\n{value_fmt.format(y_val)}')
    hov['annot'].set_visible(True)
    canvas.draw_idle()
    return True


def _update_hover_multi(hov, ax, canvas, series, extra_series, event, value_fmt='{:,.2f}'):
    """Same hover rig as _update_hover, but the tooltip also lists any
    named `extra_series` (e.g. {'UL': ul_series, 'DL': dl_series}) read
    at the SAME nearest date as the primary series — each extra series
    is independently nearest-matched, so a shorter UL/DL history still
    shows its closest reading instead of being dropped."""
    if series is None or len(series) == 0 or event.inaxes != ax or event.xdata is None:
        return _clear_hover(hov, canvas)
    try:
        xs = mdates.date2num(series.index.to_pydatetime())
    except Exception:
        return _clear_hover(hov, canvas)
    idx = int(np.argmin(np.abs(xs - event.xdata)))
    x_val, y_val = series.index[idx], series.iloc[idx]
    hov['vline'].set_xdata([xs[idx], xs[idx]])
    hov['vline'].set_visible(True)
    hov['dot'].set_data([xs[idx]], [y_val])
    hov['dot'].set_visible(True)
    hov['annot'].xy = (xs[idx], y_val)
    xlim = ax.get_xlim()
    frac = (xs[idx] - xlim[0]) / (xlim[1] - xlim[0]) if xlim[1] != xlim[0] else 0
    dx = -14 if frac > 0.6 else 14
    ha = 'right' if frac > 0.6 else 'left'
    hov['annot'].set_position((dx, 14))
    hov['annot'].set_ha(ha)
    lines = [x_val.strftime("%d %b %Y"), value_fmt.format(y_val)]
    for name, extra in (extra_series or {}).items():
        if extra is None or len(extra) == 0:
            continue
        try:
            pos = extra.index.get_indexer([x_val], method='nearest')[0]
            if pos >= 0:
                lines.append(f'{name} {value_fmt.format(extra.iloc[pos])}')
        except Exception:
            continue
    hov['annot'].set_text('\n'.join(lines))
    hov['annot'].set_visible(True)
    canvas.draw_idle()
    return True


def _clear_hover(hov, canvas):
    if hov['annot'].get_visible():
        hov['vline'].set_visible(False)
        hov['dot'].set_visible(False)
        hov['annot'].set_visible(False)
        canvas.draw_idle()
    return False


def _mark_extreme_on_chart(ax, series):
    """If the latest point in `series` is a fresh all-time-high or
    all-time-low, circle it right on the chart — the same hand-drawn-
    style callout as marking a breakout on a screenshot: a red ellipse
    around the recent run plus an ATH/ATL tag, drawn after the axes'
    x/y limits are already set so the ellipse sizes correctly."""
    if series is None or len(series) < 3:
        return
    last_val = float(series.iloc[-1])
    last_ts  = series.index[-1]
    prior    = series.iloc[:-1]
    hist_max = float(prior.max())
    hist_min = float(prior.min())

    if last_val >= hist_max:
        tag, text_color = 'ATH', _GREEN
    elif last_val <= hist_min:
        tag, text_color = 'ATL', _RED
    else:
        return   # not currently sitting at a fresh extreme — nothing to mark

    from matplotlib.patches import Ellipse
    import matplotlib.dates as _mdates

    ax.figure.canvas.draw()   # force a layout pass so xlim/ylim are final
    xlim, ylim = ax.get_xlim(), ax.get_ylim()
    x_span, y_span = (xlim[1] - xlim[0]), (ylim[1] - ylim[0])

    # Circle covers the last few percent of the series (the "run" into
    # the breakout), centered a little left of the very last point so
    # the print itself sits inside the loop rather than dead-center.
    tail_n  = max(2, int(len(series) * 0.04))
    tail    = series.tail(tail_n)
    cx      = _mdates.date2num(last_ts) - x_span * 0.035
    cy      = (float(tail.max()) + float(tail.min())) / 2.0
    width   = max(x_span * 0.11, x_span * 0.05)
    height  = max((float(tail.max()) - float(tail.min())) * 2.4, y_span * 0.10)

    ax.add_patch(Ellipse((cx, cy), width=width, height=height, fill=False,
                          edgecolor=_RED, linewidth=2.0, zorder=9,
                          alpha=0.9))
    ax.annotate(tag, xy=(_mdates.date2num(last_ts), last_val),
                xytext=(_mdates.date2num(last_ts) + x_span * 0.045, last_val + y_span * 0.06),
                textcoords='data', fontsize=9, fontweight='bold',
                color=text_color, zorder=10)


def _bursa_price_limits(ref_price: float):
    """Static & Dynamic price limits per Bursa Malaysia's actual current
    rules (reinstated 31 May 2021, still in force):
      Static  Price Limit: reference price ±30%  (±30 sen if ref < RM1.00)
      Dynamic Price Limit: reference price ±8%   (±8 sen  if ref < RM1.00)
    Static limits are the hard Upper/Lower Limit Price for the whole
    session; Dynamic limits are a continuously-enforced band around the
    last-done price (orders outside it are auto-rejected/need approval).
    Both are computed off the same `ref_price` here (previous close) for
    a simple end-of-day read — the live Dynamic band otherwise re-centers
    on every last-done print through the session.
    Returns a dict: static_upper, static_lower, dynamic_upper, dynamic_lower.
    """
    if ref_price is None or ref_price <= 0:
        return None
    if ref_price >= 1.00:
        static_upper  = ref_price * 1.30
        static_lower  = ref_price * 0.70
        dynamic_upper = ref_price * 1.08
        dynamic_lower = ref_price * 0.92
    else:
        static_upper  = ref_price + 0.30
        static_lower  = max(ref_price - 0.30, 0.01)
        dynamic_upper = ref_price + 0.08
        dynamic_lower = max(ref_price - 0.08, 0.01)
    return {
        'ref_price':      round(ref_price, 4),
        'static_upper':   round(static_upper, 4),
        'static_lower':   round(static_lower, 4),
        'dynamic_upper':  round(dynamic_upper, 4),
        'dynamic_lower':  round(dynamic_lower, 4),
    }


def _check_date_status(series: 'pd.Series', date_str: str):
    """Custom Date Checker — looks up the nearest available trading date
    to `date_str` and reports its value plus whether it was a fresh
    all-time/1-year/1-month high or low AS OF that date (i.e. using only
    the data available up to and including that date — the same "based
    on period" logic the live ATH/ATL detector uses, just replayed for a
    date the user picks instead of always 'today'). Returns a dict, or
    None if the date can't be parsed / there's no data to check against."""
    if series is None or series.empty:
        return None
    try:
        target = pd.Timestamp(date_str)
    except Exception:
        return None

    as_of = series[series.index <= target]
    if as_of.empty:
        return None
    actual_ts  = as_of.index[-1]
    value      = float(as_of.iloc[-1])
    prior      = as_of.iloc[:-1]

    day_chg = None
    if len(as_of) >= 2:
        prev = float(as_of.iloc[-2])
        if prev > 0:
            day_chg = (value - prev) / prev * 100.0

    if prior.empty:
        high_tier = low_tier = None
    else:
        hist_max, hist_min = float(prior.max()), float(prior.min())
        yr_max  = float(prior.tail(252).max())
        mo_max  = float(prior.tail(21).max())
        yr_min  = float(prior.tail(252).min())
        mo_min  = float(prior.tail(21).min())
        if value >= hist_max:
            high_tier = 'All-Time'
        elif value >= yr_max:
            high_tier = '1-Year'
        elif value >= mo_max:
            high_tier = '1-Month'
        else:
            high_tier = None
        if value <= hist_min:
            low_tier = 'All-Time'
        elif value <= yr_min:
            low_tier = '1-Year'
        elif value <= mo_min:
            low_tier = '1-Month'
        else:
            low_tier = None

    return {
        'requested_date': date_str,
        'actual_date':    actual_ts,
        'value':          value,
        'day_chg_pct':    day_chg,
        'high_tier':      high_tier,   # None / '1-Month' / '1-Year' / 'All-Time'
        'low_tier':       low_tier,
    }


def _update_hover_ohlc(hov, ax, canvas, bars, event, value_fmt='{:,.3f}'):
    """Same hover rig as _update_hover, but for OHLC candlestick bars —
    snaps to the nearest candle and shows O/H/L/C instead of a single
    value. bars is a list of (datetime, open, high, low, close) tuples."""
    if not bars or event.inaxes != ax or event.xdata is None:
        return _clear_hover(hov, canvas)
    xs = np.array([mdates.date2num(b[0]) for b in bars])
    idx = int(np.argmin(np.abs(xs - event.xdata)))
    dt, o, h, l, c = bars[idx]
    hov['vline'].set_xdata([xs[idx], xs[idx]])
    hov['vline'].set_visible(True)
    hov['dot'].set_data([xs[idx]], [c])
    hov['dot'].set_visible(True)
    hov['annot'].xy = (xs[idx], c)
    xlim = ax.get_xlim()
    frac = (xs[idx] - xlim[0]) / (xlim[1] - xlim[0]) if xlim[1] != xlim[0] else 0
    dx = -14 if frac > 0.6 else 14
    ha = 'right' if frac > 0.6 else 'left'
    hov['annot'].set_position((dx, 14))
    hov['annot'].set_ha(ha)
    date_str = dt.strftime('%d %b %Y %H:%M') if (dt.hour or dt.minute) else dt.strftime('%d %b %Y')
    hov['annot'].set_text(
        f'{date_str}\n'
        f'O {value_fmt.format(o)}  H {value_fmt.format(h)}\n'
        f'L {value_fmt.format(l)}  C {value_fmt.format(c)}')
    hov['annot'].set_visible(True)
    canvas.draw_idle()
    return True


def _pct_color(val):
    try:
        return _GREEN if float(val) >= 0 else _RED
    except Exception:
        return _TEXT


def _fmt_chg(chg_pct, points):
    """'+0.42% (+1.20 pts)' style combined change label — anti-overflow
    safe (fixed decimal places, no runaway string growth)."""
    try:
        pct_s = f'{float(chg_pct):+.2f}%'
    except Exception:
        pct_s = '—'
    try:
        pts_s = f'{float(points):+.2f} pts'
    except Exception:
        pts_s = '+0.00 pts'
    return f'{pct_s}  ({pts_s})'


def _truncate(text, max_chars):
    """Ellipsis-truncate any label text that could overflow a fixed-width
    card (long index names, long company names) instead of letting Tk
    silently clip or expand the widget."""
    text = str(text)
    return text if len(text) <= max_chars else text[:max_chars - 1].rstrip() + '…'


