class SavingsPopup(tk.Toplevel):
    """Deposit into / withdraw from the savings sub-balance. Cr above
    CR_AUTO_SAVE_THRESHOLD (10,000) sweeps in here automatically as it's
    earned (see _auto_sweep_to_savings) and accrues CR_AUTO_SAVE_RATE_PA
    (0.01% p.a.) daily; this window also lets the user move Cr either
    way manually. Opened by clicking the Savings tile on the Portfolio
    page."""

    def __init__(self, parent_page, app):
        super().__init__(parent_page)
        self.app = app
        self.amount_var = tk.StringVar(value='')
        self.configure(bg=_BG)
        self.geometry('380x360')
        self.title('Savings')
        self._build()
        self._refresh()

    def _build(self):
        head = _card(self)
        head.pack(fill='x', padx=10, pady=(10, 6))
        tk.Label(head, text='💰 Savings', font=_FONT_H1, bg=_CARD, fg=_TEXT,
                 anchor='w').pack(fill='x', padx=12, pady=(10, 2))
        tk.Label(head, text=f'Accrues {CR_AUTO_SAVE_RATE_PA:.2f}% p.a., credited daily.\n'
                             f'Cr above {CR_AUTO_SAVE_THRESHOLD:,.0f} in trading is swept '
                             f'in here automatically.',
                 font=_FONT_SM, bg=_CARD, fg=_SUBTEXT, anchor='w', justify='left',
                 wraplength=340).pack(fill='x', padx=12, pady=(0, 10))

        bal_card = _card(self)
        bal_card.pack(fill='x', padx=10, pady=6)
        self.trading_var = tk.StringVar(value='—')
        self.savings_var = tk.StringVar(value='—')
        for lbl, var in (('Trading Balance', self.trading_var), ('Savings Balance', self.savings_var)):
            row = tk.Frame(bal_card, bg=_CARD)
            row.pack(fill='x', padx=12, pady=4)
            tk.Label(row, text=lbl, font=_FONT_MD, bg=_CARD, fg=_SUBTEXT, anchor='w',
                     width=16).pack(side='left')
            tk.Label(row, textvariable=var, font=_FONT_MD, bg=_CARD, fg=_TEXT,
                     anchor='e').pack(side='right')

        move_card = _card(self)
        move_card.pack(fill='x', padx=10, pady=6)
        row = tk.Frame(move_card, bg=_CARD)
        row.pack(fill='x', padx=12, pady=(10, 6))
        tk.Label(row, text='Amount (Cr):', font=_FONT_MD, bg=_CARD, fg=_TEXT).pack(side='left')
        tk.Entry(row, textvariable=self.amount_var, font=_FONT_MD, width=14).pack(
            side='left', padx=(8, 0))
        btn_row = tk.Frame(move_card, bg=_CARD)
        btn_row.pack(fill='x', padx=12, pady=(0, 10))
        tk.Button(btn_row, text='Deposit →', command=self._deposit, bg=_ACCENT, fg=_BTN_TEXT,
                  relief='flat', font=_FONT_MD, cursor='hand2').pack(side='left')
        tk.Button(btn_row, text='← Withdraw', command=self._withdraw, bg=_PANEL, fg=_TEXT,
                  relief='flat', font=_FONT_MD, cursor='hand2').pack(side='left', padx=(8, 0))

    def _amount(self):
        try:
            amt = float(self.amount_var.get())
            if amt <= 0:
                raise ValueError
            return amt
        except ValueError:
            messagebox.showinfo('Savings', 'Enter a valid positive amount.')
            return None

    def _deposit(self):
        amt = self._amount()
        if amt is None:
            return
        result = deposit_to_savings(amt, 'USD')
        if not result['success']:
            messagebox.showwarning('Savings', 'Trading balance can\'t cover that amount.')
        self._refresh()
        self._notify_cr_balance_changed()

    def _withdraw(self):
        amt = self._amount()
        if amt is None:
            return
        result = withdraw_from_savings(amt, 'USD')
        if not result['success']:
            messagebox.showwarning('Savings', 'Savings balance can\'t cover that amount.')
        self._refresh()
        self._notify_cr_balance_changed()

    def _refresh(self):
        self.trading_var.set(fmt_cr(get_cr_balance()))
        self.savings_var.set(fmt_cr(get_savings_balance('USD')))

    def _notify_cr_balance_changed(self):
        dash = self.app.pages.get('Dashboard') if hasattr(self.app, 'pages') else None
        if dash is not None:
            dash._update_cr_balance_labels()


class LendingPopup(tk.Toplevel):
    """Borrow Cr as trading leverage against total assets (trading +
    savings + active FD principal). No hard cap — accrues a flat
    LENDING_RATE_PA on the whole outstanding balance, any size. principal. Realized profit
    (any positive apply_cr_delta) is applied against this balance first,
    automatically, before it reaches trading/savings — see
    repay_lending_from_profit(). A manual "← Repay" is also available to
    pay it down on demand straight out of the trading balance — see
    repay_lending_manual(). Status shows 'lending' while a balance is
    outstanding and flips to 'paid' the moment it's cleared, either way.
    Opened by clicking the Lending tile on the Portfolio page."""

